class NotMeasured(RuntimeError):
    """Корень населения не прочитан — третий исход, а не пустая перепись."""


def _utcnow() -> dt.datetime:
    return dt.datetime.now(dt.timezone.utc)


def const_value(node: ast.AST) -> Optional[str]:
    """Нормализованный исходник значения — или ``None``, если оно не константно.

    Константным считается выражение без единого обращения наружу: ни вызова
    (кроме конструктора контейнера), ни имени, ни атрибута, ни подписки, ни
    f-строки, ни включения. `Path(__file__).resolve()` константой не является
    и сравнивать его с чужим `Path(...)` было бы сравнением ТЕКСТА, а не
    значения — отсюда корзина ``not_constant``, а не «различаются».
    """
    for sub in ast.walk(node):
        # Отдельной ветки на `ast.Call` здесь НЕТ, и это решение, а не пропуск:
        # у любого вызова функция есть либо имя, либо атрибут, либо лямбда — то
        # есть отвергается ветками ниже. Ветка на `Call` отвергала бы то же
        # самое на узел раньше, и батарея мутаций показала её выживающей:
        # неотличимая от умолчания проверка есть украшение, а не сторож.
        if isinstance(sub, ast.Name):
            if sub.id in _CONST_CTORS:
                continue
            return None
        if isinstance(sub, (ast.Attribute, ast.Subscript, ast.Lambda, ast.JoinedStr,
                            ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp,
                            ast.Await, ast.Starred)):
            return None
    try:
        return ast.unparse(node)
    except Exception:  # noqa: BLE001 — ast.unparse на экзотике
        return None


def toplevel_constants(tree: ast.Module) -> Dict[str, Optional[str]]:
    """Имена верхнего уровня и их значения (``None`` — значение не константно).

    Только верхний уровень: константа внутри функции никому не видна и второй
    копией правила быть не может.
    """
    out: Dict[str, Optional[str]] = {}
    for node in tree.body:
        if isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name):
                    out[target.id] = const_value(node.value)
        elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name) \
                and node.value is not None:
            out[node.target.id] = const_value(node.value)
    return out


def imported_modules(tree: ast.Module) -> set:
    """Полные имена модулей, которые файл ВВОЗИТ, включая форму `from pkg import mod`.

    Разбирать ввоз текстом нельзя: `from spa_core.backtesting.tier1 import
    monte_carlo` не содержит строки «spa_core.backtesting.tier1.monte_carlo»
    ни разу, и текстовое правило объявило бы такого сторожа НЕ достающим
    исполнителя — то есть выдумало бы находку ровно там, где сторож честно
    делегирует. Имя собирается из модуля и КАЖДОГО псевдонима: какой из них
    подмодуль, а какой — имя внутри модуля, по одному тексту не различить,
    поэтому в набор кладутся оба прочтения.
    """
    out: set = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                out.add(alias.name)
        elif isinstance(node, ast.ImportFrom):
            if not node.module:
                continue
            out.add(node.module)
            for alias in node.names:
                out.add(f"{node.module}.{alias.name}")
    return out


def reaches(source: str, imported: set, module_rel: str) -> bool:
    """Достаёт ли сторож исполнителя ХОТЬ ОДНОЙ из четырёх дверей.

    Дверь опознаётся по тому, что исполнитель НАЗВАН, а не по форме зова:

    * ввоз — разбором AST (`imported_modules`), а не текстом;
    * загрузка по ПУТИ (`spec_from_file_location`, `SourceFileLoader`) — путь
      модуля стоит строковым литералом;
    * подпроцесс `python3 -m spa_core.x.y` — точечное имя стоит литералом;
    * `sys.path` + ввоз по короткому имени — тот же литерал.

    Проверять только `import` значило бы выдумать находку у теста, который
    честно зовёт исполнителя подпроцессом.
    """
    dotted = module_rel[:-3].replace("/", ".") if module_rel.endswith(".py") else module_rel
    if dotted in imported:
        return True
    return dotted in source or module_rel in source


def value_key(value: object) -> str:
    """Канонический ключ величины: у ЧИСЛА — его значение, у прочего — текст.

    Заведена замером цикла #651 (заказ G55 п. 1). До неё обе поверхности
    решения сверялись с находкой ТЕКСТОМ, и ответ на вопрос «кому принадлежит
    это число» зависел от того, как литерал НАПИСАН, а не сколько он равен:

    * `min_tvl_usd: float = 5_000_000` у RiskPolicy против `MIN_ELIGIBLE_TVL =
      5000000.0` у находки — одна величина, разные тексты (`'5000000'` против
      `'5000000.0'`), право чинить уходило МЛАДШЕЙ поверхности;
    * `kill_switch.hard_kill_pct: 10.0` у витрины против `MIN_ADAPTERS = 10` у
      находки — десятичная точка автора JSON решала, возразит ли владельцу
      кто-нибудь вообще.

    Замер 20.09 на живом дереве: девять пар меняют ответ (4 + 5). Ровно тот
    же класс, что ADR-431: свойство ПРИБОРА, выданное за свойство дерева.

    Нечисловая величина остаётся собой: сверка по строке объявила бы предметом
    владельца каждую пару со значением ``'v1.0'``, и обе поверхности держат
    только числа (:func:`is_numeric_value`).
    """
    text = str(value)
    try:
        return repr(float(text))
    except (TypeError, ValueError):
        return text


def declared_names(mapping: Dict[str, List[str]], value: object) -> List[str]:
    """Имена, под которыми поверхность решения объявила величину.

    Спрашивается СНАЧАЛА канонический ключ, потом сырой текст: второй нужен
    сцене, которая подаёт словарь руками, и величине, у которой числа нет
    вовсе. Объединять ответы нельзя — имя пришло бы дважды.
    """
    return mapping.get(value_key(value)) or mapping.get(str(value)) or []


def risk_policy_thresholds(root: Path) -> Dict[str, List[str]]:
    """Числовой порог RiskPolicy -> ВСЕ имена, под которыми он объявлен.

    Имён у одного числа бывает несколько, и называть первое попавшееся нельзя:
    замер 19.09 дал у ``0.05`` сразу три порога — `max_drawdown_stop`,
    `max_var_pct`, `min_cash_pct`. Первая редакция этой функции хранила одно
    имя и приписала бы `MIN_CASH` соседство со стоп-краном вместо буфера кэша,
    то есть соврала бы ровно тем способом, против которого написан весь прибор:
    равенство величины НЕ есть тождество смысла.

    Берутся и константы верхнего уровня, и умолчания полей (пороги живут
    полями датакласса `RiskConfig`, поэтому обходится ВЕСЬ модуль, а не
    `tree.body`). Только числа: порог есть величина, и строковая версия
    политики порогом не является — сверка по ней объявила бы предметом
    владельца каждую пару со значением ``'v1.0'``.

    Модуль не прочитан ⇒ ``NotMeasured``: молча решить, что совпадений с
    порогами нет, значило бы выдать «не измерено» за «чисто» и дать агенту
    право чинить то, что он чинить не вправе.
    """
    path = Path(root) / RISK_POLICY_MODULE
    try:
        tree = ast.parse(path.read_text(encoding="utf-8"))
    except Exception as exc:  # noqa: BLE001
        raise NotMeasured(
            f"пороги RiskPolicy не прочитаны ({RISK_POLICY_MODULE}): "
            f"{type(exc).__name__}: {exc}") from exc
    out: Dict[str, List[str]] = {}
    for node in ast.walk(tree):
        pairs: List[Tuple[str, ast.AST]] = []
        if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name) \
                and node.value is not None:
            pairs.append((node.target.id, node.value))
        elif isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name):
                    pairs.append((target.id, node.value))
        for name, value_node in pairs:
            if name.startswith("_"):
                continue
            if not (isinstance(value_node, ast.Constant)
                    and isinstance(value_node.value, (int, float))
                    and not isinstance(value_node.value, bool)):
                continue
            text = const_value(value_node)
            if text is None:
                continue
            key = value_key(text)   # `5_000_000` и `5000000.0` — одно число
            if name not in out.setdefault(key, []):
                out[key].append(name)
    return {value: sorted(names) for value, names in out.items()}


def subject_witness(text: str, module_rel: str) -> Optional[str]:
    """Называет ли ТЕКСТ файл `module_rel` — по имени модуля или по имени файла.

    Свидетель ОДНОСТОРОННИЙ и слабее двери из :func:`reaches`: упоминание
    исполнителя дверью к нему не является (ADR-417), но доказывает, что о
    чужой копии ЗНАЮТ. Ищется точечный хвост длиной от двух звеньев
    (``owner_queue.queue``) и имя файла (``baseanalytics_migration_summary.py``).

    Граница слева и справа обязательна: голое ``queue.py`` совпало бы внутри
    ``orchestrator_queue.py`` и выдумало бы свидетеля там, где назван СОСЕД.

    **У исполнителя из двух звеньев пути свидетель-хвост СОВПАДАЕТ с дверью**
    (``spa_core/e.py`` → ``spa_core.e``), и такая пара находкой быть перестаёт
    ещё в :func:`reaches` — до разбора форм. Свидетелем там остаётся только имя
    файла. Это не изъян: совпадение означает, что проводка уже есть.
    """
    if not module_rel.endswith(".py"):
        return None
    parts = module_rel[:-3].split("/")
    candidates = [f"{parts[-1]}.py"]
    candidates += [".".join(parts[-n:]) for n in range(2, len(parts) + 1)]
    for cand in candidates:
        if re.search(r"(?<![\w.])" + re.escape(cand) + r"(?![\w])", text):
            return cand
    return None


def artifact_literals(tree: ast.Module) -> set:
    """Имена файлов-артефактов, названные в файле строковым литералом.

    Берётся БАЗОВОЕ имя, а не путь: одна сторона пишет
    ``os.path.join(ROOT, "data", "paper_evidence.json")``, другая —
    ``"data/paper_evidence.json"``, и сравнение путей объявило бы их разными
    предметами там, где предмет один. Голый хвост (``".json"``) артефактом
    не является и отбрасывается — иначе предметом стала бы буква.
    """
    out: set = set()
    for node in ast.walk(tree):
        if not (isinstance(node, ast.Constant) and isinstance(node.value, str)):
            continue
        value = node.value
        if not value.lower().endswith(_ARTIFACT_SUFFIXES):
            continue
        name = value.replace("\\", "/").rsplit("/", 1)[-1]
        if name.startswith("."):        # сам хвост, имени файла нет
            continue
        out.add(name)
    return out


def key_literals(tree: ast.Module) -> set:
    """Строковые литералы, использованные как КЛЮЧ отображения.

    Три формы, и третья существенна: ``assert "adapters" in data`` есть
    обращение к ключу ровно в той же мере, что ``data["adapters"]``, и
    пропустить её значило бы не увидеть половину сторожей этого репозитория.

    Литерал, стоящий где попало (в сообщении об ошибке, в докстринге), ключом
    НЕ считается: свидетель обязан быть поведенческим, а не текстовым, иначе
    он вырождается в правило имени, уже измеренное как негодное (ADR-417).
    """
    out: set = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Subscript) and isinstance(node.slice, ast.Constant) \
                and isinstance(node.slice.value, str):
            out.add(node.slice.value)
        elif isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) \
                and node.func.attr in _KEY_METHODS and node.args \
                and isinstance(node.args[0], ast.Constant) \
                and isinstance(node.args[0].value, str):
            out.add(node.args[0].value)
        elif isinstance(node, ast.Compare) and len(node.ops) == 1 \
                and isinstance(node.ops[0], (ast.In, ast.NotIn)) \
                and isinstance(node.left, ast.Constant) \
                and isinstance(node.left.value, str):
            out.add(node.left.value)
    return out


def behaviour_witness(guard_text: str, executor_text: str) -> Tuple[Optional[dict],
                                                                    Optional[str]]:
    """ВТОРОЙ свидетель общего предмета — поведенческий (заказ G43, п. 1).

    Возвращает ``(свидетель | None, причина-не-измерено | None)``.

    Первый свидетель (:func:`subject_witness`) — ТЕКСТОВЫЙ: одна сторона
    называет другую. Он молчит о паре, где обе стороны честно работают с одним
    предметом и просто не знают друг о друге, — а это ровно случай
    ``tests/test_preflight.py`` × ``scripts/preflight_day1.py``: обе читают
    ``data/paper_evidence.json`` и обе спрашивают у него ключ ``start_date``.
    Заказ G43 потребовал поднять такие пары из «не измерено».

    Свидетельством считается пересечение СРАЗУ ПО ДВУМ осям: общий артефакт И
    общий ключ. Одной оси мало и это не осторожность, а замер: имя ``data/``
    стои́т у сотен файлов, и свидетель по одному артефакту объявил бы общим
    предметом любую пару, читающую репозиторий. Две оси оставляют предмет,
    у которого есть и носитель, и поле в нём.

    **Обратная сторона названа.** Пересечение НЕ доказывает, что ключ читается
    ИМЕННО из этого артефакта: статически связать их нечем, и прибор такой
    связи не выдумывает. Свидетель, как и первый, ОДНОСТОРОННИЙ — его наличие
    доказывает общий предмет, его отсутствие не доказывает ничего, и
    ``subject_unproven`` остаётся достижимым исходом (замер: из восьми пар
    свидетель нашёлся у двух).
    """
    try:
        guard_tree = ast.parse(guard_text)
        executor_tree = ast.parse(executor_text)
    except SyntaxError as exc:
        return None, f"сторона не разобрана: {type(exc).__name__}: {exc}"
    artifacts = sorted(artifact_literals(guard_tree) & artifact_literals(executor_tree))
    keys = sorted(key_literals(guard_tree) & key_literals(executor_tree))
    if not artifacts or not keys:
        return None, None
    return {"artifacts": artifacts, "keys": keys,
            "artifact": artifacts[0], "key": keys[0]}, None


def constant_is_loaded(tree: ast.Module, name: str) -> bool:
    """Читается ли имя хоть где-нибудь в файле (загрузка, не присваивание).

    Вопрос СТАТИЧЕСКИЙ, и отвечать на него прогоном нельзя: нечувствительность
    вердикта к значению — другое утверждение. Замер 19.09 разделил их ценой
    одной ошибки: пять пар были названы «константа не читается» по прогону, а
    читаются все пять (`random.Random(SEED)`, `for d in SCAN_DIRS`).

    Имя, которое НЕ читается, правилом на стороне сторожа не является вовсе —
    и это единственный честный способ снять пару с учёта.
    """
    for node in ast.walk(tree):
        if isinstance(node, ast.Name) and node.id == name \
                and isinstance(node.ctx, ast.Load):
            return True
    return False


def probe_key(row: dict) -> str:
    """Координата пары в журнале зонда. Значение входит в ключ НАМЕРЕННО."""
    return f"{row['guard']}|{row['executor']}|{row['name']}"


def load_probe_ledger(path: Path) -> Tuple[Dict[str, dict], Optional[str]]:
    """Журнал зонда независимости: ``(записи по координате, причина-нет | None)``.

    Перепись зонд не зовёт. Журнал устаревает САМ и устаревает в безопасную
    сторону: запись годится, только если совпали и значение находки, и sha
    ОБЕИХ сторон (проверяет :func:`_probe_verdict`). Любая правка любой из
    сторон отменяет вердикт зонда, и пара возвращается в ``subject_unproven``
    — то есть на учёт, а не с учёта. Расписания зонду поэтому не нужно:
    протухший журнал не молчит, он перестаёт отвечать.
    """
    try:
        import json
        doc = json.loads(Path(path).read_text(encoding="utf-8"))
    except OSError:
        return {}, f"журнала зонда нет ({path.name})"
    except Exception as exc:  # noqa: BLE001
        return {}, f"журнал зонда не прочитан: {type(exc).__name__}: {exc}"
    entries = doc.get("entries")
    if not isinstance(entries, list):
        return {}, "журнал зонда без перечня записей"
    out: Dict[str, dict] = {}
    for entry in entries:
        if isinstance(entry, dict) and isinstance(entry.get("key"), str):
            out[entry["key"]] = entry
    return out, None


def _sha256(path: Path) -> Optional[str]:
    import hashlib
    try:
        return hashlib.sha256(path.read_bytes()).hexdigest()
    except OSError:
        return None


def right_to_fix(value: object, *, thresholds: Dict[str, List[str]],
                 constitution: Dict[str, List[str]],
                 constitution_unread: Optional[str]) -> Tuple[
                     Optional[str], Optional[str], Dict[str, object]]:
    """ПРАВО чинить величину — одно правило на все три оси (заказ G54 п. 1).

    Возвращает ``(форма, основание, поля)``; ``(None, None, {})`` означает
    «ни одна объявленная поверхность решения этой величины не объявляла» —
    и только тогда ось вправе спрашивать о СПОСОБЕ починки.

    **Почему функция, а не ветка на месте.** До заказа G54 это правило жило
    в ДВУХ видах: первая и вторая оси знали одну поверхность решения (пороги
    `spa_core/risk/policy.py`), третья — две (плюс витрину порогов сайта).
    Прибор, который меряет вторые копии правил, держал вторую копию
    собственного правила — и ровно на ней публиковал «агенту никто не
    возражает» у 14 пар, чья величина объявлена витриной. Свести копии в одну
    здесь можно и должно: обе стороны — этот же модуль, право на правку у
    агента, и `single_copy_by_import` есть та самая форма починки, которую
    прибор прописывает другим.

    **Порядок ветвей существен.** Сначала пороги RiskPolicy: они остаются
    предметом №1 границы ADR-285 и старше витрины. Совпадение с ОБЕИМИ
    поверхностями не теряется — витрина называется полем
    ``also_constitution_fields``, потому что «число объявлено дважды» есть
    отдельный факт, а не оттенок первого.

    Витрина НЕ прочитана ⇒ :data:`REMEDY_RIGHT_UNMEASURED`, а не «совпадений
    нет» (инв. #17). Исключение ровно одно и оно не подмена: у величины,
    равной порогу RiskPolicy, право чинить УЖЕ установлено — вторая
    поверхность могла бы добавить причину, но отнять право не может.
    """
    owner_names = declared_names(thresholds, value)
    shelf_names = declared_names(constitution, value)
    if owner_names:
        named = ", ".join(f"`{n}`" for n in owner_names)
        evidence = (
            f"значение равно порог{'ам' if len(owner_names) > 1 else 'у'} "
            f"RiskPolicy {named} ({RISK_POLICY_MODULE}) — предмет №1 границы "
            f"ADR-285; какой из них ТОТ САМЫЙ, прибор не решает")
        extra: Dict[str, object] = {"owner_threshold_names": list(owner_names)}
        if shelf_names:
            extra["also_constitution_fields"] = list(shelf_names)
            evidence += (
                "; то же число объявлено и витриной порогов сайта пол"
                + ("ями " if len(shelf_names) > 1 else "ем ")
                + ", ".join(f"`{n}`" for n in shelf_names)
                + " — поверхностей решения ДВЕ, и умолчать о второй значило бы "
                  "выдать первую за полный ответ")
        elif constitution_unread is not None:
            extra["constitution_unread"] = constitution_unread
        return REMEDY_OWNER, evidence, extra
    if constitution_unread is not None:
        return REMEDY_RIGHT_UNMEASURED, constitution_unread, {}
    if shelf_names:
        return (REMEDY_CONSTITUTION,
                "то же число объявлено витриной порогов сайта пол"
                + ("ями " if len(shelf_names) > 1 else "ем ")
                + ", ".join(f"`{n}`" for n in shelf_names)
                + f" ({CONSTITUTION_FILE}) — род «решение», меняется только "
                  "ADR-ом; сводить копии ввозом агент не вправе",
                {"constitution_fields": list(shelf_names)})
    return None, None, {}


def is_numeric_value(value: object) -> bool:
    """Может ли витрина порогов вообще говорить об этой величине.

    Витрина и пороги RiskPolicy держат ТОЛЬКО числа — обе по одной причине:
    порог есть величина, и сверка по строке объявила бы предметом владельца
    каждую пару со значением ``'v1.0'``. Значит у пары со строковым значением
    ответ витрины пуст ПО ПОСТРОЕНИЮ, и складывать такие пары в знаменатель
    сдвига значило бы разбавлять замер вопросом, который никому не задавался.
    """
    try:
        float(str(value))
    except (TypeError, ValueError):
        return False
    return True


def classify_remedy(row: dict, *, guard_text: Optional[str],
                    executor_text: Optional[str],
                    thresholds: Dict[str, List[str]],
                    constitution: Dict[str, List[str]],
                    constitution_unread: Optional[str],
                    probe: Optional[dict] = None,
                    guard_loads: Optional[bool] = None) -> dict:
    """Форма починки одной находки (заказы G42 п. 1 и G43). Поля строки.

    Порядок ветвей — не стилистика: право чинить спрашивается раньше способа
    чинить. Пара, чью величину объявила поверхность решения, уходит владельцу
    ДО того, как прибор вообще посмотрит на свидетеля.

    **Поверхностей решения ДВЕ** (с заказа G54 п. 1): пороги RiskPolicy и
    витрина порогов сайта. Правило одно на три оси — :func:`right_to_fix`; до
    этого заказа здесь спрашивалась только первая, и разница была не
    умозрительной: на соседней оси 14 пар публиковались как «никто не
    возражает». Способ починки считается В ЛЮБОМ случае, и когда право
    перебивает способ, прежняя форма остаётся в строке полем
    ``remedy_without_shelf`` — сдвиг обязан быть виден, а не получен даром.

    Дальше порядок такой: **имя не читается · текстовый свидетель ·
    поведенческий свидетель · не доказан**. Первым идёт статический факт «имя
    у сторожа не читается ни разу», потому что он ОДИН снимает пару с учёта:
    правила на стороне сторожа нет вовсе, и спрашивать о свидетелях общего
    предмета уже не о чем.

    **Вердикты зонда в этом порядке НЕ участвуют** и кладутся полями (`drift`,
    `verdict_teeth`). Причина — замер, а не вкус: зонд отвечает на вопрос о
    ВРЕДЕ («поймают ли расхождение»), а не о предмете, и попытка прочесть его
    как ответ о предмете уже один раз сняла бы с учёта пять живых пар
    (ADR-419).
    """
    right, right_evidence, right_extra = right_to_fix(
        row.get("value"), thresholds=thresholds, constitution=constitution,
        constitution_unread=constitution_unread)
    method = _remedy_method(row, guard_text=guard_text,
                            executor_text=executor_text, probe=probe,
                            guard_loads=guard_loads)
    if right is None:
        return method
    out = {"remedy": right, "remedy_evidence": right_evidence, **right_extra}
    # Поля зонда — про ВРЕД, а не про предмет, и правом чинить не отменяются:
    # потерять `drift` при переходе к форме владельца значило бы погасить
    # наблюдение решением о том, кто вправе править.
    for key in ("drift", "drift_evidence", "verdict_teeth"):
        if key in method:
            out[key] = method[key]
    if right in _SHELF_REMEDIES and method["remedy"] != right:
        # СДВИГ формы починки, снятый строкой, а не пересказом (заказ G54 п. 1):
        # чем эта пара была, пока витрину не спрашивали. Сравнение идёт со
        # СТАРЫМ правилом, а не с «способом»: пара, равная порогу RiskPolicy,
        # была формой владельца и до заказа, и записывать ей сдвиг значило бы
        # приписать витрине чужую работу.
        out["remedy_without_shelf"] = method["remedy"]
    return out


def _remedy_method(row: dict, *, guard_text: Optional[str],
                   executor_text: Optional[str],
                   probe: Optional[dict] = None,
                   guard_loads: Optional[bool] = None) -> dict:
    """СПОСОБ починки — отдельно от ПРАВА (заказ G54 п. 1).

    Разделены они не ради опрятности: способ считается ВСЕГДА, в том числе у
    пары, которую право чинить уже отправило владельцу, — иначе сдвиг формы
    («чем пара была до вопроса витрине») пришлось бы домысливать, а заказ
    требовал его ИЗМЕРИТЬ.
    """
    if guard_text is None or executor_text is None:
        side = "guard" if guard_text is None else "executor"
        return {"remedy": REMEDY_UNREADABLE,
                "remedy_evidence": f"текст стороны `{side}` не прочитан повторно"}

    text_witness = subject_witness(guard_text, row["executor"])
    text_side = "guard"
    if text_witness is None:
        text_witness = subject_witness(executor_text, row["guard"])
        text_side = "executor"
    behaviour, behaviour_unmeasured = behaviour_witness(guard_text, executor_text)

    # Зонд НЕ снимает пару с учёта — ни одним своим вердиктом, и это поправка,
    # снятая замером. Заказ G43 предлагал считать «вердикт не изменился»
    # независимостью; замер показал, что так выглядит ВРЕД (расхождение не
    # будет поймано), а первая редакция этого прибора назвала тем же именем
    # нечувствительность вердикта и сняла бы с учёта пять пар, у которых
    # константа читается. Поэтому вклад зонда — ПОЛЕ строки (`drift`,
    # `verdict_teeth`), а снимает пару СТАТИЧЕСКИЙ факт: имя не читается.
    extra: Dict[str, object] = {}
    if probe is not None:
        verdict = probe.get("verdict")
        detail = probe.get("evidence") or "основание зонда не записано"
        if verdict in (PROBE_DRIFT_SILENT, PROBE_DRIFT_LOUD):
            extra = {"drift": verdict, "drift_evidence": detail}
        elif verdict == PROBE_INSENSITIVE:
            extra = {"verdict_teeth": "none", "drift_evidence": detail}

    if guard_loads is False:
        return {"remedy": REMEDY_UNUSED,
                "remedy_evidence": (
                    f"имя `{row['name']}` в стороже НЕ ЧИТАЕТСЯ ни разу "
                    f"(статический разбор) ⇒ правила на его стороне нет, и двух "
                    f"копий одного правила тоже нет"), **extra}

    if text_witness is not None:
        who = "сторож называет исполнителя" if text_side == "guard" \
            else "исполнитель называет сторожа"
        return {"remedy": REMEDY_IMPORT, "witness_side": text_side,
                "remedy_evidence": f"{who}: `{text_witness}`", **extra}
    if behaviour is not None:
        # Представитель НЕ единственный: общих артефактов и ключей бывает
        # много, и называть один, умолчав о числе, значило бы выдать пример
        # за весь свидетельский состав.
        return {"remedy": REMEDY_BEHAVIOUR, "witness_side": "behaviour",
                "behaviour_witness": behaviour,
                "remedy_evidence": (
                    f"обе стороны читают {len(behaviour['artifacts'])} общих "
                    f"артефакт(ов) и спрашивают {len(behaviour['keys'])} общих "
                    f"ключ(ей) — напр. `{behaviour['artifact']}` + "
                    f"`{behaviour['key']}`; общий предмет ДОКАЗАН поведением, "
                    f"дверь к исполнителю не проложена"), **extra}
    evidence = ("ни одна сторона не называет другую и общего артефакта с общим "
                "ключом у них нет — общий предмет НЕ ДОКАЗАН (это не «совпадение»)")
    if behaviour_unmeasured is not None:
        evidence = (f"текстового свидетеля нет; поведенческий НЕ ИЗМЕРЕН "
                    f"({behaviour_unmeasured})")
    return {"remedy": REMEDY_UNPROVEN, "remedy_evidence": evidence, **extra}


def _guard_files(root: Path) -> List[Path]:
    seen: set = set()
    out: List[Path] = []
    for sub in GUARD_DIRS:
        base = root / sub
        if not base.is_dir():
            continue
        for path in sorted(base.rglob("test_*.py")):
            if path in seen:
                continue
            seen.add(path)
            out.append(path)
    if not out:
        raise NotMeasured(f"в дереве {root} не нашлось ни одного файла-сторожа")
    return out


def _executor_files(root: Path) -> List[Path]:
    out: List[Path] = []
    for sub in EXECUTOR_DIRS:
        base = root / sub
        if not base.is_dir():
            raise NotMeasured(f"каталог исполнителей не прочитан: {base}")
        for path in sorted(base.rglob("*.py")):
            rel = path.relative_to(root).as_posix()
            if "/tests/" in f"/{rel}" or path.name.startswith("test_"):
                continue
            if any(rel.startswith(skip) for skip in _EXECUTOR_SKIP):
                continue
            if rel == PRODUCER:      # сам прибор исполнителем правил не является
                continue
            out.append(path)
    if not out:
        raise NotMeasured(f"в дереве {root} не нашлось ни одного файла-исполнителя")
    return out


def _probe_verdict(root: Path, row: dict, ledger: Dict[str, dict],
                   stats: dict) -> Optional[dict]:
    """Запись зонда для пары — ТОЛЬКО если она описывает СЕГОДНЯШНИЕ стороны.

    Годность проверяется тремя равенствами: значение находки и sha обоих
    файлов. Ошибиться эта проверка может лишь в одну сторону — объявить
    годную запись протухшей, — и пара тогда возвращается на учёт как
    ``subject_unproven``. Обратная ошибка (принять запись о ДРУГОМ дереве за
    ответ о сегодняшнем) закрыта: sha меняется от любой правки.
    """
    entry = ledger.get(probe_key(row))
    if entry is None:
        stats["missing"] += 1
        return None
    if entry.get("value") != row.get("value"):
        stats["stale"] += 1
        return None
    for side in ("guard", "executor"):
        if entry.get(f"{side}_sha") != _sha256(root / row[side]):
            stats["stale"] += 1
            return None
    if entry.get("verdict") not in _PROBE_VERDICTS:
        # Зонд честно не измерил пару — это НЕ вердикт и подставлять его
        # вместо вердикта нельзя.
        stats["missing"] += 1
        return None
    stats["fresh"] += 1
    return entry


def peer_pairs(declared: Dict[str, List[Tuple[str, Optional[str]]]], *,
               source_of, imports_of,
               thresholds: Dict[str, List[str]],
               constitution: Dict[str, List[str]],
               constitution_unread: Optional[str]) -> Tuple[List[dict], dict]:
    """Копия правила между двумя ИСПОЛНИТЕЛЯМИ (заказ G52 п. 1).

    ## Почему сужения ровно эти — это замер, а не вкус

    Перенести сюда правило соседней оси дословно нельзя: там пару удерживает
    АСИММЕТРИЯ сторон (сторож утверждает правило, исполнитель его применяет), а
    здесь стороны однородны, и одного имени с равным значением мало настолько
    же, насколько мало было его там. Замер на дереве ``072c418d3``:

    | сужение | пар |
    |---|---|
    | одно имя у двух исполнителей | **263 191** |
    | + имя объявлено РОВНО ДВУМЯ исполнителями | 615 имён |
    | + значение константно и равно | 225 |
    | + ни один не достаёт другого ни одной из четырёх дверей | **189** |

    Первая строка и есть соглашение об именовании: ``LOG_CAP`` объявлен
    столькими модулями, что пар по нему одному 14 028. Отсюда сужение №1 —
    ТОЧНЫЙ аналог правила «исполнитель у имени ровно один» соседней оси: имя,
    объявленное тремя и более исполнителями, одного правила не называет, и это
    своя корзина (``peer_many_executors``), а не находка и не «сошлось».

    ## Приватное имя здесь В НАСЕЛЕНИИ, и асимметрия названа

    Соседняя ось выбрасывает ``_`` -имена с основанием «приватное имя правилом
    наружу не является»: сторож чужое ``_X`` прочитать не может, значит парой
    одного правила они быть не могут. **Сюда это основание не переносится.**
    Два исполнителя, каждый со своим ``_T1_CAP = 0.4``, держат ровно две копии
    одного порога — невозможность прочитать чужое имя делает копию НЕИЗБЕЖНОЙ,
    а не мнимой. Меняется только форма починки: свести к ввозу без
    переименования нельзя. Числа поэтому печатаются врозь (замер: 46 приватных
    и 143 публичных), чтобы разницу правил было видно, а не выводить.

    ## Право чинить спрашивается первым

    Тот же порядок, что у соседней оси (заказ G42 п. 1): величина, равная
    ЧИСЛОВОМУ порогу RiskPolicy, есть предмет №1 границы ADR-285, и агент такую
    пару не чинит. Замер: **23** из 189, среди них ``MIN_ELIGIBLE_APY = 1.0`` и
    ``MAX_ELIGIBLE_APY = 30.0`` у двух модулей money-path. Сверка одностороння
    НАМЕРЕННО и ошибается в сторону «спросить»: равенство числа не есть
    тождество смысла (``SENTINEL = 0.0`` рядом с ``days_held`` — совпадение).

    ## Третий исход различим

    Исходник стороны не перечитан ⇒ вопрос о двери НЕ ИЗМЕРЕН
    (``peer_door_unmeasured``), а не «двери нет»: молчаливое «дверь закрыта»
    превратило бы нечитаемый файл в находку.
    """
    counts = {cls: 0 for cls in _PEER_CLASSES}
    rows: List[dict] = []
    for name, sides in declared.items():
        if len(sides) < 2:
            continue
        if len(sides) > 2:
            counts[CLASS_PEER_MANY] += 1
            continue
        (rel_a, val_a), (rel_b, val_b) = sides
        if val_a is None or val_b is None:
            counts[CLASS_PEER_NOT_CONSTANT] += 1
            continue
        if val_a != val_b:
            counts[CLASS_PEER_VALUE_DIFFERS] += 1
            continue
        src_a, src_b = source_of(rel_a), source_of(rel_b)
        if src_a is None or src_b is None:
            counts[CLASS_PEER_UNMEASURED] += 1
            rows.append({"verdict": CLASS_PEER_UNMEASURED, "name": name,
                         "value": val_a, "left": rel_a, "right": rel_b,
                         "reason": "исходник стороны не перечитан — вопрос о двери не измерен"})
            continue
        if (reaches(src_a, imports_of(rel_a), rel_b)
                or reaches(src_b, imports_of(rel_b), rel_a)):
            counts[CLASS_PEER_DELEGATES] += 1
            continue
        counts[CLASS_PEER_TWO_COPIES] += 1
        # Способ починки эта ось не разбирает вовсе, поэтому её «до витрины»
        # есть ровно одна форма — `subject_unproven`. Право чинить
        # спрашивается ТОЙ ЖЕ функцией, что и на двух других осях (G54 п. 1).
        right, right_evidence, right_extra = right_to_fix(
            val_a, thresholds=thresholds, constitution=constitution,
            constitution_unread=constitution_unread)
        method_evidence = (
            "ни одна сторона не достаёт другую — копия своя у обеих; "
            "общего происхождения значения прибор не доказывает")
        row = {
            "verdict": CLASS_PEER_TWO_COPIES,
            "name": name,
            "value": val_a,
            "left": rel_a,
            "right": rel_b,
            "private_name": name.startswith("_"),
            "remedy": right or REMEDY_UNPROVEN,
            "remedy_evidence": right_evidence or method_evidence,
            **right_extra,
        }
        if right in _SHELF_REMEDIES:
            row["remedy_without_shelf"] = REMEDY_UNPROVEN
        rows.append(row)
    rows.sort(key=lambda r: (r["left"], r["right"], r["name"]))
    return rows, counts


def constitution_values(root: Path) -> Tuple[Dict[str, List[str]], Optional[str]]:
    """Числа витрины порогов сайта -> ВСЕ поля, под которыми число объявлено.

    Возвращает ``(значения, причина_не_прочитано)``. Витрина отсутствует ⇒
    ПРИЧИНА, а не пустой словарь: пустой словарь сказал бы «совпадений нет», то
    есть выдал бы «не измерено» за «чинить можно». Отказом всей переписи это
    НЕ является намеренно — витрина лежит под ``landing/`` и в синтетическом
    дереве её может не быть по построению, в отличие от `spa_core/risk/policy.py`,
    без которого не измеряется само население.

    Берутся только ЧИСЛА (как и у порогов RiskPolicy): строковая метка витрины
    порогом не является, и сверка по ней объявила бы предметом владельца каждую
    пару со значением ``'v1.0'``.
    """
    path = Path(root) / CONSTITUTION_FILE
    try:
        doc = json.loads(path.read_text(encoding="utf-8"))
    except Exception as exc:  # noqa: BLE001
        return {}, (f"витрина порогов не прочитана ({CONSTITUTION_FILE}): "
                    f"{type(exc).__name__}: {exc}")
    out: Dict[str, List[str]] = {}

    def walk(node, path_parts: Tuple[str, ...]) -> None:
        if isinstance(node, dict):
            for key, value in node.items():
                walk(value, path_parts + (str(key),))
        elif isinstance(node, list):
            for i, value in enumerate(node):
                walk(value, path_parts + (f"[{i}]",))
        elif isinstance(node, (int, float)) and not isinstance(node, bool):
            field = ".".join(path_parts)
            key = value_key(node)   # `10` и `10.0` — одно число, а не два
            if field not in out.setdefault(key, []):
                out[key].append(field)

    walk(doc, ())
    return {value: sorted(names) for value, names in out.items()}, None



def declaring_paragraphs(text: str) -> List[List[Tuple[int, str]]]:
    """Абзацы правила, годные быть ОБЪЯВЛЕНИЕМ.

    Абзац — подряд идущие непустые строки. Слишком широкий или слишком длинный
    отбрасывается: строка реестра ADR несёт пересказ чужого документа и
    называет в себе всё подряд, поэтому связь «путь рядом с фразой» там не
    улика (:data:`MAX_DECLARING_LINE`, :data:`MAX_DECLARING_PARAGRAPH`).
    Отброшенные считаются и печатаются — иначе «не смотрели» стало бы
    неотличимо от «не нашли».
    """
    out: List[List[Tuple[int, str]]] = []
    current: List[Tuple[int, str]] = []
    for lineno, line in enumerate(text.splitlines(), 1):
        if line.strip():
            current.append((lineno, line))
            continue
        if current:
            out.append(current)
            current = []
    if current:
        out.append(current)
    return out


def _paragraph_admissible(block: List[Tuple[int, str]]) -> bool:
    return (len(block) <= MAX_DECLARING_PARAGRAPH
            and max(len(line) for _, line in block) <= MAX_DECLARING_LINE)


def _tree_paths(root: Path) -> List[str]:
    """Пути дерева, которыми разрешаются ОТНОСИТЕЛЬНЫЕ упоминания правил.

    Правило пишет `lib/constitution.json` и `governance/kill_switch.py` —
    хвост, а не путь от корня. Считать такое упоминание отсутствующим значило
    бы потерять объявление там, где оно есть; поэтому хвост разрешается по
    дереву и только при ЕДИНСТВЕННОМ совпадении. Неоднозначный хвост — свой
    исход, а не догадка о том, какой файл имели в виду.
    """
    out: List[str] = []
    for path in sorted(root.rglob("*")):
        if not path.is_file() or path.suffix not in (".py", ".json"):
            continue
        rel = path.relative_to(root).as_posix()
        if rel.startswith((".git/", "node_modules/", "landing/node_modules/")):
            continue
        out.append(rel)
    return out


def resolve_declared_path(raw: str, tree_paths: List[str],
                          root: Path) -> Tuple[Optional[str], str]:
    """Упоминание правила -> путь дерева (или причина, почему не вышло)."""
    if (root / raw).is_file():
        return raw, "прямой путь"
    tail = [rel for rel in tree_paths if rel.endswith("/" + raw)]
    if len(tail) == 1:
        return tail[0], f"хвост разрешён единственным совпадением ({tail[0]})"
    if not tail:
        return None, "названного файла в дереве нет"
    return None, f"хвост неоднозначен: {len(tail)} файл(ов) дерева"


def declared_surfaces(root: Path) -> Tuple[Dict[str, List[dict]], List[dict],
                                           int, int]:
    """Поверхности решения, ОБЪЯВЛЕННЫЕ правилами репозитория (заказ G55 п. 1).

    Возвращает ``(кандидаты, нечитаемые_тексты, отброшенных_абзацев,
    прочитанных_текстов)``. Последнее число — не украшение: «правил не
    прочитано ни одного» и «правила прочитаны, поверхностей не объявлено» —
    разные ответы, и выдать первый за второй значило бы объявить чистотой
    отсутствие наблюдения (инв. #17).
    Кандидат — путь, названный в абзаце правила вместе с языком ПРАВА
    ИЗМЕНЕНИЯ (:data:`AUTHORITY_MARKS`); у каждого хранится основание:
    файл правила, строка и сама цитата. Основание — часть находки, а не
    украшение: «прибор перечисляет» отличается от «автор знал» ровно тем, что
    на каждую строку населения можно посмотреть.

    Ни один текст правил не прочитан ⇒ пустой словарь И список причин; вердикт
    :data:`SURFACES_UNMEASURED` ставит уже :func:`decision_surfaces`.
    """
    texts: List[Path] = []
    rule_text = root / RULE_TEXT
    if rule_text.is_file():
        texts.append(rule_text)
    rules_dir = root / RULE_DIR
    if rules_dir.is_dir():
        texts.extend(sorted(rules_dir.glob("*.md")))
    tree_paths = _tree_paths(root)
    candidates: Dict[str, List[dict]] = {}
    unreadable: List[dict] = []
    skipped = 0
    read = 0
    for path in texts:
        rel_text = path.relative_to(root).as_posix()
        try:
            body = path.read_text(encoding="utf-8")
        except Exception as exc:  # noqa: BLE001
            unreadable.append({"text": rel_text,
                               "reason": f"{type(exc).__name__}: {exc}"})
            continue
        read += 1
        for block in declaring_paragraphs(body):
            if not _paragraph_admissible(block):
                skipped += 1
                continue
            joined = "\n".join(line for _, line in block).lower()
            if not any(mark in joined for mark in AUTHORITY_MARKS):
                continue
            for lineno, line in block:
                for match in _DECLARED_PATH_RE.finditer(line):
                    raw = match.group(1)
                    resolved, why = resolve_declared_path(raw, tree_paths, root)
                    key = resolved or raw
                    evidence = {
                        "text": rel_text,
                        "line": lineno,
                        "quote": line.strip()[:160],
                        "named_as": raw,
                        "resolution": why,
                        "resolved": resolved is not None,
                    }
                    if evidence not in candidates.setdefault(key, []):
                        candidates[key].append(evidence)
    return candidates, unreadable, skipped, read


def surface_numbers(root: Path, rel: str) -> Tuple[Optional[Dict[str, List[str]]],
                                                   str, Optional[str]]:
    """Числа объявленного кандидата: ``(значения, род, причина)``.

    Род решается ЗАМЕРОМ, а не расширением файла:

    * документ со штампом свежести — :data:`SURFACE_MEASUREMENT`: он сам
      свидетельствует, что его числа пересчитывает такт;
    * файл из каталогов предписанного прогона — :data:`SURFACE_GUARD`: сторож
      есть сторона, которую перепись СУДИТ, и власти над ней у него нет;
    * прочитанный шкаф чисел — :data:`SURFACE_SHELF`;
    * не разобран или отсутствует — два РАЗНЫХ исхода «не измерено».

    Ключи значений канонические (:func:`value_key`): иначе ответ поверхности
    зависел бы от того, поставил автор десятичную точку или нет.
    """
    if rel.startswith(tuple(d + "/" for d in GUARD_DIRS)):
        return None, SURFACE_GUARD, (
            "файл собирается предписанным прогоном как сторож — он сторона, "
            "которую перепись судит, а не поверхность решения")
    path = root / rel
    if not path.is_file():
        return None, SURFACE_ABSENT, "названного файла в дереве нет"
    try:
        body = path.read_text(encoding="utf-8")
    except Exception as exc:  # noqa: BLE001
        return None, SURFACE_UNREADABLE, f"{type(exc).__name__}: {exc}"
    out: Dict[str, List[str]] = {}
    if rel.endswith(".json"):
        try:
            doc = json.loads(body)
        except Exception as exc:  # noqa: BLE001
            return None, SURFACE_UNREADABLE, f"{type(exc).__name__}: {exc}"
        if isinstance(doc, dict):
            stamped = [s for s in FRESHNESS_STAMPS if s in doc]
            if stamped:
                return None, SURFACE_MEASUREMENT, (
                    "документ сам свидетельствует о такте пол"
                    + ("ями " if len(stamped) > 1 else "ем ")
                    + ", ".join(f"`{s}`" for s in stamped)
                    + " — числа рода ЗАМЕР, а не решение")

        def walk(node: object, parts: Tuple[str, ...]) -> None:
            if isinstance(node, dict):
                for key, value in node.items():
                    walk(value, parts + (str(key),))
            elif isinstance(node, list):
                for index, value in enumerate(node):
                    walk(value, parts + (f"[{index}]",))
            elif isinstance(node, (int, float)) and not isinstance(node, bool):
                field = ".".join(parts)
                key = value_key(node)
                if field not in out.setdefault(key, []):
                    out[key].append(field)

        walk(doc, ())
        return {k: sorted(v) for k, v in out.items()}, SURFACE_SHELF, None
    try:
        tree = ast.parse(body)
    except Exception as exc:  # noqa: BLE001
        return None, SURFACE_UNREADABLE, f"{type(exc).__name__}: {exc}"
    for node in ast.walk(tree):
        pairs: List[Tuple[str, ast.AST]] = []
        if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name) \
                and node.value is not None:
            pairs.append((node.target.id, node.value))
        elif isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name):
                    pairs.append((target.id, node.value))
        for name, value_node in pairs:
            if name.startswith("_"):
                continue
            if not (isinstance(value_node, ast.Constant)
                    and isinstance(value_node.value, (int, float))
                    and not isinstance(value_node.value, bool)):
                continue
            key = value_key(value_node.value)
            if name not in out.setdefault(key, []):
                out[key].append(name)
    return {k: sorted(v) for k, v in out.items()}, SURFACE_SHELF, None


def adr_channel(root: Path) -> dict:
    """ПОЧЕМУ нарратив ADR не считается объявлением — числом, а не словом.

    Заказ назвал «пороги в ADR» кандидатом в поверхности. Ответ замера: в
    абзацах ADR с языком права изменения путей много, и это пути ЗАМЕРОВ,
    помянутые рядом с фразой о владельце. Порог, объявленный ПРОЗОЙ, поля не
    имеет и сверять его не с чем; механизм самого репозитория для превращения
    решений ADR в читаемый шкаф — `scripts/build_site_constitution.py` →
    витрина порогов, которая в населении УЖЕ есть.

    Реестр `docs/decisions/INDEX.md` исключён отдельно и по измеренной
    причине: строка на ADR (поле `registry_long_lines`).
    """
    named: Dict[str, int] = {}
    files = 0
    for directory in ADR_DIRS:
        base = root / directory
        if not base.is_dir():
            continue
        for path in sorted(base.glob("*.md")):
            if path.relative_to(root).as_posix() == ADR_REGISTRY:
                continue
            try:
                body = path.read_text(encoding="utf-8")
            except Exception:  # noqa: BLE001
                continue
            files += 1
            for block in declaring_paragraphs(body):
                if not _paragraph_admissible(block):
                    continue
                joined = "\n".join(line for _, line in block).lower()
                if not any(mark in joined for mark in AUTHORITY_MARKS):
                    continue
                for _lineno, line in block:
                    for match in _DECLARED_PATH_RE.finditer(line):
                        raw = match.group(1)
                        named[raw] = named.get(raw, 0) + 1
    registry = root / ADR_REGISTRY
    long_lines = unreadable = None
    registry_lines = None
    if registry.is_file():
        try:
            rows = registry.read_text(encoding="utf-8").splitlines()
            registry_lines = len(rows)
            long_lines = len([r for r in rows if len(r) > MAX_DECLARING_LINE])
        except Exception as exc:  # noqa: BLE001
            unreadable = f"{type(exc).__name__}: {exc}"
    else:
        unreadable = "реестра нет в дереве"
    artifacts = len([p for p in named if p.startswith("data/")])
    return {
        "files": files,
        "named_paths": len(named),
        "artifact_paths": artifacts,
        "registry": ADR_REGISTRY,
        "registry_lines": registry_lines,
        "registry_long_lines": long_lines,
        "registry_unreadable": unreadable,
        "why_not_a_channel": (
            "нарратив называет путь РЯДОМ с фразой о праве владельца, а не "
            "объявляет его поверхностью; большинство названного — артефакты "
            "`data/`, то есть замеры. Порог в прозе ADR поля не имеет, и "
            "механизм репозитория для превращения решений в шкаф — витрина "
            "порогов, которая в населении уже есть"),
    }


def decision_surfaces(root: Path, rows: List[dict], *,
                      asked: Tuple[str, ...] = ASKED_SURFACES) -> dict:
    """Население поверхностей решения и СДВИГ у каждой (заказ **G55, п. 1**).

    Вопрос заказа дословно: «какие ещё файлы объявляют числа рода «решение» и
    сколько пар сменили бы форму у КАЖДОГО из них». Ответ — перепись, у
    которой каждая строка несёт основание (какое правило, какая строка, какая
    цитата), и число совпадений с находками всех трёх осей.

    **Две величины считаются отдельно, и смешивать их нельзя.**
    ``matches`` — сколько находок поверхность вообще называет; ``would_move``
    — сколько из них СЕГОДНЯ не имеют формы права чинить, то есть сколько
    агенту никто не возражает лишь потому, что эту поверхность не спрашивают.
    У поверхности, которую УЖЕ спрашивают, ``would_move`` равен нулю ПО
    ПОСТРОЕНИЮ, а ``matches`` — нет: он и есть доказательство, что мера
    кусается, а не молчит впустую (ровно тот вопрос, которым ADR-431 снял
    структурный ноль).

    **Спрашиваемые сегодня поверхности проверяются на объявленность.** Замер
    20.09: витрина порогов объявлена правилом `.claude/rules/site-numbers.md`
    прямой строкой, а `spa_core/risk/policy.py` этим каналом не объявлен:
    ПУТИ его в текстах правил нет вовсе.

    **Поправка замера 20.09 (заказ G56 п. 2), и она существенна.** Отсюда
    раньше следовал вывод «старшая поверхность решения не объявлена НИКЕМ и
    держится на знании автора прибора». Вывод был о КАНАЛЕ, а прочитывался как
    вывод о репозитории. Канал имени (:func:`name_channel`) нашёл объявление:
    ``Не менять `RiskConfig` пороги без ADR`` — `.claude/rules/risk-engine.md`,
    и `RiskConfig` разрешается в `spa_core/risk/policy.py` единственным
    определением верхнего уровня во всём дереве. Правила эту поверхность
    объявляют; их не видела мера. Чинить правило по-прежнему нельзя молча —
    оно предмет владельца в той же мере, что и число, — но утверждение
    «не объявлена никем» снято замером, а не мнением.
    """
    candidates, unreadable_texts, skipped, texts_read = declared_surfaces(root)
    channel = adr_channel(root)
    if texts_read == 0:
        # Ни одного текста правил: ни прочитанного, ни существующего. Это НЕ
        # «поверхностей не объявлено» — объявлять было негде, и разница здесь
        # ровно та, ради которой написан инв. #17.
        return {
            "verdict": SURFACES_UNMEASURED,
            "reason": ("ни один текст правил не прочитан — объявлять поверхности "
                       "было негде, и население НЕ ИЗМЕРЕНО"),
            "texts_read": 0,
            "texts_unreadable": unreadable_texts,
            "candidates": 0,
            "surfaces": [],
            "asked": [],
            "adr_channel": channel,
        }
    numeric_rows = [r for r in rows if is_numeric_value(r.get("value"))]
    right_forms = (REMEDY_OWNER, REMEDY_CONSTITUTION, REMEDY_RIGHT_UNMEASURED)
    surfaces: List[dict] = []
    by_kind: Dict[str, int] = {kind: 0 for kind in _SURFACE_KINDS}
    for rel in sorted(candidates):
        values, kind, reason = surface_numbers(root, rel)
        by_kind[kind] = by_kind.get(kind, 0) + 1
        row: dict = {
            "path": rel,
            "kind": kind,
            "declared_by": candidates[rel],
            "asked_today": rel in asked,
        }
        if values is None:
            row["reason"] = reason
            surfaces.append(row)
            continue
        matched = [r for r in numeric_rows
                   if value_key(r.get("value")) in values]
        moved = [r for r in matched if r.get("remedy") not in right_forms]
        row.update({
            "numbers": len(values),
            "matches": len(matched),
            "would_move": len(moved),
            "would_move_names": sorted({f"{r['name']} = {r['value']}"
                                        for r in moved}),
        })
        surfaces.append(row)
    shelves = [s for s in surfaces if s["kind"] == SURFACE_SHELF]
    unasked_moving = [s for s in shelves
                      if not s["asked_today"] and s.get("would_move")]
    biting = [s for s in shelves if s.get("matches")]
    if not numeric_rows:
        verdict = SURFACES_NOTHING_COMPARABLE
        reason = ("числовых находок нет вовсе — поверхностям нечего называть, "
                  "и это не «сдвига нет»")
    elif unasked_moving:
        verdict = SURFACES_SHIFT
        reason = (f"{len(unasked_moving)} объявленн(ая/ых) поверхност(ь/ей) "
                  f"решения не спрашивается, и её молчание даёт агенту право "
                  f"чинить {sum(s['would_move'] for s in unasked_moving)} пар(ы)")
    elif biting:
        verdict = SURFACES_NO_SHIFT
        reason = (f"из {len(shelves)} объявленных шкафов чисел ни один "
                  f"НЕспрашиваемый не называет ни одной находки; мера при этом "
                  f"кусается — спрашиваемые называют "
                  f"{sum(s['matches'] for s in biting)} строк(и)")
    else:
        verdict = SURFACES_NO_SHIFT
        reason = ("ни один объявленный шкаф не называет ни одной находки — "
                  "ноль ИЗМЕРЕН, но подтвердить укус этой мерой сегодня нечем")
    asked_rows = []
    for rel in asked:
        declared = candidates.get(rel)
        asked_rows.append({
            "path": rel,
            "declared_by_rules": bool(declared),
            "evidence": declared or [],
            "mentions_in_rules": _mentions_in_rules(root, rel),
        })
    return {
        "verdict": verdict,
        "reason": reason,
        "question": ("сколько в репозитории ОБЪЯВЛЕННЫХ поверхностей решения и "
                     "сколько пар сменили бы форму починки у каждой"),
        "channel": f"{RULE_TEXT} + {RULE_DIR}/*.md",
        "candidates": len(candidates),
        "by_kind": by_kind,
        "shelves": len(shelves),
        "numeric_rows": len(numeric_rows),
        "rows_total": len(rows),
        "would_move_total": sum(s["would_move"] for s in unasked_moving),
        "texts_read": texts_read,
        "paragraphs_skipped_wide": skipped,
        "texts_unreadable": unreadable_texts,
        "asked": asked_rows,
        "surfaces": surfaces,
        "adr_channel": channel,
        "blind": [
            "поверхность, не названную ни одним правилом, перепись не видит — "
            "число есть доказанный МИНИМУМ населения, а не потолок",
            "поверхность, объявленную ИМЕНЕМ КЛАССА, а не путём файла, ЭТА "
            "мера не видит по построению: ровно так объявлен `RiskConfig`, и "
            "ровно поэтому старшая поверхность системы в ЕЁ населении "
            "отсутствует; зазор измерен отдельной координатой `name_channel` "
            "(заказ G56 п. 2) и нулём не оказался",
            "совпадение величины не есть тождество смысла — `would_move` "
            "считает поводы СПРОСИТЬ, а не доказанные копии одного решения",
            "абзац, отброшенный как широкий (`paragraphs_skipped_wide`), эта "
            "мера не читает ПО ПОСТРОЕНИЮ; потолок того, что дало бы его "
            "чтение, измерен отдельной координатой `wide_paragraph_channel` "
            "(заказ G57 п. 1) и нулём не оказался — но и вердикта не двинул",
        ],
    }


def _mentions_in_rules(root: Path, rel: str) -> int:
    """Сколько раз путь вообще назван правилами — с маркером или без.

    Нужен ровно одному вопросу: объявление отсутствует потому, что в абзаце не
    было языка права изменения, или потому, что пути нет в правилах ВООБЩЕ?
    Это разные ответы, и второй сильнее.
    """
    total = 0
    texts = []
    if (root / RULE_TEXT).is_file():
        texts.append(root / RULE_TEXT)
    if (root / RULE_DIR).is_dir():
        texts.extend(sorted((root / RULE_DIR).glob("*.md")))
    for path in texts:
        try:
            body = path.read_text(encoding="utf-8")
        except Exception:  # noqa: BLE001
            continue
        total += len(re.findall(r"(?<![\w/.])" + re.escape(rel) + r"(?![\w])", body))
    return total


def toplevel_definitions(root: Path) -> Tuple[Dict[str, List[str]], int, List[dict]]:
    """Имя верхнего уровня -> файлы дерева, которые его определяют.

    Население файлов — ровно те два дерева рабочего кода и пять каталогов
    сторожей, которыми прибор уже пользуется (:data:`EXECUTOR_DIRS`,
    :data:`GUARD_DIRS`). Оно ОБЪЯВЛЕНО репозиторием, а не выбрано здесь, и это
    существенно: обход всего дерева подряд втянул бы вложенные рабочие копии
    (`.claude/worktrees/`, `attic/`), и тогда КАЖДОЕ имя оказалось бы
    неоднозначным — мера ответила бы о числе чужих чекаутов на диске вместо
    репозитория.

    Возвращает ``(индекс, прочитано_файлов, нечитаемые)``. Последнее — не
    украшение: «в дереве нет ни одного определения» и «ни один файл не
    разобран» суть разные ответы, и второй есть отсутствие наблюдения.
    """
    index: Dict[str, List[str]] = {}
    unreadable: List[dict] = []
    read = 0
    seen: set = set()
    for sub in EXECUTOR_DIRS + GUARD_DIRS:
        base = root / sub
        if not base.is_dir():
            continue
        for path in sorted(base.rglob("*.py")):
            rel = path.relative_to(root).as_posix()
            if rel in seen:
                continue
            seen.add(rel)
            try:
                tree = ast.parse(path.read_text(encoding="utf-8"))
            except Exception as exc:  # noqa: BLE001
                unreadable.append({"path": rel,
                                   "reason": f"{type(exc).__name__}: {exc}"})
                continue
            read += 1
            for node in tree.body:
                names: List[str] = []
                if isinstance(node, (ast.ClassDef, ast.FunctionDef,
                                     ast.AsyncFunctionDef)):
                    names.append(node.name)
                elif isinstance(node, ast.Assign):
                    names.extend(t.id for t in node.targets
                                 if isinstance(t, ast.Name))
                elif isinstance(node, ast.AnnAssign) and isinstance(node.target,
                                                                   ast.Name):
                    names.append(node.target.id)
                for name in names:
                    bucket = index.setdefault(name, [])
                    if rel not in bucket:
                        bucket.append(rel)
    for bucket in index.values():
        bucket.sort()
    return index, read, unreadable


def resolve_declared_name(raw: str,
                          index: Dict[str, List[str]]) -> Tuple[Optional[str],
                                                                str, str]:
    """Имя из текста правила -> путь дерева (или причина, почему не вышло).

    Зеркало :func:`resolve_declared_path` и отвечает по той же строгости: путь
    возвращается ТОЛЬКО при единственном определении. Имя, определённое
    многими файлами (`main`, `run`), поверхность не называет — оно называет
    привычку, и догадываться, какой файл имели в виду, прибор не вправе.
    """
    where = index.get(raw) or []
    if not where:
        return None, NAME_ABSENT, "имени нет среди определений верхнего уровня дерева"
    if len(where) > 1:
        return None, NAME_AMBIGUOUS, f"имя определяют {len(where)} файл(ов) дерева"
    return where[0], NAME_RESOLVED, f"единственное определение ({where[0]})"


def declared_by_name(root: Path,
                     index: Dict[str, List[str]]) -> dict:
    """Объявления правил, в которых ПУТИ НЕТ (заказ **G56 п. 2**).

    Заказ дословно: «замерить, сколько объявлений правил вообще НЕ содержат
    пути: пока это число неизвестно, „объявлено семь“ есть нижняя граница с
    неизвестным зазором, а не население».

    Считаются числа, и они разные: сколько абзацев правил вообще несут язык
    права изменения, сколько из них мера пути ОТБРОСИЛА как широкие, у
    скольких путь есть, у скольких его нет. Вместе они и есть зазор.

    **Широкий абзац здесь НЕ отбрасывается, и это не ослабление предела, а
    другая улика.** Предел :data:`MAX_DECLARING_PARAGRAPH` защищает от «путь
    рядом с фразой»: в длинном нарративе такое соседство ничего не значит.
    Имя связывается с файлом иначе — оно обязано разрешиться в РОВНО ОДНО
    определение верхнего уровня во всём дереве, и эта связь не слабеет от
    длины абзаца. Поэтому широкие абзацы входят в население канала имени, но
    помечены (``paragraph_wide``) и посчитаны отдельно: смешать их значило бы
    потерять ровно тот ответ, ради которого заказ и поставлен.
    """
    texts: List[Path] = []
    rule_text = root / RULE_TEXT
    if rule_text.is_file():
        texts.append(rule_text)
    rules_dir = root / RULE_DIR
    if rules_dir.is_dir():
        texts.extend(sorted(rules_dir.glob("*.md")))
    candidates: Dict[str, List[dict]] = {}
    unresolved: List[dict] = []
    by_outcome: Dict[str, int] = {outcome: 0 for outcome in _NAME_OUTCOMES}
    unreadable: List[dict] = []
    read = 0
    counts = {
        "paragraphs_authority": 0,
        "paragraphs_wide_total": 0,
        "paragraphs_wide_with_authority": 0,
        "paragraphs_with_path": 0,
        "paragraphs_without_path": 0,
        "names_in_paragraphs_with_path": 0,
        "control_paragraphs": 0,
        "control_names": 0,
        "control_resolved_single": 0,
    }
    for path in texts:
        rel_text = path.relative_to(root).as_posix()
        try:
            body = path.read_text(encoding="utf-8")
        except Exception as exc:  # noqa: BLE001
            unreadable.append({"text": rel_text,
                               "reason": f"{type(exc).__name__}: {exc}"})
            continue
        read += 1
        for block in declaring_paragraphs(body):
            wide = not _paragraph_admissible(block)
            if wide:
                counts["paragraphs_wide_total"] += 1
            joined = "\n".join(line for _, line in block).lower()
            if not any(mark in joined for mark in AUTHORITY_MARKS):
                # Контроль базовой частоты: тот же разбор на абзацах БЕЗ языка
                # права изменения. Без него «канал имени нашёл пять» не
                # отличить от «обратные кавычки разрешаются с такой частотой
                # везде» — у подтверждающего прибора обязана быть своя частота
                # ошибки, иначе он подтверждает сам себя.
                counts["control_paragraphs"] += 1
                for _lineno, line in block:
                    for match in _DECLARED_NAME_RE.finditer(line):
                        _r, outcome, _w = resolve_declared_name(match.group(1),
                                                                index)
                        counts["control_names"] += 1
                        if outcome == NAME_RESOLVED:
                            counts["control_resolved_single"] += 1
                continue
            counts["paragraphs_authority"] += 1
            if wide:
                counts["paragraphs_wide_with_authority"] += 1
            has_path = any(_DECLARED_PATH_RE.search(line) for _, line in block)
            if has_path:
                counts["paragraphs_with_path"] += 1
                counts["names_in_paragraphs_with_path"] += sum(
                    len(_DECLARED_NAME_RE.findall(line)) for _, line in block)
            else:
                counts["paragraphs_without_path"] += 1
            for lineno, line in block:
                for match in _DECLARED_NAME_RE.finditer(line):
                    raw = match.group(1)
                    resolved, outcome, why = resolve_declared_name(raw, index)
                    by_outcome[outcome] = by_outcome.get(outcome, 0) + 1
                    evidence = {
                        "text": rel_text,
                        "line": lineno,
                        "quote": line.strip()[:160],
                        "named_as": raw,
                        "resolution": why,
                        "outcome": outcome,
                        "paragraph_wide": wide,
                        "paragraph_has_path": has_path,
                    }
                    if resolved is None:
                        if evidence not in unresolved:
                            unresolved.append(evidence)
                        continue
                    if evidence not in candidates.setdefault(resolved, []):
                        candidates[resolved].append(evidence)
    out = {
        "texts_read": read,
        "texts_unreadable": unreadable,
        "by_outcome": by_outcome,
        "candidates": candidates,
        "unresolved": unresolved,
    }
    out.update(counts)
    return out


def name_channel(root: Path, rows: List[dict], *,
                 path_candidates: Iterable[str],
                 asked: Tuple[str, ...] = ASKED_SURFACES,
                 definitions: Optional[Tuple[Dict[str, List[str]], int,
                                             List[dict]]] = None) -> dict:
    """Сколько поверхностей решения объявлено ИМЕНЕМ, а не путём (**G56 п. 2**).

    Мера G55 отвечала на вопрос «какие файлы объявлены правилами» обходом
    ПУТЕЙ, и сама назвала свою слепоту вслух: объявление бывает именем класса.
    Здесь у слепоты появляется ЧИСЛО — и зазор между «объявлено семь» и
    населением перестаёт быть неизвестным.

    **Два числа считаются отдельно, и смешивать их нельзя.** ``gap`` — сколько
    поверхностей канал имени добавляет к населению пути; ``matches``/
    ``would_move`` — кусается ли добавленное, ровно в том же смысле, что у
    :func:`decision_surfaces`. У поверхности, которую УЖЕ спрашивают,
    ``would_move`` нулевой ПО ПОСТРОЕНИЮ, а ``matches`` — нет.

    Третий исход обязателен и здесь: ни один текст правил не прочитан ИЛИ ни
    один файл дерева не разобран ⇒ :data:`NAME_CHANNEL_UNMEASURED`. Пустой
    индекс имён и «имён в правилах нет» — разные ответы.
    """
    # Индекс берётся аргументом, когда зовущий уже его построил: обход дерева
    # стоит секунд, а соседняя координата (заказ G60) спрашивает ТОТ ЖЕ индекс.
    # Второй обход дал бы то же число другой ценой — и, что хуже, два
    # населения, способных разойтись между собой внутри одного прогона.
    index, files_read, files_unreadable = (
        definitions if definitions is not None else toplevel_definitions(root))
    named = declared_by_name(root, index)
    if named["texts_read"] == 0 or files_read == 0:
        reason = ("ни один текст правил не прочитан"
                  if named["texts_read"] == 0
                  else "ни один файл дерева не разобран — разрешать имена нечем")
        return {
            "verdict": NAME_CHANNEL_UNMEASURED,
            "reason": f"{reason}: канал имени НЕ ИЗМЕРЕН",
            "texts_read": named["texts_read"],
            "texts_unreadable": named["texts_unreadable"],
            "files_read": files_read,
            "files_unreadable": files_unreadable,
            "surfaces": [],
            "gap": 0,
        }
    known = set(path_candidates)
    numeric_rows = [r for r in rows if is_numeric_value(r.get("value"))]
    right_forms = (REMEDY_OWNER, REMEDY_CONSTITUTION, REMEDY_RIGHT_UNMEASURED)
    surfaces: List[dict] = []
    already: List[str] = []
    for rel in sorted(named["candidates"]):
        if rel in known:
            already.append(rel)
            continue
        values, kind, reason = surface_numbers(root, rel)
        row: dict = {
            "path": rel,
            "kind": kind,
            "declared_by": named["candidates"][rel],
            "asked_today": rel in asked,
        }
        if values is None:
            row["reason"] = reason
            surfaces.append(row)
            continue
        matched = [r for r in numeric_rows
                   if value_key(r.get("value")) in values]
        moved = [r for r in matched if r.get("remedy") not in right_forms]
        row.update({
            "numbers": len(values),
            "matches": len(matched),
            "would_move": len(moved),
            "would_move_names": sorted({f"{r['name']} = {r['value']}"
                                        for r in moved}),
        })
        surfaces.append(row)
    shelves = [s for s in surfaces if s["kind"] == SURFACE_SHELF]
    unasked_moving = [s for s in shelves
                      if not s["asked_today"] and s.get("would_move")]
    biting = [s for s in shelves if s.get("matches")]
    if not surfaces:
        verdict = NAME_CHANNEL_NOTHING_NAMED
        reason = (f"из {named['paragraphs_authority']} абзац(ев) с языком права "
                  f"изменения ни один не назвал имени, которое дерево определяет "
                  f"единственным файлом и которого не знал канал пути")
    elif unasked_moving:
        verdict = NAME_CHANNEL_SHIFT
        reason = (f"{len(unasked_moving)} поверхност(ь/ей), объявленн(ая/ых) "
                  f"ИМЕНЕМ и не спрашиваем(ая/ых), дают агенту право чинить "
                  f"{sum(s['would_move'] for s in unasked_moving)} пар(ы)")
    elif biting:
        verdict = NAME_CHANNEL_NO_SHIFT
        reason = (f"канал имени добавил {len(surfaces)} поверхност(ь/ей) к "
                  f"населению пути, из них шкафов чисел {len(shelves)}; ни один "
                  f"НЕспрашиваемый не даёт права чинить, и мера при этом "
                  f"кусается — добавленные называют "
                  f"{sum(s['matches'] for s in biting)} строк(и)")
    else:
        verdict = NAME_CHANNEL_NO_SHIFT
        reason = (f"канал имени добавил {len(surfaces)} поверхност(ь/ей), но ни "
                  f"одна не называет ни одной находки — ноль ИЗМЕРЕН, укуса "
                  f"этой мерой сегодня не предъявлено")
    return {
        "verdict": verdict,
        "reason": reason,
        "question": ("сколько объявлений правил вообще НЕ содержат пути и "
                     "сколько поверхностей решения объявлено ИМЕНЕМ"),
        "texts_read": named["texts_read"],
        "texts_unreadable": named["texts_unreadable"],
        "files_read": files_read,
        "files_unreadable": files_unreadable,
        "paragraphs_authority": named["paragraphs_authority"],
        "paragraphs_with_path": named["paragraphs_with_path"],
        "paragraphs_without_path": named["paragraphs_without_path"],
        "paragraphs_wide_total": named["paragraphs_wide_total"],
        "paragraphs_wide_with_authority": named["paragraphs_wide_with_authority"],
        "names_in_paragraphs_with_path": named["names_in_paragraphs_with_path"],
        "control_paragraphs": named["control_paragraphs"],
        "control_names": named["control_names"],
        "control_resolved_single": named["control_resolved_single"],
        "by_outcome": named["by_outcome"],
        "gap": len(surfaces),
        "already_declared_by_path": sorted(already),
        "shelves": len(shelves),
        "would_move_total": sum(s["would_move"] for s in unasked_moving),
        "surfaces": surfaces,
        "unresolved": named["unresolved"][:40],
        "blind": [
            "имена ищутся ТОЛЬКО в абзацах без пути — это сужение по заказу, и "
            "цена его названа числом (names_in_paragraphs_with_path), а не "
            "умолчанием",
            "имя, определённое несколькими файлами дерева, поверхности не "
            "называет: догадка о том, какой файл имели в виду, прибором не "
            "делается — такое имя уходит в свой исход, а не в ноль",
            "объявление ИМЕНЕМ МОДУЛЯ (`spa_core.risk.policy`) каналом не "
            "ловится: обратные кавычки с точками именем верхнего уровня не "
            "являются, и это остаток слепоты, а не её отсутствие",
        ],
    }



#: Почему абзац отброшен мерой пути. Две причины, и слить их нельзя: предел
#: строки защищает от реестра ADR (364 строки длиннее 400 символов), предел
#: абзаца — от нарратива. Заказ G57 п. 1 спрашивает про ВТОРОЙ, и ответ «шесть»
#: без разделения был бы числом о сумме двух разных решений.
WIDE_BY_LINES = "too_many_lines"
WIDE_BY_LINE_LENGTH = "line_too_long"
WIDE_BY_BOTH = "both_limits"
_WIDE_REASONS = (WIDE_BY_LINES, WIDE_BY_LINE_LENGTH, WIDE_BY_BOTH)

#: Вердикт канала широкого абзаца (заказ **G57 п. 1**). «Путей внутри нет» и
#: «пути есть, но вердикта не двигают» — разные ответы, и первый не есть
#: чистота.
WIDE_CHANNEL_SHIFT = "WIDE_PARAGRAPH_SHIFT"
WIDE_CHANNEL_NO_SHIFT = "WIDE_PARAGRAPH_NO_SHIFT"
WIDE_CHANNEL_NOTHING_NAMED = "WIDE_PARAGRAPH_NOTHING_NAMED"
WIDE_CHANNEL_UNMEASURED = "WIDE_PARAGRAPH_UNMEASURED"


def _wide_reason(block: List[Tuple[int, str]]) -> str:
    by_lines = len(block) > MAX_DECLARING_PARAGRAPH
    by_length = max(len(line) for _, line in block) > MAX_DECLARING_LINE
    if by_lines and by_length:
        return WIDE_BY_BOTH
    return WIDE_BY_LINES if by_lines else WIDE_BY_LINE_LENGTH


def paths_in_wide_paragraphs(root: Path) -> dict:
    """Пути, названные внутри ШИРОКИХ абзацев с языком права изменения (**G57 п. 1**).

    Заказ дословно: «замерить, сколько ПУТЕЙ названо внутри этих шести абзацев
    и сколько из них дали бы новую поверхность: пока это неизвестно,
    „объявлено семь“ остаётся нижней границей».

    **Это НЕ ослабление предела** :data:`MAX_DECLARING_PARAGRAPH`, и разница
    существенна. Мера пути (:func:`declared_surfaces`) широкий абзац не читает
    и читать не начинает; здесь считается ПОТОЛОК того, что расширение предела
    добавило бы, — и считается он отдельной координатой, которая в население
    объявленных поверхностей ничего не доливает. Население и потолок зазора —
    два разных числа; слить их значило бы выдать «путь рядом с фразой» за
    объявление, то есть ровно за тот дефект, от которого предел и написан.

    Вместе с потолком считается его ЧАСТОТА ОШИБКИ, и считается она таблицей
    2×2 (узкий/широкий × с языком права/без). Без второй строки таблицы
    «двенадцать упоминаний» неотличимо от того, что широкий абзац называет
    пути и так: обогащение отбором есть свойство ОТБОРА, а не населения.
    """
    texts: List[Path] = []
    rule_text = root / RULE_TEXT
    if rule_text.is_file():
        texts.append(rule_text)
    rules_dir = root / RULE_DIR
    if rules_dir.is_dir():
        texts.extend(sorted(rules_dir.glob("*.md")))
    tree_paths = _tree_paths(root)
    candidates: Dict[str, List[dict]] = {}
    control_candidates: set = set()
    unresolved: List[dict] = []
    unreadable: List[dict] = []
    read = 0
    cells = {
        "wide_authority": [0, 0],
        "wide_control": [0, 0],
        "narrow_authority": [0, 0],
        "narrow_control": [0, 0],
    }
    by_reason: Dict[str, int] = {reason: 0 for reason in _WIDE_REASONS}
    for path in texts:
        rel_text = path.relative_to(root).as_posix()
        try:
            body = path.read_text(encoding="utf-8")
        except Exception as exc:  # noqa: BLE001
            unreadable.append({"text": rel_text,
                               "reason": f"{type(exc).__name__}: {exc}"})
            continue
        read += 1
        for block in declaring_paragraphs(body):
            wide = not _paragraph_admissible(block)
            joined = "\n".join(line for _, line in block).lower()
            authority = any(mark in joined for mark in AUTHORITY_MARKS)
            mentions = sum(len(_DECLARED_PATH_RE.findall(line))
                           for _, line in block)
            cell = cells[("wide" if wide else "narrow")
                         + ("_authority" if authority else "_control")]
            cell[0] += 1
            cell[1] += mentions
            if wide and not authority:
                # Контроль на ТОЙ ЖЕ ширине, но без отбора. Нужен не для
                # украшения: обогащение по УПОМИНАНИЯМ и обогащение по
                # ПОСЛЕДСТВИЮ — два разных вопроса, и на этом дереве они
                # отвечают по-разному (ADR G57 п. 1).
                for _lineno, line in block:
                    for match in _DECLARED_PATH_RE.finditer(line):
                        resolved, _why = resolve_declared_path(
                            match.group(1), tree_paths, root)
                        if resolved is not None:
                            control_candidates.add(resolved)
                continue
            if not (wide and authority):
                continue
            by_reason[_wide_reason(block)] += 1
            for lineno, line in block:
                for match in _DECLARED_PATH_RE.finditer(line):
                    raw = match.group(1)
                    resolved, why = resolve_declared_path(raw, tree_paths, root)
                    evidence = {
                        "text": rel_text,
                        "line": lineno,
                        "quote": line.strip()[:160],
                        "named_as": raw,
                        "resolution": why,
                        "paragraph_lines": len(block),
                        "wide_because": _wide_reason(block),
                    }
                    if resolved is None:
                        if evidence not in unresolved:
                            unresolved.append(evidence)
                        continue
                    if evidence not in candidates.setdefault(resolved, []):
                        candidates[resolved].append(evidence)
    out = {
        "texts_read": read,
        "texts_unreadable": unreadable,
        "candidates": candidates,
        "control_candidates": sorted(control_candidates),
        "unresolved": unresolved,
        "wide_by_reason": by_reason,
    }
    for name, (paragraphs, mentions) in cells.items():
        out[f"{name}_paragraphs"] = paragraphs
        out[f"{name}_mentions"] = mentions
    return out


def _enrichment(selected: Tuple[int, int],
                control: Tuple[int, int]) -> Tuple[Optional[float], str]:
    """Во сколько раз отбор «язык права изменения» сгущает упоминания пути.

    Третий исход обязателен: контрольных абзацев нет ИЛИ контроль не назвал
    ни одного пути ⇒ ``None`` с причиной. Деление на ноль здесь молча дало бы
    «обогащение бесконечно», то есть выдало бы отсутствие наблюдения за
    сильнейшим возможным результатом.
    """
    sel_paragraphs, sel_mentions = selected
    ctl_paragraphs, ctl_mentions = control
    if not sel_paragraphs:
        return None, "отобранных абзацев нет — сгущать нечего"
    if not ctl_paragraphs:
        return None, "контрольных абзацев нет — частота ошибки НЕ ИЗМЕРЕНА"
    if not ctl_mentions:
        return None, ("контроль не назвал ни одного пути — знаменателя нет, и "
                      "«обогащение бесконечно» было бы не измерением")
    return ((sel_mentions / sel_paragraphs) / (ctl_mentions / ctl_paragraphs),
            "измерено")


def wide_paragraph_channel(root: Path, rows: List[dict], *,
                           path_candidates: Iterable[str],
                           name_candidates: Iterable[str],
                           asked: Tuple[str, ...] = ASKED_SURFACES) -> dict:
    """Цена слепоты ШИРОКОГО абзаца — оба числа заказа **G57 п. 1**.

    Первое число — НАСЕЛЕНИЕ: сколько путей названо внутри широких абзацев с
    языком права изменения и сколько из них не знает ни канал пути, ни канал
    имени. Второе — ВЕРДИКТ: сколько пар сменили бы форму права чинить, если
    бы эти поверхности спрашивались. Смешивать их нельзя ровно по той же
    причине, что и в :func:`decision_surfaces`: «поверхность добавилась» и
    «добавленное кусается» — разные утверждения.

    **Зазор считается против ОБОИХ прежних каналов сразу.** Путь, который уже
    нашёл канал имени (:func:`name_channel`), новой поверхностью не является,
    и зачесть его сюда значило бы посчитать одну находку дважды. Замер 20.09:
    ровно один из десяти (`spa_core/governance/kill_switch.py`) уже объявлен
    именем — и он же единственный, кто называет хоть одну находку.

    Третий исход обязателен: ни один текст правил не прочитан ⇒
    :data:`WIDE_CHANNEL_UNMEASURED`. «Правил не прочитано» и «в правилах
    широких абзацев нет» — разные ответы.
    """
    named = paths_in_wide_paragraphs(root)
    if named["texts_read"] == 0:
        return {
            "verdict": WIDE_CHANNEL_UNMEASURED,
            "reason": ("ни один текст правил не прочитан — широких абзацев не "
                       "из чего собрать, и потолок зазора НЕ ИЗМЕРЕН"),
            "texts_read": 0,
            "texts_unreadable": named["texts_unreadable"],
            "surfaces": [],
            "gap": 0,
        }
    known_by_path = set(path_candidates)
    known_by_name = set(name_candidates)
    numeric_rows = [r for r in rows if is_numeric_value(r.get("value"))]
    right_forms = (REMEDY_OWNER, REMEDY_CONSTITUTION, REMEDY_RIGHT_UNMEASURED)

    def _row(rel: str) -> dict:
        values, kind, reason = surface_numbers(root, rel)
        row: dict = {
            "path": rel,
            "kind": kind,
            "declared_by": named["candidates"][rel],
            "asked_today": rel in asked,
        }
        if values is None:
            row["reason"] = reason
            return row
        matched = [r for r in numeric_rows
                   if value_key(r.get("value")) in values]
        moved = [r for r in matched if r.get("remedy") not in right_forms]
        row.update({
            "numbers": len(values),
            "matches": len(matched),
            "would_move": len(moved),
            "would_move_names": sorted({f"{r['name']} = {r['value']}"
                                        for r in moved}),
        })
        return row

    surfaces: List[dict] = []
    already: List[dict] = []
    for rel in sorted(named["candidates"]):
        row = _row(rel)
        if rel in known_by_path or rel in known_by_name:
            row["known_by"] = ("path" if rel in known_by_path else "name")
            already.append(row)
            continue
        surfaces.append(row)
    # Контроль ПО ПОСЛЕДСТВИЮ: те же широкие абзацы, но без языка права
    # изменения. Вопрос «обогащает ли отбор» имеет ДВЕ оси, и на этом дереве
    # они отвечают по-разному: по упоминаниям отбор почти не сгущает, по
    # сменившим бы форму парам — сгущает решительно. Мерить обогащение
    # упоминаниями и объявлять этим ответ о последствии значило бы посчитать
    # не то население.
    control_rows: List[dict] = []
    for rel in named["control_candidates"]:
        values, kind, _reason = surface_numbers(root, rel)
        if kind != SURFACE_SHELF or values is None:
            continue
        matched = [r for r in numeric_rows
                   if value_key(r.get("value")) in values]
        moved = [r for r in matched if r.get("remedy") not in right_forms]
        control_rows.append({"path": rel, "matches": len(matched),
                             "would_move": len(moved),
                             "asked_today": rel in asked})
    control_move = sum(r["would_move"] for r in control_rows
                       if not r["asked_today"])

    shelves = [s for s in surfaces if s["kind"] == SURFACE_SHELF]
    guards = [s for s in surfaces if s["kind"] == SURFACE_GUARD]
    unasked_moving = [s for s in shelves
                      if not s["asked_today"] and s.get("would_move")]
    biting = [s for s in shelves if s.get("matches")]
    biting_already = [s for s in already if s.get("matches")]
    wide_authority = named["wide_authority_paragraphs"]
    if not named["candidates"]:
        verdict = WIDE_CHANNEL_NOTHING_NAMED
        reason = (f"в {wide_authority} широк(ом/их) абзац(е/ах) с языком права "
                  f"изменения не названо ни одного пути — расширять предел "
                  f"было бы не за чем")
    elif unasked_moving:
        verdict = WIDE_CHANNEL_SHIFT
        reason = (f"{len(unasked_moving)} поверхност(ь/ей) из широкого абзаца "
                  f"не спрашивается, и её молчание даёт агенту право чинить "
                  f"{sum(s['would_move'] for s in unasked_moving)} пар(ы)")
    elif biting:
        verdict = WIDE_CHANNEL_NO_SHIFT
        reason = (f"широкий абзац добавляет {len(surfaces)} поверхност(ь/ей) к "
                  f"населению двух прежних каналов, шкафов чисел из них "
                  f"{len(shelves)}; права чинить не даёт ни одна, и мера при "
                  f"этом кусается — добавленные называют "
                  f"{sum(s['matches'] for s in biting)} строк(и)")
    else:
        verdict = WIDE_CHANNEL_NO_SHIFT
        reason = (f"широкий абзац добавляет {len(surfaces)} поверхност(ь/ей), "
                  f"но ни одна не называет ни одной находки — ноль ИЗМЕРЕН, "
                  f"и цена слепоты по ВЕРДИКТУ сегодня нулевая"
                  + (f"; укус предъявлен на {len(biting_already)} пут(и/ях), "
                     f"которые прежние каналы уже знают"
                     if biting_already else ""))
    # Какой ИМЕННО предел держит цену. Заказ G57 п. 1 назвал
    # `MAX_DECLARING_PARAGRAPH`; посылку надо проверить, а не повторить:
    # «широкий» есть ДИЗЪЮНКЦИЯ двух пределов, и приписать сумму одному из них
    # значило бы ответить не на тот вопрос.
    move_by_reason: Dict[str, int] = {reason: 0 for reason in _WIDE_REASONS}
    surfaces_by_reason: Dict[str, int] = {reason: 0 for reason in _WIDE_REASONS}
    for row in surfaces:
        why = (row.get("declared_by") or [{}])[0].get("wide_because")
        if why not in move_by_reason:
            continue
        surfaces_by_reason[why] += 1
        move_by_reason[why] += row.get("would_move") or 0

    wide_ratio, wide_why = _enrichment(
        (named["wide_authority_paragraphs"], named["wide_authority_mentions"]),
        (named["wide_control_paragraphs"], named["wide_control_mentions"]))
    narrow_ratio, narrow_why = _enrichment(
        (named["narrow_authority_paragraphs"], named["narrow_authority_mentions"]),
        (named["narrow_control_paragraphs"], named["narrow_control_mentions"]))
    out = {
        "verdict": verdict,
        "reason": reason,
        "question": ("сколько ПУТЕЙ названо внутри широких абзацев с языком "
                     "права изменения и сколько из них дали бы НОВУЮ "
                     "поверхность решения"),
        "texts_read": named["texts_read"],
        "texts_unreadable": named["texts_unreadable"],
        "mentions": named["wide_authority_mentions"],
        "distinct_paths": len(named["candidates"]) + len(
            {e["named_as"] for e in named["unresolved"]}),
        "resolved_paths": len(named["candidates"]),
        "unresolved": named["unresolved"][:40],
        # Знаменатель утверждения «сменили бы форму N пар». Публикуется
        # потому, что без него число N не с чем сравнить, а фильтр
        # `is_numeric_value` остался бы ненаблюдаемым: сторож, чьё действие
        # наружу не видно, не проверяется ничем.
        "population_total": len(rows),
        "population_numeric": len(numeric_rows),
        "gap": len(surfaces),
        "shelves": len(shelves),
        "guards": len(guards),
        "would_move_total": sum(s["would_move"] for s in unasked_moving),
        "already_known": [{"path": s["path"], "known_by": s["known_by"],
                           "matches": s.get("matches")} for s in already],
        "surfaces": surfaces,
        "wide_by_reason": named["wide_by_reason"],
        "would_move_by_wide_reason": move_by_reason,
        "surfaces_by_wide_reason": surfaces_by_reason,
        "control_shelves": len(control_rows),
        "control_matches": sum(r["matches"] for r in control_rows),
        "control_would_move": control_move,
        "control_rows": control_rows,
        "enrichment_wide": wide_ratio,
        "enrichment_wide_reason": wide_why,
        "enrichment_narrow": narrow_ratio,
        "enrichment_narrow_reason": narrow_why,
        "blind": [
            "число есть ПОТОЛОК того, что дало бы расширение предела, а не "
            "население объявленных поверхностей: внутри широкого абзаца связь "
            "«путь рядом с фразой» слаба ПО ПОСТРОЕНИЮ, и мера пути его не "
            "читает по-прежнему",
            "обогащение отбором — свойство ОТБОРА, а не репозитория: узкий "
            "абзац и широкий меряются отдельными строками таблицы именно "
            "потому, что одно число на оба ответило бы не на тот вопрос",
            "путь, названный внутри широкого абзаца ЧУЖОГО правила (цитата, "
            "пересказ, ссылка на соседний документ), отличить от объявления "
            "эта мера не умеет — ошибка отбора направлена в сторону «спросить»",
        ],
    }
    for key in ("wide_authority", "wide_control", "narrow_authority",
                "narrow_control"):
        out[f"{key}_paragraphs"] = named[f"{key}_paragraphs"]
        out[f"{key}_mentions"] = named[f"{key}_mentions"]
    return out
# ── ФОРМА «ТАБЛИЦА С ДЛИННЫМИ СТРОКАМИ» (заказ G58 п. 1) ────────────────────
#: Каналы, по которым форма меряется. Разделены НАМЕРЕННО и слиянию не
#: подлежат: `rules_declared` — то самое население, на котором заказ G57 нашёл
#: свои тринадцать пар (выборка), остальные два — КОНТРОЛЬ ширины. Контроль
#: каналом объявления не становится и в `decision_surfaces` не доливает ни
#: строки: вопрос здесь «редка ли форма», а не «что ещё объявлено».
TABLE_CHANNEL_RULES = "rules_declared"
TABLE_CHANNEL_DOCS = "docs_control"
TABLE_CHANNEL_ADR = "adr_control"
_TABLE_CHANNELS = (TABLE_CHANNEL_RULES, TABLE_CHANNEL_DOCS, TABLE_CHANNEL_ADR)

#: Вердикт формы. «Форма живёт только в выборке» и «форма живёт по всему
#: репозиторию» — РАЗНЫЕ ответы заказу, и от них зависит форма починки: в
#: первом случае чинится один абзац, во втором чинить один абзац значит
#: оставить класс на месте.
TABLE_FORM_SAMPLE_BOUND = "TABLE_FORM_SAMPLE_BOUND"
TABLE_FORM_REPO_WIDE = "TABLE_FORM_REPO_WIDE"
TABLE_FORM_NOTHING_FOUND = "TABLE_FORM_NOTHING_FOUND"
TABLE_FORM_UNMEASURED = "TABLE_FORM_UNMEASURED"

#: Разделительная строка markdown-таблицы: `|---|---|`, `| :--- | ---: |`.
#: Признак взят ИМЕННО такой, а не «строка начинается с трубы»: строка с трубой
#: бывает в коде, в цитате и в перечне, и считать её таблицей значило бы
#: посчитать формой то, чего в тексте нет.
_TABLE_SEPARATOR_RE = re.compile(r"^\s*\|(?:\s*:?-{2,}:?\s*\|)+\s*$")
#: Сколько строк с трубой обязана иметь таблица помимо разделителя: шапка и
#: хотя бы одна строка тела. Меньше — не таблица, а обрывок.
MIN_TABLE_PIPE_LINES = 2


def is_markdown_table(block: List[Tuple[int, str]]) -> bool:
    """Абзац — markdown-таблица (разделитель + шапка + хотя бы одна строка).

    Отдельной функцией, а не выражением внутри переписи, потому что именно
    ЭТОТ признак заказ G58 называет формой; признак, который нельзя позвать
    отдельно, нельзя и проверить отдельно.
    """
    pipes = sum(1 for _, line in block if line.lstrip().startswith("|"))
    separators = sum(1 for _, line in block if _TABLE_SEPARATOR_RE.match(line))
    # Разделитель сам начинается с трубы, поэтому из счёта он вычитается:
    # требование — шапка и хотя бы одна строка тела ПОМИМО него. Без вычитания
    # «таблицей» стал бы разделитель с одной соседней строкой, то есть обрывок.
    return separators >= 1 and pipes - separators >= MIN_TABLE_PIPE_LINES


def _table_channel_texts(root: Path, channel: str) -> List[Path]:
    """Файлы канала. Пустой список — НЕ ошибка: его называет третий исход."""
    if channel == TABLE_CHANNEL_RULES:
        out: List[Path] = []
        rule_text = root / RULE_TEXT
        if rule_text.is_file():
            out.append(rule_text)
        rules_dir = root / RULE_DIR
        if rules_dir.is_dir():
            out.extend(sorted(rules_dir.glob("*.md")))
        return out
    if channel == TABLE_CHANNEL_ADR:
        out = []
        for name in ADR_DIRS:
            directory = root / name
            if directory.is_dir():
                out.extend(sorted(directory.glob("*.md")))
        return out
    docs = root / "docs"
    if not docs.is_dir():
        return []
    skip = tuple(f"{name}/" for name in ADR_DIRS) + ("docs/journal/",)
    return [p for p in sorted(docs.rglob("*.md"))
            if not p.relative_to(root).as_posix().startswith(skip)]


def table_form_population(root: Path, channel: str) -> dict:
    """Перепись формы в ОДНОМ канале.

    Считаются четыре числа, и последние два существуют затем, чтобы «девять
    таблиц в docs/» нельзя было прочесть как «в docs/ форма чаще»: в docs/
    файлов в сорок раз больше, и голое число сказало бы о РАЗМЕРЕ канала, а не
    о его свойстве. Доля таблиц среди широких абзацев с языком права изменения
    отвечает на вопрос заказа, а счёт — нет.

    **Предел строки и предел абзаца разделены.** Заказ дословно говорит
    «таблица с ДЛИННЫМИ СТРОКАМИ», и таблица, отброшенная за ЧИСЛО строк, той
    же формой не является: от длинной строки защищает один предел, от длинного
    абзаца — другой. Сложить их в одно число значило бы ответить не на тот
    вопрос (тот же довод, что у `wide_by_reason` в канале G57).

    Нечитаемый файл — ТРЕТИЙ ИСХОД с причиной (инв. #17), а не ноль: «не
    прочитали» и «формы нет» здесь неотличимы только для того, кто их слил.
    """
    texts = _table_channel_texts(root, channel)
    counts = {reason: 0 for reason in _WIDE_REASONS}
    hits: List[dict] = []
    unreadable: List[dict] = []
    read = 0
    paragraphs = tables = wide = wide_authority = 0
    for path in texts:
        rel = path.relative_to(root).as_posix()
        try:
            body = path.read_text(encoding="utf-8")
        except Exception as exc:  # noqa: BLE001
            unreadable.append({"text": rel,
                               "reason": f"{type(exc).__name__}: {exc}"})
            continue
        read += 1
        for block in declaring_paragraphs(body):
            paragraphs += 1
            table = is_markdown_table(block)
            if table:
                tables += 1
            if _paragraph_admissible(block):
                continue
            wide += 1
            joined = "\n".join(line for _, line in block).lower()
            if not any(mark in joined for mark in AUTHORITY_MARKS):
                continue
            wide_authority += 1
            if not table:
                continue
            reason = _wide_reason(block)
            counts[reason] += 1
            hits.append({
                "text": rel,
                "line": block[0][0],
                "lines": len(block),
                "longest_line": max(len(line) for _, line in block),
                "wide_because": reason,
                "quote": block[0][1].strip()[:120],
                # Реестр ADR объявлен НЕ каналом (см. `ADR_REGISTRY`), и его
                # единственная «таблица» — весь файл одной строкой на ADR.
                # Посчитать его молча значило бы подпереть утверждение о
                # репозитории тем, что репозиторий уже объявил исключением.
                "declared_registry": rel == ADR_REGISTRY,
            })
    long_line_hits = [h for h in hits if h["wide_because"] in
                      (WIDE_BY_LINE_LENGTH, WIDE_BY_BOTH)
                      and not h["declared_registry"]]
    return {
        "channel": channel,
        "texts_total": len(texts),
        "texts_read": read,
        "texts_unreadable": unreadable,
        "paragraphs": paragraphs,
        "tables": tables,
        "wide_paragraphs": wide,
        "wide_authority_paragraphs": wide_authority,
        # Широкая форма ЛЮБОЙ причины — знаменатель доли ниже.
        "form_any_reason": len(hits),
        # Форма ЗАКАЗА: таблица, отброшенная ДЛИНОЙ СТРОКИ, без объявленного
        # реестра. Это то число, о котором заказ спрашивает.
        "form_long_line": len(long_line_hits),
        "form_by_reason": counts,
        "registry_hits": len([h for h in hits if h["declared_registry"]]),
        "hits": hits,
        "long_line_hits": long_line_hits,
    }


def table_form_census(root: Path) -> dict:
    """Редка ли форма «таблица с длинными строками + язык права изменения».

    Заказ **G58 п. 1** дословно: «замерить, СКОЛЬКО правил репозитория имеют
    ту же форму… сегодня это число неизвестно, и „одна таблица“ может
    оказаться свойством выборки, а не репозитория».

    Вопрос поставлен о ВЫБОРКЕ, поэтому и меряется он двумя населениями:
    объявленным каналом правил (та самая выборка G57) и контролем — `docs/` и
    каналом ADR. Контроль объявлением НЕ становится: он отвечает на вопрос
    «редка ли форма», а не «что ещё объявлено», и в население поверхностей
    решения не попадает ни одной строкой. Смешать их значило бы тихо
    расширить канал объявления — ровно то, чего предел `MAX_DECLARING_LINE`
    и не даёт сделать.

    Вердикт различает два ответа, потому что от них зависит форма починки:
    форма, живущая ТОЛЬКО в выборке, чинится одним абзацем; форма, живущая по
    репозиторию, одним абзацем не чинится вовсе — чинить придётся правило.
    """
    channels = {name: table_form_population(root, name)
                for name in _TABLE_CHANNELS}
    read_total = sum(c["texts_read"] for c in channels.values())
    unreadable = [u for c in channels.values() for u in c["texts_unreadable"]]
    sample = channels[TABLE_CHANNEL_RULES]
    controls = [channels[TABLE_CHANNEL_DOCS], channels[TABLE_CHANNEL_ADR]]
    control_form = sum(c["form_long_line"] for c in controls)

    if not read_total:
        verdict = TABLE_FORM_UNMEASURED
        reason = ("не прочитано ни одного текста ни в одном канале — «формы "
                  "нет» о репозитории НЕ сказано")
    elif not sample["texts_read"]:
        verdict = TABLE_FORM_UNMEASURED
        reason = ("объявленный канал правил не прочитан — выборка, о которой "
                  "спрашивает заказ, не измерена, и контроль за неё не отвечает")
    elif not sample["form_long_line"] and not control_form:
        verdict = TABLE_FORM_NOTHING_FOUND
        reason = ("формы нет ни в выборке, ни в контроле: широких таблиц с "
                  f"языком права изменения, отброшенных ДЛИНОЙ СТРОКИ, — 0 "
                  f"при {sample['wide_authority_paragraphs']} широк(ом/их) "
                  f"абзац(е/ах) с этим языком в выборке")
    elif control_form:
        verdict = TABLE_FORM_REPO_WIDE
        reason = (f"форма живёт и ВНЕ объявленного канала: в выборке "
                  f"{sample['form_long_line']}, в контроле {control_form} "
                  f"(docs/ {controls[0]['form_long_line']}, ADR "
                  f"{controls[1]['form_long_line']}). «Одна таблица» есть "
                  f"свойство ВЫБОРКИ — чинить один абзац значит оставить "
                  f"класс на месте")
    else:
        verdict = TABLE_FORM_SAMPLE_BOUND
        reason = (f"форма найдена только в объявленном канале "
                  f"({sample['form_long_line']}), контроль "
                  f"({controls[0]['texts_read'] + controls[1]['texts_read']} "
                  f"текст(ов)) не дал ни одной — починка одного абзаца "
                  f"закрывает класс целиком")

    # Доля таблиц среди широких абзацев с языком права изменения — по каналам.
    # Без неё счёт отвечает о РАЗМЕРЕ канала: в docs/ текстов в сорок раз
    # больше, и большее число там не значит ничего само по себе.
    shares = {}
    for name, data in channels.items():
        denominator = data["wide_authority_paragraphs"]
        shares[name] = {
            "form_any_reason": data["form_any_reason"],
            "wide_authority_paragraphs": denominator,
            "share": (data["form_any_reason"] / denominator
                      if denominator else None),
            "share_reason": ("измерено" if denominator else
                             "широких абзацев с языком права изменения в "
                             "канале нет — доля НЕ ИЗМЕРЕНА, а не равна нулю"),
        }
    return {
        "verdict": verdict,
        "reason": reason,
        "question": ("сколько правил репозитория имеют форму «таблица с "
                     "длинными строками, несущая язык права изменения» — и "
                     "есть ли это свойство ВЫБОРКИ или репозитория"),
        "texts_read": read_total,
        "texts_unreadable": unreadable,
        "sample_form_long_line": sample["form_long_line"],
        "control_form_long_line": control_form,
        "channels": channels,
        "table_share_of_wide_authority": shares,
        "blind": [
            "контроль (`docs/`, ADR) каналом ОБЪЯВЛЕНИЯ не становится и в "
            "`decision_surfaces` не доливает ни строки: он отвечает на вопрос "
            "«редка ли форма», а не «что ещё объявлено»",
            "таблица, отброшенная ЧИСЛОМ строк, формой заказа не является и "
            "в `form_long_line` не входит — пределы защищают от разного, и "
            "одно число на оба ответило бы не на тот вопрос",
            "`docs/decisions/INDEX.md` объявлен реестром, а не каналом "
            "(`ADR_REGISTRY`); его попадание считается отдельно "
            "(`registry_hits`) и в утверждение о репозитории не входит",
            "форма мерит ВИД абзаца, а не вред: таблица с длинной строкой "
            "вредна ровно тем, что мера пути её не читает, — вред этой "
            "координатой не измеряется и владельцу не адресуется",
        ],
    }



# --- ЧИСЛА ВНЕ КАНАЛА ОБЪЯВЛЕНИЯ (заказ G59 п. 2) -------------------------
#
# Координата выше нашла СЕМЬ мест той же формы в `docs/**`. Заказ дословно:
# «замерить, сколько ЧИСЕЛ стоит в этих семи таблицах и сколько из них
# совпадает с порогом, уже известным переписи: если совпадений нет — канал
# верно узок; если есть — молчит не предел, а граница канала».
#
# Вопрос требует различать РАВЕНСТВО ЦИФРЫ и ТОЖДЕСТВО ВЕЛИЧИНЫ, и это не
# придирка: замер 21.09 дал 136 совпадений по голой величине на 365 чисел —
# порог `var_horizon_days = 7` совпадал с номером строки таблицы, с числом
# недель и с «≥4 из 7 дней». Прибор, докладывающий 136, отвечает на вопрос
# «встречается ли такая цифра», а заказ спросил про ПОРОГ.

#: Свидетельства тождества, от сильного к слабому. Порядок существен: пара
#: попадает в ОДИН канал — сильнейший из сработавших, иначе одна и та же пара
#: считалась бы несколько раз и доля «названо» выросла бы сама собой.
EV_NAME_VERBATIM = "name_verbatim"
EV_NAME_TOKEN = "name_token"
EV_NAME_BILINGUAL = "name_token_bilingual"
EV_NAME_NO_UNIT = "name_without_unit"
EV_UNIT = "unit_only"
EV_VALUE = "value_only"

#: Достаточное свидетельство — ИМЯ **и** ЕДИНИЦА вместе, и ни одно из двух по
#: отдельности. Оба ограничения измерены на живом дереве 21.09, и каждое сняло
#: свою ложь:
#:
#: * одна единица без имени — «peg 3 % + vol 5 %» у красной команды несёт
#:   проценты и порогом книги не является;
#: * одно имя без единицы — у `min_paper_days_before_live` различающий токен
#:   ровно один (`paper`), и первая редакция объявила «названными» пять голых
#:   чисел `30` из строк про бумажный трек, включая обломки ISO-дат.
#:
#: Пара «имя есть, единицы нет» не выбрасывается, а уходит в СВОЙ канал
#: (:data:`EV_NAME_NO_UNIT`): вердикта она не решает, но остаётся видимой —
#: иначе нижняя граница ответа пропала бы молча.
_EV_NAMED = (EV_NAME_VERBATIM, EV_NAME_TOKEN, EV_NAME_BILINGUAL)
_EV_ALL = _EV_NAMED + (EV_NAME_NO_UNIT, EV_UNIT, EV_VALUE)

#: Обломок ISO-даты числом не является: `2026-07-11` дало бы три «числа» и
#: подняло бы знаменатель ответа на пустом месте.
_ISO_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}")

OUT_CHANNEL_SILENT = "OUT_OF_CHANNEL_SILENT"
OUT_CHANNEL_NARROW = "OUT_OF_CHANNEL_NARROW"
OUT_CHANNEL_NOTHING = "OUT_OF_CHANNEL_NOTHING_TO_COMPARE"
OUT_CHANNEL_UNMEASURED = "OUT_OF_CHANNEL_UNMEASURED"

#: Вопрос заказа дословно — одной константой, потому что его печатают и
#: отчёт, и артефакт: вторая формулировка рядом была бы ровно той копией
#: правила, которую эта перепись и ищет.
_OUT_CHANNEL_QUESTION = (
    "сколько ЧИСЕЛ стоит в таблицах вне канала объявления и сколько из них "
    "совпадает с порогом, уже известным переписи — и молчит ли предел строки "
    "или граница самого канала"
)

#: Прочтение числа. Обе стороны держат ОДИН порог в РАЗНЫХ единицах:
#: `BASE_CHAIN_CAP = 0.20` у RiskPolicy против `base_chain_pct: 20.0` у
#: витрины. Документ пишет «20 %». Сверка по одной лишь величине связала бы
#: документ с витриной и НЕ связала бы его с RiskPolicy — то есть ответ о
#: том, чей это порог, решала бы единица автора, а не смысл.
READ_AS_WRITTEN = "as_written"
READ_AS_FRACTION = "as_fraction"

#: Имена, ничего не говорящие о ВЕЛИЧИНЕ: они есть почти у каждого порога и
#: совпадают в любом тексте про риск. Оставить их значило бы объявить
#: «названным» всякий абзац со словом «max».
_GENERIC_NAME_TOKENS = frozenset({
    "min", "max", "total", "pct", "usd", "days", "cap", "caps", "per",
    "allocation", "single", "stop", "floor", "ceiling", "for", "new",
    "position", "buffer", "before", "live", "v", "value", "limit",
})

#: Русские соответствия различающих токенов. Карта ОБЪЯВЛЕНА, а не выведена:
#: репозиторий двуязычен по построению (инструкции и `docs/` — по-русски,
#: код — по-английски), и канал имени, умеющий только латиницу, отвечает
#: «никто не называет» о СЕБЕ, а не о дереве. Ровно этим замер 21.09 и
#: закончился: `docs/allocation_logic_explicit.md` держит `BASE_CHAIN_CAP`
#: строкой «Base-цепочка | до 20 % … ADR-025», и латинский канал её не видел.
#: Русская сторона ищется ПОДСТРОКОЙ (язык склоняет: «цепочка/цепочке»), и
#: это объявленное послабление, а не недосмотр.
_TOKEN_SYNONYMS = {
    "chain": ("цепочк", "цепи", "цепь"),
    "cash": ("кэш", "наличн"),
    "drawdown": ("просадк",),
    "protocol": ("протокол",),
    "protocols": ("протокол",),
    "concentration": ("концентрац",),
    "capital": ("капитал",),
    "paper": ("бумаг",),
    "kill": ("стоп-кран", "килл"),
    "switch": ("кран",),
    "held": ("удержан",),
    "horizon": ("горизонт",),
    "confidence": ("доверит",),
    "tvl": ("tvl",),
    "apy": ("apy", "ставк"),
}

#: Число с необязательной единицей. Доллар стоит СЛЕВА и потому спрашивается
#: отдельно; `_` и `,` внутри числа — разделители разрядов автора.
_NUMBER_RE = re.compile(r"(?<![\w.])(\d[\d_]*(?:\.\d+)?)\s*(%|дн|дней|days|ч)?")


def _name_tokens(name: str) -> set:
    """Различающие токены объявленного имени порога."""
    return {t for t in re.split(r"[._]+", name.lower())
            if t and t not in _GENERIC_NAME_TOKENS}


def _name_evidence(line_low: str, declared_name: str) -> Optional[str]:
    """Сильнейший канал имени, которым СТРОКА называет порог, либо ``None``.

    Каналов три и они не складываются: пара уходит в сильнейший сработавший.
    Латинский токен требуется ЦЕЛИКОМ (границы слова) — иначе `t1` совпало бы
    внутри `t10`; русское соответствие ищется подстрокой из-за склонения.
    """
    short = declared_name.split(":", 1)[-1]
    tail = short.split(".")[-1]
    for cand in (short, tail):
        if re.search(r"(?<![\w])" + re.escape(cand) + r"(?![\w])", line_low):
            return EV_NAME_VERBATIM
    return _token_evidence(line_low, _name_tokens(short))


def _token_evidence(line_low: str, tokens: set,
                    synonyms: Optional[dict] = None) -> Optional[str]:
    """Называет ли строка предмет НАБОРОМ различающих токенов, и как именно.

    Вынесено из :func:`_name_evidence` не ради опрятности: правило «каждый
    токен либо латиницей по границам слова, либо русским словом объявленной
    карты» с заказа **G60** спрашивают ДВА разных свидетеля, и вторая копия
    этого правила внутри переписи «одно правило — две копии» была бы ровно тем
    предметом, который перепись и ищет.

    Карта берётся аргументом с умолчанием-`None`, а не читается жёстко: так
    контроль «карта пуста» есть ВХОД меры, а не подмена глобального имени, —
    и одноязычный прогон остаётся измеримым в том же процессе.

    Возвращает :data:`EV_NAME_BILINGUAL` (без русского слова совпадения не
    было бы), :data:`EV_NAME_TOKEN` (хватило одной латиницы) или ``None``.
    """
    if not tokens:
        return None
    table = _TOKEN_SYNONYMS if synonyms is None else synonyms
    bilingual = False
    for token in tokens:
        if re.search(r"(?<![a-z0-9])" + re.escape(token) + r"(?![a-z0-9])",
                     line_low):
            continue
        if any(syn in line_low for syn in table.get(token, ())):
            bilingual = True
            continue
        return None
    return EV_NAME_BILINGUAL if bilingual else EV_NAME_TOKEN


def known_thresholds(root: Path) -> Tuple[Dict[str, List[str]], List[str]]:
    """Пороги, УЖЕ известные переписи: обе объявленные поверхности решения.

    Имя несёт сторону (``RiskPolicy:`` / ``shelf:``), потому что у одной
    величины имён бывает несколько И с разных поверхностей: `0.05` у
    RiskPolicy — сразу `max_drawdown_stop`, `max_var_pct`, `min_cash_pct`.
    Назвать первое попавшееся значило бы соврать тем же способом, против
    которого написан весь прибор (ADR-418).

    RiskPolicy не прочитан ⇒ :class:`NotMeasured`: «совпадений нет» и «не с
    чем сравнивать» — разные ответы заказу, и слить их значило бы выдать
    «не измерено» за «канал верно узок» (инв. #17).
    """
    known: Dict[str, List[str]] = {}
    for key, names in risk_policy_thresholds(root).items():
        known.setdefault(key, []).extend(f"RiskPolicy:{n}" for n in names)
    shelf, shelf_reason = constitution_values(root)
    blind: List[str] = []
    # Спрашивается ПРИЧИНА, а не пустота: `constitution_values` возвращает
    # `({}, причина)`, и ветка «витрина is None» не исполнилась бы никогда —
    # слепота объявлялась бы, а сторожа у неё не было. Пустая витрина без
    # причины — законный ответ (в ней просто нет чисел), и молчать о ней верно.
    if shelf_reason is not None:
        blind.append(
            "витрина порогов сайта НЕ прочитана "
            f"({CONSTITUTION_FILE}): {shelf_reason} — вторая поверхность "
            "решения в сверку не вошла, и ответ есть НИЖНЯЯ граница")
    else:
        for key, names in shelf.items():
            known.setdefault(key, []).extend(f"shelf:{n}" for n in names)
    return {k: sorted(v) for k, v in known.items()}, blind


def _readings(raw: str, unit: Optional[str]) -> List[Tuple[str, str]]:
    """Прочтения числа как ``(ключ величины, имя прочтения)``.

    Процент читается ДВАЖДЫ — как написан и как доля, — потому что обе
    поверхности держат один порог в разных единицах. Второе прочтение НЕ
    подменяет первое: имя прочтения едет с парой, и «20 % = 0.20» никогда не
    выдаётся за «в документе стоит 0.20».
    """
    text = raw.replace("_", "")
    out = [(value_key(text), READ_AS_WRITTEN)]
    if unit == "%":
        try:
            out.append((value_key(str(float(text) / 100)), READ_AS_FRACTION))
        except (TypeError, ValueError):       # не число — прочтения нет
            pass
    return out


def out_of_channel_numbers(root: Path, hits: List[dict]) -> dict:
    """Сколько чисел стои́т вне канала объявления и сколько из них — ПОРОГИ.

    Заказ **G59 п. 2**. Отвечает тремя числами, а не одним, и каждое отвечает
    на свой вопрос:

    * ``numbers_total`` — сколько чисел вообще стои́т в этих таблицах;
    * ``by_evidence[value_only]`` — сколько РАВНО известному порогу и ничем
      больше не подтверждено. Это шум прибора, а не находка: у порога
      ``var_horizon_days = 7`` таким совпадением оказывается номер строки;
    * ``by_evidence`` по трём каналам ИМЕНИ — сколько чисел строка НАЗЫВАЕТ
      порогом. Только это свидетельство достаточно, и только по нему решается
      вердикт.

    **Вердикт отвечает ровно на вопрос заказа.** Есть хоть одна названная
    пара ⇒ :data:`OUT_CHANNEL_SILENT`: молчит граница канала, и починка
    предела класс на месте оставит. Нет ни одной ⇒
    :data:`OUT_CHANNEL_NARROW`.

    **Своя частота ошибки измеряется, а не предполагается** (``enrichment``):
    доля названных среди совпавших по величине делится на долю названных
    среди ВСЕХ чисел. Единица означала бы, что имя не различает ничего и
    работает одна величина.

    Текст не прочитан ⇒ третий исход с причиной (``unreadable``), а не ноль.
    """
    try:
        known, blind = known_thresholds(root)
    except NotMeasured as exc:
        return {
            "verdict": OUT_CHANNEL_UNMEASURED,
            "reason": str(exc),
            "question": _OUT_CHANNEL_QUESTION,
            "tables": len(hits),
            "numbers_total": None,
            "by_evidence": None,
            "by_reading": None,
            "enrichment": None,
            "pairs": [],
            "unreadable": [],
            "blind": [],
        }

    numbers_total = 0
    named_rows = 0
    pairs: List[dict] = []
    unreadable: List[dict] = []
    by_evidence = {name: 0 for name in _EV_ALL}
    by_reading = {READ_AS_WRITTEN: 0, READ_AS_FRACTION: 0}
    tables_read = 0
    cache: Dict[str, Optional[List[str]]] = {}

    for hit in hits:
        rel = hit.get("text")
        if rel not in cache:
            try:
                cache[rel] = (root / rel).read_text(
                    encoding="utf-8").splitlines()
            except Exception as exc:  # noqa: BLE001
                cache[rel] = None
                unreadable.append({"text": rel,
                                   "reason": f"{type(exc).__name__}: {exc}"})
        lines = cache[rel]
        if lines is None:
            continue
        tables_read += 1
        start = int(hit.get("line", 1)) - 1
        block = lines[start:start + int(hit.get("lines", 0))]
        for offset, line in enumerate(block):
            line_low = line.lower()
            # Названо ли в ЭТОЙ строке хоть одно известное имя — знаменатель
            # частоты ошибки: без него «названных мало» было бы свойством
            # текста, а не прибора.
            row_names_any = any(
                _name_evidence(line_low, name) is not None
                for names in known.values() for name in names)
            if row_names_any:
                named_rows += 1
            date_spans = [m.span() for m in _ISO_DATE_RE.finditer(line)]
            for match in _NUMBER_RE.finditer(line):
                if any(lo <= match.start() < hi for lo, hi in date_spans):
                    continue        # обломок ISO-даты числом не является
                numbers_total += 1
                raw, unit = match.group(1), match.group(2)
                dollar = line[max(0, match.start() - 1):match.start()] == "$"
                best: Optional[Tuple[str, str, str]] = None
                bears_unit = bool(unit or dollar)
                for key, reading in _readings(raw, unit):
                    for name in known.get(key, ()):
                        channel = _name_evidence(line_low, name)
                        if channel is None:
                            channel = EV_UNIT if bears_unit else EV_VALUE
                        elif not bears_unit:
                            # Имя без единицы вердикта не решает: величина без
                            # единицы не предъявлена как ТА ЖЕ величина.
                            channel = EV_NAME_NO_UNIT
                        rank = _EV_ALL.index(channel)
                        if best is None or rank < _EV_ALL.index(best[0]):
                            best = (channel, name, reading)
                if best is None:
                    continue
                channel, name, reading = best
                by_evidence[channel] += 1
                by_reading[reading] += 1
                pairs.append({
                    "text": rel,
                    "line": int(hit.get("line", 1)) + offset,
                    "number": raw + (unit or ""),
                    "dollar": dollar,
                    "threshold": name,
                    "evidence": channel,
                    "reading": reading,
                    "quote": line.strip()[:160],
                })

    named = sum(by_evidence[name] for name in _EV_NAMED)
    matched = sum(by_evidence.values())
    # Обогащение: доля названных среди СОВПАВШИХ против доли строк, называющих
    # хоть один порог, среди всех. Знаменатель нулевой ⇒ не измерено, а не 1.0.
    enrichment: Optional[float] = None
    enrichment_reason: Optional[str] = None
    rows_total = sum(int(h.get("lines", 0)) for h in hits)
    if matched and rows_total:
        base_rate = named_rows / rows_total
        if base_rate > 0:
            enrichment = (named / matched) / base_rate
        else:
            enrichment_reason = ("ни одна строка не называет ни одного порога "
                                 "— знаменатель нулевой")
    else:
        enrichment_reason = ("сравнивать нечего: совпадений по величине или "
                             "строк в таблицах ноль")

    if not tables_read and hits:
        verdict = OUT_CHANNEL_UNMEASURED
        reason = ("ни одна из названных таблиц не прочитана — "
                  "«совпадений нет» здесь было бы выдачей «не измерено» за "
                  "«чисто»")
    elif not hits:
        verdict = OUT_CHANNEL_NOTHING
        reason = ("координата формы не назвала ни одного места вне канала — "
                  "сверять нечего")
    elif named:
        verdict = OUT_CHANNEL_SILENT
        reason = (f"{named} из {numbers_total} чисел строка НАЗЫВАЕТ порогом, "
                  f"уже известным переписи: вне объявленного канала стои́т "
                  f"копия порога, и правит её предел строки, а не граница "
                  f"канала")
    else:
        verdict = OUT_CHANNEL_NARROW
        reason = (f"ни одно из {numbers_total} чисел строка порогом не "
                  f"называет; {by_evidence[EV_VALUE]} совпадений — равенство "
                  f"ЦИФРЫ, а не величины")

    return {
        "verdict": verdict,
        "reason": reason,
        "question": _OUT_CHANNEL_QUESTION,
        "tables": len(hits),
        "tables_read": tables_read,
        "rows_total": rows_total,
        "numbers_total": numbers_total,
        "matched_value": matched,
        "named": named,
        "named_rows": named_rows,
        "by_evidence": by_evidence,
        "by_reading": by_reading,
        "enrichment": enrichment,
        "enrichment_reason": enrichment_reason,
        "pairs": pairs,
        "unreadable": unreadable,
        "blind": blind + [
            "канал имени двуязычен ТОЛЬКО по объявленной карте "
            "`_TOKEN_SYNONYMS`: порог, названный прозой без её слов, этой "
            "мерой не находится, и `named` есть НИЖНЯЯ граница",
            "единица необходима, но не достаточна: «peg 3 % + vol 5 %» у "
            "красной команды несёт проценты и порогом книги не является — "
            "поэтому `unit_only` вердикта не решает",
            "координата НЕ докладывает, вредит ли найденная копия: она "
            "называет, что порог стои́т вне канала, а не что он разошёлся",
            "правка найденного числа в `docs/**` предметом этой координаты "
            "НЕ является: величина по соседству с порогом RiskPolicy есть "
            "предмет №1 границы ADR-285 и уезжает карточкой владельцу",
        ],
    }


def axes_intersection(rows: List[dict], peer_rows: List[dict],
                      declared: Dict[str, List[Tuple[str, Optional[str]]]]) -> dict:
    """Пересечение населений двух осей ПО ИМЕНИ (заказ **G53, п. 1**).

    Заказ спросил ЧИСЛОМ, у скольких имён обе оси говорят одновременно: если
    такое имя есть, копий у правила три, а не две. Число здесь ИЗМЕРЯЕТСЯ, а
    затем отдельно измеряется, ПОЧЕМУ оно такое — и это разные вопросы.

    **Ноль сам по себе ответом не является.** Находка первой оси требует у
    имени РОВНО ОДНОГО исполнителя, находка второй — РОВНО ДВУХ. Условия
    несовместимы, поэтому пересечение пусто при любом дереве, включая дерево, в
    котором три копии есть на самом деле. Чтобы «пусто» нельзя было прочесть
    как «таких правил нет», вердикт различает три исхода, а основание
    печатается ЧИСЛАМИ: гистограммы числа исполнителей у имён обеих осей.
    Ключи гистограмм не пересекаются ⇒ ``EMPTY_BY_CONSTRUCTION``; пересекаются,
    а имён общих всё равно нет ⇒ ``EMPTY_MEASURED`` (тогда ноль — свидетельство).

    **Четвёртый исход найден собственным тестом 20.09** и первой редакции этой
    функции стоил бы неправды: если одна из осей пуста, пересекать НЕЧЕГО, и
    гистограммы «не пересекаются» тривиально. Первая редакция объявила бы такой
    ноль структурным, то есть приписала бы устройству прибора свойство дерева.
    Отсюда ``EMPTY_NOTHING_TO_INTERSECT`` с обоими числами в основании.

    Ровно эту форму ответа («прибор молчит о том, чего не видит по построению»)
    разобрал ADR-430 на соседней паре; повторять её молча было бы не ответом, а
    вторым экземпляром той же ошибки.
    """
    axis_one = sorted({r["name"] for r in rows
                       if r.get("verdict") in _FINDING_CLASSES})
    axis_two = sorted({r["name"] for r in peer_rows
                       if r.get("verdict") == CLASS_PEER_TWO_COPIES})

    def histogram(names: List[str]) -> Dict[str, int]:
        out: Dict[str, int] = {}
        for name in names:
            key = str(len(declared.get(name) or []))
            out[key] = out.get(key, 0) + 1
        return out

    hist_one, hist_two = histogram(axis_one), histogram(axis_two)
    shared = sorted(set(axis_one) & set(axis_two))
    if shared:
        verdict = INTERSECTION_NON_EMPTY
    elif not axis_one or not axis_two:
        # Пустая сторона делает пересечение пустым сама по себе, и объявить
        # этот ноль структурным значило бы приписать устройству прибора то,
        # что есть свойство ДЕРЕВА.
        verdict = INTERSECTION_EMPTY_NOTHING_TO_INTERSECT
    elif set(hist_one) & set(hist_two):
        verdict = INTERSECTION_EMPTY_MEASURED
    else:
        verdict = INTERSECTION_EMPTY_BY_CONSTRUCTION
    return {
        "verdict": verdict,
        "names": shared,
        "count": len(shared),
        "axis_one_names": len(axis_one),
        "axis_two_names": len(axis_two),
        "executors_per_name": {"axis_one": hist_one, "axis_two": hist_two},
        "reason": (
            "находка первой оси требует РОВНО ОДНОГО исполнителя, второй — "
            "РОВНО ДВУХ; гистограммы числа исполнителей не пересекаются, "
            "значит ноль здесь СТРУКТУРНЫЙ и свидетельством не является"
            if verdict == INTERSECTION_EMPTY_BY_CONSTRUCTION else
            f"пересекать было НЕЧЕГО: находок у первой оси {len(axis_one)}, у "
            f"второй {len(axis_two)} — ноль пришёл от пустой стороны, а не от "
            f"устройства осей"
            if verdict == INTERSECTION_EMPTY_NOTHING_TO_INTERSECT else
            "число исполнителей у имён обеих осей совпадает хотя бы на одном "
            "значении — пустое пересечение здесь ИЗМЕРЕНО, а не предрешено"
            if verdict == INTERSECTION_EMPTY_MEASURED else
            "имена, о которых говорят ОБЕ оси: у правила три копии, а не две"),
    }


def triple_name_count(rows: List[dict]) -> int:
    """Сколько ИМЁН у находок третьей оси.

    Отдельная функция, а не выражение на месте: строка «N пар на M имён» —
    главное число оси, а строка `triple_door_unmeasured` именем НАХОДКИ не
    является. Правило «что здесь считается именем» обязано быть одно и
    проверяемое тестом: замер 20.09 дал 18 пар на ОДНОМ имени, и спутать их
    значило бы соврать масштабом в восемнадцать раз.
    """
    return len({r["name"] for r in rows if r.get("verdict") == CLASS_TRIPLE})


def triple_copies(peer_rows: List[dict],
                  guard_declared: Dict[str, List[Tuple[str, Optional[str]]]],
                  *, source_of, imports_of,
                  thresholds: Dict[str, List[str]],
                  constitution: Dict[str, List[str]],
                  constitution_unread: Optional[str]) -> Tuple[List[dict], dict]:
    """ТРИ копии одного правила: сторож × два исполнителя (заказ **G53, п. 1**).

    Координата, которой у пересечения осей нет и быть не может (см.
    :func:`axes_intersection`): имя, объявленное сторожем И ровно двумя
    исполнителями, значение у всех трёх сторон равно, а сторож не достаёт НИ
    ОДНОГО из исполнителей ни одной из четырёх дверей.

    ## Почему сторону-сторожа мало просто «добавить» к паре исполнителей

    Сторож, который достаёт ОДНОГО из двух исполнителей, третьей копии не
    держит — у него копия одна, чужая, и правка доедет. Такой случай кладётся в
    свою корзину (``triple_door_to_one``), а не в находку: смешать его с
    находкой значило бы посчитать копией ввоз.

    ## Равное имя при РАЗНОМ значении находкой не является

    Замер 20.09 даёт такую пару ровно одну: ``SILENT`` у сторожа значит
    ``'pendle'``, а у двух исполнителей — литерал ``'SILENT'``. Это соглашение
    об именовании, а не разошедшиеся копии, и объявить его расхождением было бы
    выдумкой той же природы, что объявить совпадение копией. Корзина своя
    (``triple_value_differs``), находкой не считается.

    ## Право чинить спрашивается ПЕРВЫМ и у ДВУХ поверхностей решения

    Порядок тот же, что у соседних осей (заказ G42 п. 1), но поверхностей здесь
    две: пороги RiskPolicy и витрина порогов сайта (``CONSTITUTION_FILE``).
    Вторая добавлена замером, а не для полноты: единственная находка этой оси —
    ``CAPITAL = 100000.0``, и то же число объявлено витриной полем
    ``start_capital_usd``, то есть это РЕШЕНИЕ, меняемое ADR-ом
    (`.claude/rules/site-numbers.md`). Починить его «ввозом» агент не вправе.

    Витрина не прочитана ⇒ ``REMEDY_RIGHT_UNMEASURED``, а не «совпадений нет».
    """
    counts = {cls: 0 for cls in _TRIPLE_CLASSES}
    rows: List[dict] = []
    for peer in peer_rows:
        if peer.get("verdict") != CLASS_PEER_TWO_COPIES:
            continue
        name = peer["name"]
        for guard_rel, guard_value in guard_declared.get(name, []):
            if guard_value is None:
                counts[CLASS_TRIPLE_NOT_CONSTANT] += 1
                continue
            if guard_value != peer["value"]:
                counts[CLASS_TRIPLE_VALUE_DIFFERS] += 1
                continue
            source = source_of(guard_rel)
            if source is None:
                # Молчаливое «дверь закрыта» превратило бы нечитаемый файл в
                # находку — та же подмена, что у соседней оси.
                counts[CLASS_TRIPLE_UNMEASURED] += 1
                rows.append({
                    "verdict": CLASS_TRIPLE_UNMEASURED, "name": name,
                    "value": guard_value, "guard": guard_rel,
                    "left": peer["left"], "right": peer["right"],
                    "reason": "текст сторожа не перечитан — вопрос о двери не измерен"})
                continue
            imports = imports_of(guard_rel)
            doors = [reaches(source, imports, peer["left"]),
                     reaches(source, imports, peer["right"])]
            if all(doors):
                counts[CLASS_TRIPLE_DOOR_BOTH] += 1
                continue
            if any(doors):
                counts[CLASS_TRIPLE_DOOR_ONE] += 1
                continue
            counts[CLASS_TRIPLE] += 1
            # Право чинить спрашивается ОБЩЕЙ функцией (G54 п. 1). До неё это
            # правило жило здесь своей копией — в приборе, который меряет
            # вторые копии правил; ровно ту форму починки
            # (`single_copy_by_import`) он и прописывает другим.
            remedy, evidence, extra = right_to_fix(
                guard_value, thresholds=thresholds, constitution=constitution,
                constitution_unread=constitution_unread)
            if remedy is None:
                remedy = REMEDY_UNPROVEN
                evidence = (
                    "сторож не достаёт ни одного исполнителя, исполнители не "
                    "достают друг друга — копия своя у всех трёх; общего "
                    "происхождения значения прибор не доказывает")
            rows.append({
                "verdict": CLASS_TRIPLE,
                "name": name,
                "value": guard_value,
                "guard": guard_rel,
                "left": peer["left"],
                "right": peer["right"],
                "remedy": remedy,
                "remedy_evidence": evidence,
                **extra,
            })
    rows.sort(key=lambda r: (r["name"], r["guard"], r["left"], r["right"]))
    return rows, counts


#: Вердикт сдвига формы починки (заказ G54 п. 1). Четыре исхода, и четвёртый
#: существует затем, чтобы ноль нельзя было выдать за ответ: величина, не
#: являющаяся числом, витрине не предъявляется ПО ПОСТРОЕНИЮ, и ось, где таких
#: величин все до одной, отвечает «сравнивать было нечего», а не «сдвига нет».
SHIFT_MEASURED = "SHIFTED"
SHIFT_NONE_MEASURED = "NO_SHIFT_MEASURED"
SHIFT_NOTHING_COMPARABLE = "NOTHING_COMPARABLE"
SHIFT_UNMEASURED = "RIGHT_TO_FIX_UNMEASURED"


def constitution_shift(rows: List[dict], *, finding_classes: Tuple[str, ...],
                       constitution_unread: Optional[str]) -> dict:
    """Что купил оси вопрос к витрине порогов (заказ **G54, п. 1**).

    Заказ поставлен был так: «замерить, сколько из 9 и 189 пар сменили бы форму
    починки, если бы витрину спросили и у них». Замер сделан — и раз он вышел
    ненулевым, вопрос задан всем трём осям, а не оставлен третьей. Поэтому
    координата мерит не гипотезу, а СДВИГ, уже произошедший в строках:
    ``remedy_without_shelf`` хранит форму, которая была у пары, пока право
    чинить спрашивалось у одной поверхности решения.

    **Знаменатель сужен намеренно и это сказано числом.** Витрина держит
    только ЧИСЛА (:func:`is_numeric_value`), поэтому пара со строковым
    значением сменить форму не могла ни при каком дереве. Сложить её в
    знаменатель значило бы разбавить замер вопросом, который ей не задавался,
    — тот же дефект, что и «ноль по построению, объявленный чистотой»
    (ADR-431).

    **Витрина не прочитана ⇒ :data:`SHIFT_UNMEASURED`**, и это не «сдвига
    нет»: при нечитаемой витрине каждая пара без порога RiskPolicy получает
    `right_to_fix_unmeasured`, то есть сдвиг как раз МАКСИМАЛЕН.
    """
    population = [r for r in rows if r.get("verdict") in finding_classes]
    owner = [r for r in population if r.get("remedy") == REMEDY_OWNER]
    rest = [r for r in population if r.get("remedy") != REMEDY_OWNER]
    comparable = [r for r in rest if is_numeric_value(r.get("value"))]
    silent = [r for r in rest if not is_numeric_value(r.get("value"))]
    moved = [r for r in population if r.get("remedy_without_shelf")]
    transitions: Dict[str, int] = {}
    for row in moved:
        key = f"{row['remedy_without_shelf']} → {row['remedy']}"
        transitions[key] = transitions.get(key, 0) + 1
    if constitution_unread is not None:
        verdict = SHIFT_UNMEASURED
        reason = constitution_unread
    elif moved:
        verdict = SHIFT_MEASURED
        reason = (f"{len(moved)} из {len(comparable)} сравнимых пар сменили "
                  f"форму починки — право чинить у них было НЕ спрошено до конца")
    elif comparable:
        verdict = SHIFT_NONE_MEASURED
        reason = (f"витрину спросили у {len(comparable)} сравнимых пар, ни одно "
                  f"значение ей не объявлено — ноль ИЗМЕРЕН, а не структурен")
    else:
        verdict = SHIFT_NOTHING_COMPARABLE
        reason = ("сравнимых пар нет вовсе: у всех значение не число, и витрина "
                  "о них молчит ПО ПОСТРОЕНИЮ — это не «сдвига нет»")
    return {
        "verdict": verdict,
        "reason": reason,
        "population": len(population),
        "owner_by_threshold": len(owner),
        "comparable": len(comparable),
        "silent_by_construction": len(silent),
        "moved": len(moved),
        "transitions": transitions,
        "moved_names": sorted({f"{r['name']} = {r['value']}" for r in moved}),
    }


# ─── координата: ДОСЯГАЕМОСТЬ ДВУЯЗЫЧИЯ (заказ G60 пп. 1–2) ─────────────────
#
# ADR-437 нашёл, что канал имени был ОДНОЯЗЫЧНЫМ: латинский прибор в двуязычном
# репозитории отвечает «никто не называет» О СЕБЕ. Заказ G60 п. 1 ставит вопрос
# шире и не даёт ответа заранее: одноязычие — свойство ОДНОЙ координаты или
# ВСЕХ свидетелей имени? Здесь у вопроса появляется число, и у каждого нуля —
# свой знаменатель.

#: Вердикт координаты. Четыре, и три последних НЕ являются «чисто»: «карта
#: спрошена и ничего не сдвинула», «спрашивать нечем» и «не измерено» суть
#: разные ответы заказу (инв. #17).
BILINGUAL_SHIFT = "BILINGUAL_REACH_SHIFT"
BILINGUAL_INERT = "BILINGUAL_REACH_INERT"
BILINGUAL_NOTHING_TO_ASK = "BILINGUAL_REACH_NOTHING_TO_ASK"
BILINGUAL_UNMEASURED = "BILINGUAL_REACH_UNMEASURED"

#: Имена свидетелей, у которых заказ спрашивает одноязычие.
WITNESS_SUBJECT = "subject_witness"
WITNESS_NAME_CHANNEL = "declared_by_name"

#: Кириллица в тексте. Нужна ровно для одного вопроса: не вырожден ли ноль ПО
#: ЯЗЫКУ — если ни одна сторона населения по-русски не написана, спрашивать
#: двуязычие не о чем, и ноль был бы свойством выборки, а не карты.
_CYRILLIC_RE = re.compile(r"[Ѐ-ӿ]")


def _module_tokens(module_rel: str) -> set:
    """Различающие токены ИМЕНИ ФАЙЛА исполнителя (без каталогов).

    Каталог в токены не берётся намеренно: `spa_core`/`monitoring` стоят у
    половины дерева и различающими не являются — карта, спрошенная о них,
    отвечала бы о частоте каталога, а не о предмете.
    """
    if not module_rel.endswith(".py"):
        return set()
    return _name_tokens(module_rel[:-3].split("/")[-1])


def _module_named_bilingually(text: str, module_rel: str,
                              synonyms: Optional[dict] = None) -> Optional[str]:
    """Называет ли ТЕКСТ модуль `module_rel` ТОЛЬКО через русское слово карты.

    Зеркало :func:`subject_witness` для двуязычного канала и строго слабее
    его: латинский свидетель спрашивается ПЕРВЫМ, и сработавший снимает
    вопрос. Иначе число «сколько добавило двуязычие» включало бы пары, у
    которых свидетель и так есть, — то есть отвечало бы о населении, а не о
    прибавке.
    """
    if subject_witness(text, module_rel) is not None:
        return None
    tokens = _module_tokens(module_rel)
    if _token_evidence(text.lower(), tokens, synonyms) != EV_NAME_BILINGUAL:
        return None
    return module_rel[:-3].split("/")[-1]


def _row_sides(row: dict) -> List[Tuple[str, str]]:
    """Стороны строки переписи, какой бы осью она ни была найдена.

    Оси три и формы строк у них разные (`guard`/`executor`, `left`/`right`,
    тройка). Свести их здесь обязательно: спросить двуязычие у одной оси
    значило бы измерить ось, а не репозиторий, — той же ошибкой, что ADR-436
    назвал свойством ВЫБОРКИ.
    """
    sides: List[Tuple[str, str]] = []
    left, right = row.get("left"), row.get("right")
    guard, executor = row.get("guard"), row.get("executor")
    if left and right:
        sides.append((left, right))
        if guard:
            sides.append((guard, left))
            sides.append((guard, right))
    elif guard and executor:
        sides.append((guard, executor))
    return sides


def synonym_map_coverage(root: Path,
                         synonyms: Optional[dict] = None) -> dict:
    """Полнота карты синонимов по порогам, УЖЕ известным переписи (**G60 п. 2**).

    Заказ дословно: «взять различающие токены ВСЕХ известных переписи порогов
    и посчитать, у скольких из них русского соответствия в карте нет вовсе.
    Пока это число неизвестно, „нижняя граница“ — слово, а не величина».

    Карта построена руками, и полнота её меряется ТОЛЬКО по порогам, которые
    перепись уже знает: порог, не объявленный ни одной поверхностью решения,
    этой мере не виден, и сказано это вслух, а не подразумевается.

    Пороги не прочитаны ⇒ ``status = UNMEASURED`` с причиной: «карта полна» и
    «сравнивать не с чем» — разные ответы.
    """
    table = _TOKEN_SYNONYMS if synonyms is None else synonyms
    try:
        known, blind = known_thresholds(root)
    except NotMeasured as exc:
        return {"status": BILINGUAL_UNMEASURED,
                "reason": f"пороги переписи не прочитаны: {exc}"}
    names = sorted({n for group in known.values() for n in group})
    if not names:
        return {"status": BILINGUAL_UNMEASURED,
                "reason": ("переписи не известен НИ ОДИН порог — полноту "
                           "карты мерить не на чем")}
    tokens_all: set = set()
    missing: set = set()
    full = partly = uncovered = nameless = 0
    for name in names:
        tokens = _name_tokens(name.split(":", 1)[-1].split(".")[-1])
        if not tokens:
            nameless += 1
            continue
        tokens_all |= tokens
        absent = {t for t in tokens if t not in table}
        missing |= absent
        if not absent:
            full += 1
        elif len(absent) < len(tokens):
            partly += 1
        else:
            uncovered += 1
    return {
        "status": "MEASURED",
        "map_entries": len(table),
        "thresholds": len(names),
        "fully_covered": full,
        "partly_covered": partly,
        "not_covered": uncovered,
        "without_distinguishing_tokens": nameless,
        "tokens": len(tokens_all),
        "tokens_without_russian": len(missing),
        "missing_tokens": sorted(missing),
        "blind": list(blind),
    }


def bilingual_subject_reach(root: Path, rows: List[dict],
                            synonyms: Optional[dict] = None) -> dict:
    """Меняется ли вердикт :func:`subject_witness` от карты синонимов (**G60 п. 1**).

    Свидетель спрашивает у текста ИМЯ МОДУЛЯ. Заказ предполагает, что он
    одноязычен так же, как был одноязычен канал порога; проверяется это
    замером, а не согласием.

    **Ноль здесь обязан ехать со своим знаменателем.** «Карта ничего не
    сдвинула» и «карту ни разу не спросили» — разные ответы, и различает их
    ``askable``: сколько модулей населения вообще МОГЛИ быть названы по-русски
    (все различающие токены имени файла есть в карте). Отдельно считается
    ``cyrillic_sides`` — не вырожден ли вопрос по языку самих сторон.

    Ни один текст населения не прочитан ⇒ ``status = UNMEASURED``.
    """
    table = _TOKEN_SYNONYMS if synonyms is None else synonyms
    cache: Dict[str, Optional[str]] = {}

    def text(rel: str) -> Optional[str]:
        if rel not in cache:
            try:
                cache[rel] = (root / rel).read_text(encoding="utf-8")
            except Exception:  # noqa: BLE001
                cache[rel] = None
        return cache[rel]

    modules: set = set()
    changed: List[dict] = []
    pairs_read = 0
    for row in rows:
        sides = _row_sides(row)
        if not sides:
            continue
        latin = False
        gained: List[Tuple[str, str]] = []
        read_any = False
        for near, far in sides:
            modules.add(near)
            modules.add(far)
            near_text, far_text = text(near), text(far)
            if near_text is None or far_text is None:
                continue
            read_any = True
            if subject_witness(near_text, far) or subject_witness(far_text, near):
                latin = True
            for source, target in ((near_text, far), (far_text, near)):
                witness = _module_named_bilingually(source, target, table)
                if witness is not None:
                    gained.append((target, witness))
        if read_any:
            pairs_read += 1
        if not latin and gained:
            changed.append({
                "name": row.get("name"),
                "value": row.get("value"),
                "remedy": row.get("remedy"),
                "sides": [f"{a} × {b}" for a, b in sides],
                "witness": sorted({f"{t} -> {w}" for t, w in gained}),
            })
    if not pairs_read:
        return {"status": BILINGUAL_UNMEASURED,
                "reason": ("ни одна сторона населения не прочитана — вердикт "
                           "свидетеля предмета НЕ ИЗМЕРЕН"),
                "population": len(rows)}
    askable = sorted(m for m in modules
                     if _module_tokens(m) and _module_tokens(m) <= set(table))
    asked = sorted(m for m in modules if _module_tokens(m) & set(table))
    cyrillic = sorted(m for m in modules
                      if (text(m) or "") and _CYRILLIC_RE.search(text(m) or ""))
    return {
        "status": "MEASURED",
        "population": len(rows),
        "pairs_read": pairs_read,
        "modules": len(modules),
        "askable": len(askable),
        "askable_sample": askable[:5],
        "token_overlap": len(asked),
        "cyrillic_sides": len(cyrillic),
        "changed": len(changed),
        "changed_rows": changed,
    }


def _module_constants(root: Path, rel: str,
                      cache: Dict[str, Dict[str, float]]) -> Dict[str, float]:
    """Числовые имена верхнего уровня одного файла. Кэш — аргумент, не глобаль."""
    if rel in cache:
        return cache[rel]
    found: Dict[str, float] = {}
    try:
        tree = ast.parse((root / rel).read_text(encoding="utf-8"))
    except Exception:  # noqa: BLE001
        cache[rel] = found
        return found
    for node in ast.walk(tree):
        pairs: List[Tuple[str, ast.AST]] = []
        if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name) \
                and node.value is not None:
            pairs.append((node.target.id, node.value))
        elif isinstance(node, ast.Assign):
            pairs += [(t.id, node.value) for t in node.targets
                      if isinstance(t, ast.Name)]
        for name, value in pairs:
            if isinstance(value, ast.Constant) \
                    and isinstance(value.value, (int, float)) \
                    and not isinstance(value.value, bool):
                found.setdefault(name, float(value.value))
    cache[rel] = found
    return found


def _paragraph_values(raw: str) -> set:
    """Величины, названные абзацем, В ОБОИХ ПРОЧТЕНИЯХ.

    Причина та же, что у ADR-437: один порог живёт у двух поверхностей в
    РАЗНЫХ единицах (`0.05` у RiskPolicy, `5.0` у витрины, «5 %» в тексте).
    Сверка по одной написанной величине связала бы абзац с одной стороной и
    НЕ связала бы с другой — ответ решала бы единица автора.
    """
    values: set = set()
    for match in _NUMBER_RE.finditer(raw):
        try:
            number = float(match.group(1).replace("_", ""))
        except ValueError:
            continue
        values.add(value_key(str(number)))
        values.add(value_key(str(number / 100)))
    return values


def bilingual_name_reach(root: Path, index: Dict[str, List[str]],
                         synonyms: Optional[dict] = None) -> dict:
    """Что даёт карта синонимов каналу ОБЪЯВЛЕНИЯ ИМЕНЕМ (**G60 п. 1**).

    Канал имени (:func:`declared_by_name`) спрашивает у правила ДОСЛОВНЫЙ
    идентификатор в обратных кавычках. Двуязычная его версия спрашивает
    предмет НАБОРОМ токенов — и это не «тот же канал по-русски», а строго
    более слабый канал. Поэтому здесь меряются три числа, и смешивать их
    нельзя:

    * ``raw`` — сколько имён абзац называет токенами через русское слово;
    * ``corroborated`` — у скольких из них величина имени СТОИ́Т В ТОМ ЖЕ
      абзаце (фильтр обозримости, а не доказательство: равное число называет
      несколько порогов, ADR-418);
    * те же два числа на КОНТРОЛЕ — абзацах БЕЗ языка права изменения. Без
      контроля «канал нашёл 59» неотличимо от «токены разрешаются с такой
      частотой везде», и подтверждающий прибор подтверждал бы сам себя.

    Ни один текст правил не прочитан ИЛИ индекс дерева пуст ⇒ ``UNMEASURED``.
    """
    table = _TOKEN_SYNONYMS if synonyms is None else synonyms
    texts: List[Path] = []
    rule_text = root / RULE_TEXT
    if rule_text.is_file():
        texts.append(rule_text)
    rules_dir = root / RULE_DIR
    if rules_dir.is_dir():
        texts.extend(sorted(rules_dir.glob("*.md")))
    if not texts or not index:
        return {"status": BILINGUAL_UNMEASURED,
                "reason": ("текстов правил нет" if not texts
                           else "индекс определений дерева пуст — "
                                "разрешать имена нечем")}
    candidates = {name: where[0] for name, where in index.items()
                  if len(where) == 1 and _name_tokens(name)
                  and _name_tokens(name) <= set(table)}
    counts = {"authority_paragraphs": 0, "control_paragraphs": 0,
              "authority_raw": 0, "control_raw": 0,
              "authority_numeric": 0, "control_numeric": 0,
              "authority_corroborated": 0, "control_corroborated": 0}
    pairs: List[dict] = []
    raw_hits: List[dict] = []
    unreadable: List[dict] = []
    constants: Dict[str, Dict[str, float]] = {}
    read = 0
    for path in texts:
        rel_text = path.relative_to(root).as_posix()
        try:
            body = path.read_text(encoding="utf-8")
        except Exception as exc:  # noqa: BLE001
            unreadable.append({"text": rel_text,
                               "reason": f"{type(exc).__name__}: {exc}"})
            continue
        read += 1
        for block in declaring_paragraphs(body):
            raw = "\n".join(line for _, line in block)
            low = raw.lower()
            side = ("authority"
                    if any(mark in low for mark in AUTHORITY_MARKS)
                    else "control")
            counts[f"{side}_paragraphs"] += 1
            verbatim = set(_DECLARED_NAME_RE.findall(raw))
            values = _paragraph_values(raw)
            for name, where in candidates.items():
                if name in verbatim:
                    continue
                if _token_evidence(low, _name_tokens(name),
                                   table) != EV_NAME_BILINGUAL:
                    continue
                counts[f"{side}_raw"] += 1
                value = _module_constants(root, where, constants).get(name)
                # Население канала ЗАПИСЫВАЕТСЯ целиком, а не только та его
                # часть, которую подтвердила величина: заказ **G61 п. 1**
                # спрашивает точность канала, а посчитанное и не записанное
                # срабатывание разметить нечем — «59 названных» осталось бы
                # числом без предметов.
                raw_hits.append({
                    "side": side,
                    "text": rel_text,
                    "block_start": block[0][0],
                    "named_as": name,
                    "resolved": where,
                    "value": value,
                })
                if value is None:
                    continue
                counts[f"{side}_numeric"] += 1
                if value_key(str(value)) not in values:
                    continue
                counts[f"{side}_corroborated"] += 1
                if side != "authority":
                    continue
                pairs.append({
                    "text": rel_text,
                    "line": block[0][0],
                    "named_as": name,
                    "resolved": where,
                    "value": value,
                    "quote": raw.strip().splitlines()[0][:160],
                })
    if not read:
        return {"status": BILINGUAL_UNMEASURED,
                "reason": "ни один текст правил не прочитан",
                "unreadable": unreadable}
    enrichment, enrichment_reason = _rate_enrichment(
        counts["authority_raw"], counts["authority_paragraphs"],
        counts["control_raw"], counts["control_paragraphs"])
    return {
        "status": "MEASURED",
        "texts_read": read,
        "unreadable": unreadable,
        "candidates": len(candidates),
        "pairs": pairs,
        "raw_hits": raw_hits,
        "enrichment": enrichment,
        "enrichment_reason": enrichment_reason,
        **counts,
    }


def _rate_enrichment(hits: int, population: int,
                     control_hits: int,
                     control_population: int) -> Tuple[Optional[float],
                                                       Optional[str]]:
    """Во сколько раз канал чаще срабатывает на объявлении, чем на контроле.

    Ноль в знаменателе — ТРЕТИЙ ИСХОД с причиной, а не подставленная единица:
    сочинённое число вместо «не измерено» есть ровно тот дефект, который
    батарея мутаций ADR-437 нашла у первой редакции соседней координаты.
    """
    if not population or not control_population:
        return None, ("населения объявлений нет" if not population
                      else "контрольных абзацев нет — сравнивать частоту не с чем")
    if not control_hits:
        return None, ("контроль не сработал ни разу: отношение к нулю есть "
                      "бесконечность, а не «канал безупречен»")
    return ((hits / population) / (control_hits / control_population)), None


#: Правило разметки заказа **G61 п. 1**, записанное ДО разметки и не менявшееся
#: после первого прогона. Свободных параметров, подогнанных по данным, у него
#: нет: три свидетеля и таблица истинности — весь состав.
PRECISION_RULE = (
    "население — ВСЕ срабатывания канала имени (`raw_hits`), а не только "
    "подтверждённые величиной; свидетели: W1 — все токены имени стои́т в ОДНОМ "
    "пункте абзаца (тот же `_token_evidence`, более узкая область), W2 — абзац "
    "называет разрешённый модуль дословно по основе файла — полный путь её "
    "содержит и потому отдельной ветки не требует, — W3 — абзац "
    "несёт величину имени в любом из двух прочтений; "
    "GENUINE = W1 и (W2 или W3) · ARTEFACT = не W1 · UNDECIDED = W1 без W2 и W3"
)

def truth_interval(genuine: int, undecided: int,
                   labelled: int) -> Optional[dict]:
    """Интервал истины канала: нижняя граница — `GENUINE`, верхняя — с `UNDECIDED`.

    Формула объявлена ОДИН раз намеренно: её спрашивают и разметка
    (**G61 п. 1**), и цена сужения (**G62 п. 1**), а вторая её копия была бы
    ровно тем предметом, который эта перепись ищет у чужого кода (ADR-417).

    Пустое население ⇒ ``None``, а не интервал ``[0, 0]``: «не измерено» и
    «измерено и равно нулю» обязаны быть различимы (инв. #17).
    """
    if not labelled:
        return None
    return {"lower": genuine / labelled,
            "upper": (genuine + undecided) / labelled,
            "denominator": labelled}


PRECISION_UNMEASURED = "BILINGUAL_PRECISION_UNMEASURED"
LABEL_GENUINE = "GENUINE"
LABEL_ARTEFACT = "ARTEFACT"
LABEL_UNDECIDED = "UNDECIDED"

#: Начало ПУНКТА внутри абзаца: маркер списка, строка таблицы, заголовок.
_ITEM_START_RE = re.compile(r"^\s*(?:[-*+]\s|\d+[.)]\s|\||#{1,6}\s)")


def declaring_items(block: List[Tuple[int, str]]) -> List[Tuple[int, str]]:
    """Абзац, разбитый на ПУНКТЫ; перенос строки пункт НЕ разрывает.

    Область совпадения токенов у канала имени — абзац целиком, и это его
    измеряемое свойство: чем шире абзац, тем больше в нём чужих слов. Узкая
    область нужна, чтобы спросить «а переживёт ли срабатывание сужение», но
    физическая СТРОКА для этого слишком узка: авторский перенос внутри одного
    маркера списка разорвал бы настоящее объявление и записал бы его в ложные.
    Поэтому область — пункт: строка-маркер вместе со своими продолжениями.
    Цена этого выбора не скрыта, а измерена — :func:`bilingual_name_precision`
    считает и совпадения по строке, и разницу между двумя областями.
    """
    items: List[Tuple[int, List[str]]] = []
    for lineno, line in block:
        if not items or _ITEM_START_RE.match(line):
            items.append((lineno, [line]))
        else:
            items[-1][1].append(line)
    return [(lineno, "\n".join(lines)) for lineno, lines in items]


def paragraph_at(root: Path, rel: str, block_start: object,
                 cache: Dict[str, Dict[int, List[Tuple[int, str]]]]
                 ) -> Tuple[Optional[List[Tuple[int, str]]], Optional[str]]:
    """Абзац населения по координате «файл + строка начала» — ОДНА копия.

    Координату населения разрешают ДВЕ координаты переписи (разметка канала
    имени — **G61 п. 1** — и цена свидетелей абзаца — **G63 п. 1**), и вторая
    копия этого разрешения внутри переписи «одно правило — две копии» была бы
    ровно тем предметом, который перепись ищет у чужого кода (ADR-417).

    Возвращает ``(абзац, причина)``: ровно один из двух не ``None``. Отказ
    чтения и отсутствие абзаца по координате — РАЗНЫЕ причины и чинятся в
    разных местах, поэтому сливать их в одно «не разрешилось» нельзя (инв. #17).
    """
    if not isinstance(block_start, int) or isinstance(block_start, bool):
        return None, (f"координата абзаца записана как "
                      f"{type(block_start).__name__}, а не номером строки — "
                      f"разрешать нечего")
    blocks = cache.get(rel)
    if blocks is None:
        try:
            body = (root / rel).read_text(encoding="utf-8")
        except Exception as exc:  # noqa: BLE001
            cache[rel] = {}
            return None, f"{type(exc).__name__}: {exc}"
        blocks = {block[0][0]: block for block in declaring_paragraphs(body)}
        cache[rel] = blocks
    block = blocks.get(block_start)
    if block is None:
        return None, (f"абзаца, начинающегося строкой {block_start}, в тексте "
                      f"нет — координата населения не разрешается")
    return block, None


def _module_named(raw_low: str, where: str) -> bool:
    """Назван ли в самом абзаце РАЗРЕШЁННЫЙ модуль — свидетель вне токенов.

    Свидетель независим от канала, который проверяется: путь и основа файла
    пишутся латиницей и в карте синонимов не участвуют. Основа спрашивается по
    границам слова — иначе `policy` совпало бы внутри `risk_policy_v2`.

    Отдельной ветки «назван полный путь» здесь НЕТ, и это замер, а не
    недосмотр: внутри собственного пути основа всегда обрамлена `/` и `.`, ни
    один из которых не входит в `[a-z0-9_]`, — поэтому проверка по границам
    слова срабатывает везде, где сработала бы проверка по пути. Батарея мутаций
    #658 оставила такую ветку в живых, и это её приговор, а не её оправдание.
    """
    if not where:
        return False
    stem = where.rsplit("/", 1)[-1].rsplit(".", 1)[0].lower()
    return bool(stem) and bool(re.search(
        r"(?<![a-z0-9_])" + re.escape(stem) + r"(?![a-z0-9_])", raw_low))


def bilingual_name_precision(root: Path, channel: Optional[dict],
                             synonyms: Optional[dict] = None) -> dict:
    """Точность двуязычного канала имени на ОБЪЯВЛЕННОЙ выборке (**G61 п. 1**).

    ADR-438 назвал «2 из 4» — замер выборки размера четыре, у которого нет
    доверительного интервала никакого, и сделан он одной парой глаз. Здесь
    размечается ВСЁ население канала по правилу :data:`PRECISION_RULE`,
    записанному ДО разметки, и доля ложных называется со знаменателем.

    Контроль размечается ТЕМ ЖЕ правилом и не для симметрии: абзац без языка
    права изменения объявлением не является, поэтому доля `GENUINE` на
    контроле есть частота ошибки САМОГО правила разметки. Без неё «правило
    назвало N ложных» было бы утверждением, которое нечем поверить, —
    подтверждающий прибор подтверждал бы сам себя.

    Канал не измерен, населения нет или ни один абзац не найден по координате
    ⇒ ``UNMEASURED`` с причиной. Пустое население НЕ есть «ложных ноль».
    """
    table = _TOKEN_SYNONYMS if synonyms is None else synonyms
    if not isinstance(channel, dict) or channel.get("status") != "MEASURED":
        return {"status": PRECISION_UNMEASURED, "rule": PRECISION_RULE,
                "reason": "канал имени не измерен — размечать нечего"}
    hits = channel.get("raw_hits")
    if hits is None:
        return {"status": PRECISION_UNMEASURED, "rule": PRECISION_RULE,
                "reason": ("канал имени не выдал населения: срабатывания "
                           "посчитаны и не записаны — размечать нечем")}
    if not hits:
        return {"status": PRECISION_UNMEASURED, "rule": PRECISION_RULE,
                "reason": ("канал не сработал ни разу: населения нет — это НЕ "
                           "«ложных ноль», а отсутствие предмета разметки")}

    blocks_cache: Dict[str, Dict[int, List[Tuple[int, str]]]] = {}
    sides: Dict[str, dict] = {}
    rows: List[dict] = []
    unresolved: List[dict] = []
    for hit in hits:
        rel = str(hit.get("text") or "")
        block, why = paragraph_at(root, rel, hit.get("block_start"),
                                  blocks_cache)
        if block is None:
            unresolved.append({"text": rel, "named_as": hit.get("named_as"),
                               "reason": why})
            continue
        tokens = _name_tokens(str(hit.get("named_as") or ""))
        raw = "\n".join(line for _, line in block)
        raw_low = raw.lower()
        item_line = next(
            (lineno for lineno, item in declaring_items(block)
             if _token_evidence(item.lower(), tokens, table) is not None), None)
        line_hit = any(_token_evidence(line.lower(), tokens, table) is not None
                       for _, line in block)
        subject = _module_named(raw_low, str(hit.get("resolved") or ""))
        value = hit.get("value")
        named_value = (value is not None
                       and value_key(str(value)) in _paragraph_values(raw))
        if item_line is None:
            label = LABEL_ARTEFACT
        elif subject or named_value:
            label = LABEL_GENUINE
        else:
            label = LABEL_UNDECIDED
        side = str(hit.get("side") or "")
        tally = sides.setdefault(side, {LABEL_GENUINE: 0, LABEL_ARTEFACT: 0,
                                        LABEL_UNDECIDED: 0,
                                        "colocated_line": 0,
                                        "colocated_item": 0})
        tally[label] += 1
        tally["colocated_line"] += 1 if line_hit else 0
        tally["colocated_item"] += 1 if item_line is not None else 0
        # Размер набора токенов — НЕ вход правила, а объяснение его исхода:
        # имя из ОДНОГО различающего токена спрашивает у текста одно русское
        # слово, и «назвал» там значит «слово встретилось». Правило объявлено
        # до разметки и этим числом не правится; оно печатается, чтобы
        # причина доли была названа, а не угадана по примерам.
        by_size = tally.setdefault("by_token_count", {})
        cell = by_size.setdefault(str(len(tokens)), {LABEL_GENUINE: 0,
                                                     LABEL_ARTEFACT: 0,
                                                     LABEL_UNDECIDED: 0})
        cell[label] += 1
        rows.append({
            "side": side, "text": rel, "block_start": hit.get("block_start"),
            "named_as": hit.get("named_as"), "resolved": hit.get("resolved"),
            "value": value, "label": label,
            "tokens": sorted(tokens), "token_count": len(tokens),
            "w1_colocated_item_line": item_line,
            "w2_subject_named": subject, "w3_value_named": named_value,
            "colocated_single_line": line_hit,
        })

    labelled = sum(row["label"] in (LABEL_GENUINE, LABEL_ARTEFACT,
                                    LABEL_UNDECIDED) for row in rows)
    if not labelled:
        return {"status": PRECISION_UNMEASURED, "rule": PRECISION_RULE,
                "reason": ("ни одно срабатывание не размечено: абзацы "
                           "населения не разрешаются по координате"),
                "unresolved": unresolved}
    for tally in sides.values():
        total = (tally[LABEL_GENUINE] + tally[LABEL_ARTEFACT]
                 + tally[LABEL_UNDECIDED])
        tally["labelled"] = total
        tally["false_share"] = tally[LABEL_ARTEFACT] / total if total else None
        # Цена выбора области: сколько срабатываний держится ТОЛЬКО на том,
        # что пункт шире физической строки. Число печатается всегда — иначе
        # выбор области остался бы вкусом автора, а не измеренным решением.
        tally["wrap_cost"] = tally["colocated_item"] - tally["colocated_line"]
    # Обогащение читается ДВАЖДЫ, и знаменатели названы оба. На абзац —
    # держится ли сигнал за стороной объявления; на срабатывание — отделяет
    # ли стороны сама РАЗМЕТКА. Одно число с двумя знаменателями есть
    # ровно тот дефект, который перепись ищет у чужого кода (ADR-418), и
    # выбрать один знаменатель молча значило бы его здесь и совершить.
    authority = sides.get("authority") or {}
    control = sides.get("control") or {}
    per_paragraph, per_paragraph_why = _rate_enrichment(
        authority.get(LABEL_GENUINE, 0), int(channel.get("authority_paragraphs") or 0),
        control.get(LABEL_GENUINE, 0), int(channel.get("control_paragraphs") or 0))
    per_hit, per_hit_why = _rate_enrichment(
        authority.get(LABEL_GENUINE, 0), authority.get("labelled", 0),
        control.get(LABEL_GENUINE, 0), control.get("labelled", 0))
    interval = truth_interval(authority.get(LABEL_GENUINE, 0),
                              authority.get(LABEL_UNDECIDED, 0),
                              authority.get("labelled", 0))
    return {
        "status": "MEASURED",
        "enrichment": {
            "per_paragraph": per_paragraph, "per_paragraph_reason": per_paragraph_why,
            "per_hit": per_hit, "per_hit_reason": per_hit_why,
        },
        "truth_interval": interval,
        "rule": PRECISION_RULE,
        "question": ("какова доля ложных у двуязычного канала имени на ВСЁМ "
                     "объявленном населении (заказ G61 п. 1)"),
        "raw_hits": len(hits),
        "labelled": labelled,
        "unresolved": unresolved,
        "sides": sides,
        "rows": rows,
        "blind": [
            "`ARTEFACT` доказывает свойство УЛИКИ, а не текста: срабатывание не "
            "переживает сужения области до пункта. Что абзац не имеет к имени "
            "отношения, отсюда не следует — следует, что канал назвал его "
            "шириной абзаца, и точность канала есть именно это",
            "`GENUINE` тождества смысла НЕ доказывает: равная величина называет "
            "несколько порогов (ADR-418), а названный в том же абзаце модуль не "
            "есть доказательство, что абзац про ЭТУ его константу. GENUINE — "
            "верхняя граница истины, ARTEFACT — нижняя граница лжи",
            "`UNDECIDED` не сложен ни с той, ни с другой стороной намеренно: "
            "доля ложных со знаменателем `labelled` и этот остаток печатаются "
            "рядом, иначе третий исход растворился бы в одном из двух",
            "доля `GENUINE` на КОНТРОЛЕ есть частота ошибки самого правила "
            "разметки, а не находка о дереве",
        ],
    }


#: Правило меры заказа **G62 п. 1**, записанное ДО замера и не менявшееся
#: после него. Свободных параметров, подогнанных по увиденному исходу, у него
#: нет: глубина приходит аргументом, обе валюты цены названы заранее.
DEPTH_RULE = (
    "кандидат заказа — «имя обязано нести не меньше N различающих токенов» — "
    "прочитан ДВУМЯ способами, потому что это два разных вопроса: как СУЖЕНИЕ "
    "свидетеля W1 (срабатывание с меньшим числом токенов не происходит вовсе, "
    "население УБЫВАЕТ) и как ТРЕТИЙ СВИДЕТЕЛЬ W4 (число токенов само есть "
    "улика: GENUINE = W1 и (W2 или W3 или W4), население на месте, убывает "
    "`UNDECIDED`). Цена называется в ДВУХ валютах: срабатывания разметки и "
    "пары, подтверждённые величиной, — вторые и есть то, что канал доносит до "
    "книг. Порог НЕ вводится: мера судит уже сделанный замер и не меняет ни "
    "одного вердикта переписи"
)

TOKEN_DEPTH_UNMEASURED = "TOKEN_DEPTH_UNMEASURED"
#: Вердикт независимости кандидата: читает он ТОЛЬКО имя или ещё и текст.
DEPTH_NAME_ONLY = "VERDICT_FROM_NAME_ALONE"
DEPTH_READS_TEXT = "VERDICT_VARIES_WITH_TEXT"
DEPTH_INDEPENDENCE_UNMEASURED = "INDEPENDENCE_UNMEASURED"


def independence_verdict(groups: Dict[str, List[dict]], verdict_of) -> dict:
    """Меняется ли вердикт кандидата вместе с АБЗАЦЕМ при том же имени.

    Спрашивают это ДВЕ координаты — цена глубины токенов (**G62 п. 1**) и цена
    свидетелей абзаца (**G63 п. 1**), — и меняется у них лишь то, ЧЕМ судит
    кандидат; сама проверка одна. Вторая её копия была бы ровно тем предметом,
    который перепись ищет у чужого кода (ADR-417).

    Вырождение отдельным значением (инв. #17): ни одно имя не встретилось в
    двух разных абзацах ⇒ ``INDEPENDENCE_UNMEASURED``, а НЕ «независимости
    нет». Зелёный ответ на не заданный вопрос и есть предмет всей переписи.
    """
    multi = {name: rs for name, rs in groups.items()
             if len({(r.get("text"), r.get("block_start")) for r in rs}) > 1}
    if not multi:
        return {
            "verdict": DEPTH_INDEPENDENCE_UNMEASURED,
            "names_in_two_paragraphs": 0,
            "reason": ("проверка ВЫРОЖДЕНА: ни одно имя не встретилось в двух "
                       "разных абзацах, поэтому спросить «меняется ли вердикт "
                       "кандидата вместе с текстом» не на чем; зелёным этот "
                       "ответ быть не вправе"),
        }
    varying = sorted(name for name, rs in multi.items()
                     if len({verdict_of(row) for row in rs}) > 1)
    return {
        "verdict": DEPTH_READS_TEXT if varying else DEPTH_NAME_ONLY,
        "names_in_two_paragraphs": len(multi),
        "names_whose_verdict_varies": len(varying),
        "examples": sorted(multi)[:5],
        "varying_examples": varying[:5],
        "reason": ("вердикт кандидата у каждого из "
                   f"{len(multi)} имён, встреченных в двух и более разных "
                   "абзацах, один и тот же: кандидат читает ИМЯ и не "
                   "читает абзац, поэтому третьим свидетелем — независимым "
                   "и от токенов, и от величины — он не является"
                   if not varying else
                   "у части имён вердикт кандидата меняется вместе с "
                   "абзацем — кандидат читает не только имя"),
    }


def _depth_tally() -> dict:
    return {LABEL_GENUINE: 0, LABEL_ARTEFACT: 0, LABEL_UNDECIDED: 0}


def _depth_side(tally: dict) -> dict:
    """Сводка одной стороны: размечено, доля ложных, интервал истины."""
    labelled = (tally[LABEL_GENUINE] + tally[LABEL_ARTEFACT]
                + tally[LABEL_UNDECIDED])
    return {
        **tally,
        "labelled": labelled,
        "false_share": (tally[LABEL_ARTEFACT] / labelled) if labelled else None,
        "interval": truth_interval(tally[LABEL_GENUINE],
                                   tally[LABEL_UNDECIDED], labelled),
    }


def token_depth_price(precision: Optional[dict],
                      channel: Optional[dict] = None,
                      *, depth: int = 2) -> dict:
    """Цена требования N различающих токенов (**заказ G62 п. 1**).

    Заказ назвал кандидата замером: у 48 из 50 неразрешённых имя несёт ровно
    ОДИН различающий токен, то есть канал спрашивает у текста одно слово. И
    заказ же запретил вводить порог, пока цена не названа числом, — иначе
    порог стал бы вторым правилом, выбранным после того, как его исход увиден.
    Поэтому здесь считается ЦЕНА и только она: ни один вердикт переписи эта
    координата не меняет и ни в один гейт не входит (``applied`` — часть
    ответа, а не украшение).

    Вопрос заказа был «существует ли третий свидетель, независимый И от
    токенов, И от величины», и ответ про кандидата мера даёт САМА, а не прозой:
    вердикт, зависящий только от ИМЕНИ, не может развести два абзаца, которые
    этим именем называют один порог, — и такие абзацы в дереве есть. Проверка
    вырождена, если ни одно имя не встретилось дважды, и тогда она обязана
    сказать ``UNMEASURED``, а не «независимости нет».

    Третий исход везде отдельным значением (инв. #17): разметка не измерена,
    население пусто, число токенов у срабатывания не записано, пар нет,
    требование не строже действующего — каждое со своей причиной. Пустое
    население НЕ есть «цена нулевая».
    """
    head = {
        "rule": DEPTH_RULE,
        "depth": depth,
        "applied": False,
        "question": ("какова ЦЕНА требования N различающих токенов и является "
                     "ли кандидат третьим свидетелем (заказ G62 п. 1)"),
    }
    # Отдельной ветки «глубина — `bool`» здесь НЕТ, и это замер, а не
    # недосмотр: `bool` есть подкласс `int`, оба его значения равны 0 и 1,
    # и порог ниже двух отказывает им обоим. Батарея мутаций #659
    # оставила такую ветку в живых — это её приговор, а не оправдание.
    if not isinstance(depth, int) or depth < 2:
        return {**head, "status": TOKEN_DEPTH_UNMEASURED,
                "reason": ("требование не строже действующего: у каждого "
                           "срабатывания канала различающий токен есть хотя бы "
                           "один по построению, поэтому ноль здесь был бы "
                           "ответом не на тот вопрос")}
    # Четыре отсутствия РАЗВЕДЕНЫ, и это не педантизм: «координаты не было»
    # и «координата отказала» чинятся в разных местах, а «население не
    # записано» и «население пусто» — разные утверждения о канале. Слить их
    # значило бы отдать читателю одно «не измерено» вместо четырёх причин;
    # сосед (ADR-439) эту же развилку уже держит у `raw_hits`.
    if not isinstance(precision, dict):
        return {**head, "status": TOKEN_DEPTH_UNMEASURED,
                "reason": ("разметки канала имени нет вовсе — перепись собрана "
                           "без соседней координаты, цену считать не от чего")}
    if precision.get("status") != "MEASURED":
        return {**head, "status": TOKEN_DEPTH_UNMEASURED,
                "reason": ("точность канала имени ОТКАЗАЛА "
                           f"({precision.get('status')}) — цену сужения "
                           "считать не от чего")}
    rows = precision.get("rows")
    if rows is None:
        return {**head, "status": TOKEN_DEPTH_UNMEASURED,
                "reason": ("разметка не выдала населения: срабатывания "
                           "размечены и не записаны — считать цену нечем")}
    if not isinstance(rows, list):
        return {**head, "status": TOKEN_DEPTH_UNMEASURED,
                "reason": (f"население разметки имеет форму "
                           f"{type(rows).__name__}, а не перечень — прочитать "
                           "его построчно нельзя")}
    if not rows:
        return {**head, "status": TOKEN_DEPTH_UNMEASURED,
                "reason": ("население разметки пусто: это НЕ «цена нулевая», а "
                           "отсутствие предмета измерения")}

    before: Dict[str, dict] = {}
    kept: Dict[str, dict] = {}
    dropped: Dict[str, dict] = {}
    witness: Dict[str, dict] = {}
    resolved: Dict[str, int] = {}
    lost_rows: List[dict] = []
    moved_rows: List[dict] = []
    unreadable: List[dict] = []
    groups: Dict[str, List[dict]] = {}
    for row in rows:
        label = row.get("label")
        count = row.get("token_count")
        side = str(row.get("side") or "")
        if label not in (LABEL_GENUINE, LABEL_ARTEFACT, LABEL_UNDECIDED):
            unreadable.append({
                "text": row.get("text"), "named_as": row.get("named_as"),
                "reason": f"метка {label!r} не из объявленных трёх"})
            continue
        if isinstance(count, bool) or not isinstance(count, int):
            unreadable.append({
                "text": row.get("text"), "named_as": row.get("named_as"),
                "reason": ("у срабатывания не записано число различающих "
                           "токенов — глубину спросить не у чего")})
            continue
        groups.setdefault(str(row.get("named_as")), []).append(row)
        before.setdefault(side, _depth_tally())[label] += 1
        survives = count >= depth
        (kept if survives else dropped).setdefault(side, _depth_tally())[label] += 1
        if not survives:
            lost_rows.append({
                "side": side, "text": row.get("text"),
                "block_start": row.get("block_start"),
                "named_as": row.get("named_as"),
                "resolved": row.get("resolved"), "value": row.get("value"),
                "label": label, "token_count": count,
                "tokens": row.get("tokens"),
            })
        new_label = (LABEL_GENUINE
                     if label == LABEL_UNDECIDED and survives else label)
        witness.setdefault(side, _depth_tally())[new_label] += 1
        if new_label != label:
            resolved[side] = resolved.get(side, 0) + 1
            moved_rows.append({
                "side": side, "text": row.get("text"),
                "block_start": row.get("block_start"),
                "named_as": row.get("named_as"),
                "resolved": row.get("resolved"), "value": row.get("value"),
                "from": label, "to": new_label, "token_count": count,
            })

    if not before:
        return {**head, "status": TOKEN_DEPTH_UNMEASURED,
                "reason": ("ни одно срабатывание не разобрано: ни у одного нет "
                           "метки и числа токенов сразу"),
                "unreadable": unreadable}

    sides: Dict[str, dict] = {}
    for side, tally in before.items():
        sides[side] = {
            "before": _depth_side(tally),
            "as_filter": {
                "survive": _depth_side(kept.get(side, _depth_tally())),
                "lost": dict(dropped.get(side, _depth_tally())),
                # Сужение НИ ОДНОГО `UNDECIDED` не решает — оно их удаляет.
                # Число печатается всегда: им и отличается свидетель от фильтра.
                "resolved_undecided": 0,
            },
            "as_witness": {
                **_depth_side(witness.get(side, _depth_tally())),
                "resolved_undecided": resolved.get(side, 0),
            },
        }

    independence = independence_verdict(
        groups, lambda row: row.get("token_count"))

    pairs = channel.get("pairs") if isinstance(channel, dict) else None
    if not isinstance(pairs, list) or not pairs:
        price_in_pairs = {
            "status": TOKEN_DEPTH_UNMEASURED,
            "reason": ("канал не выдал пар, подтверждённых величиной, — цену в "
                       "валюте книг считать не на чем"),
        }
    else:
        # Глубина у пары спрашивается у РАЗМЕТКИ, а не считается заново: вторая
        # копия правила токенов здесь была бы ровно тем, что перепись ищет.
        index: Dict[Tuple, set] = {}
        for row in rows:
            count = row.get("token_count")
            if isinstance(count, bool) or not isinstance(count, int):
                continue
            key = (row.get("text"), row.get("named_as"), row.get("resolved"))
            index.setdefault(key, set()).add(count)
        pair_kept: List[dict] = []
        pair_lost: List[dict] = []
        pair_unmatched: List[dict] = []
        for pair in pairs:
            key = (pair.get("text"), pair.get("named_as"), pair.get("resolved"))
            counts = index.get(key)
            item = {"text": pair.get("text"), "named_as": pair.get("named_as"),
                    "resolved": pair.get("resolved"), "value": pair.get("value")}
            if not counts:
                pair_unmatched.append({
                    **item,
                    "reason": ("пары нет в населении разметки — число её "
                               "различающих токенов не записано никем")})
                continue
            if len(counts) > 1:
                pair_unmatched.append({
                    **item, "token_counts": sorted(counts),
                    "reason": ("у пары в разметке два разных числа токенов — "
                               "вердикт кандидата неоднозначен")})
                continue
            count = next(iter(counts))
            (pair_kept if count >= depth else pair_lost).append(
                {**item, "token_count": count})
        price_in_pairs = {
            "status": "MEASURED",
            "corroborated": len(pairs),
            "kept": pair_kept,
            "lost": pair_lost,
            "unmatched": pair_unmatched,
        }

    return {
        **head,
        "status": "MEASURED",
        "sides": sides,
        "independence": independence,
        "price_in_pairs": price_in_pairs,
        "lost_rows": lost_rows,
        "moved_rows": moved_rows,
        "unreadable": unreadable,
        "blind": [
            "цена названа, порог НЕ введён: `applied` ложно, и ни один вердикт "
            "переписи этой координатой не меняется — иначе порог оказался бы "
            "выбран после того, как его исход увиден (прямой запрет заказа)",
            "сужение делает интервал УЖЕ, и это ловушка, а не улучшение: узость "
            "берётся из убыли знаменателя, а не из решённых `UNDECIDED`, "
            "которых сужение не решает ни одного",
            "`as_witness` — не предложение ввести W4: число токенов есть "
            "свойство ИМЕНИ, а не независимая улика, и мера показывает лишь, "
            "сколько `UNDECIDED` кандидат тронул бы в этом прочтении",
            "потеря пары НЕ означает, что пара настоящая: `GENUINE` остаётся "
            "верхней границей истины (ADR-439). Цена считается в том, что "
            "канал доносит до книг, а не в доказанных копиях",
        ],
    }


#: Правило заказа **G63 п. 1**, записанное ДО разметки кандидатов и не
#: менявшееся после первого прогона. Свободных параметров, подогнанных по
#: увиденному исходу, у него нет: кандидаты, население и обе меры названы
#: заранее, а порога на саму частоту ошибки правило не вводит вовсе.
WITNESS_RULE = (
    "третий свидетель обязан читать АБЗАЦ и не читать ИМЯ (ADR-440): кандидат, "
    "чей вердикт есть функция одного имени, не способен развести два абзаца, "
    "называющие этим именем разные пороги. Кандидаты объявлены ДО разметки, и "
    "у КАЖДОГО меряются два числа: сколько `UNDECIDED` стороны объявлений он "
    "решает и какова его частота ошибки на КОНТРОЛЕ — абзац без языка права "
    "изменения объявлением не является, поэтому срабатывание там ложно по "
    "построению. Население вопроса — срабатывания, пережившие W1 (`GENUINE` и "
    "`UNDECIDED`): у `ARTEFACT` свидетеля не спрашивают, его снял уже W1. "
    "Действующие свидетели W2 и W3 размечаются ТЕМ ЖЕ мерилом и по той же "
    "причине: частоты ошибки у них не мерил никто. Кандидат без ИЗМЕРЕННОЙ "
    "частоты ошибки в правило не входит; порога на саму частоту правило НЕ "
    "вводит — он был бы выбран после того, как его исход увиден (запрет G62)"
)

PARAGRAPH_WITNESS_UNMEASURED = "PARAGRAPH_WITNESS_UNMEASURED"

WITNESS_ADR = "adr_cited"
WITNESS_DIR = "executor_dir_named"
WITNESS_UNIT = "unit_named"
WITNESS_SUBJECT = "w2_subject_named"
WITNESS_VALUE = "w3_value_named"

#: Ссылка на решение: `ADR-053`, `ADR-YL-011`, `ADR-OWN-2026-07-autoship`.
_ADR_CITED_RE = re.compile(
    r"(?<![a-z0-9_])adr[-\s]?(?:[a-z0-9]{1,4}-)*\d{2,4}(?![0-9])")

#: Единицы величины, объявленные ДО замера — ФРАГМЕНТАМИ поиска, а не словами.
#: Русская единица склоняется («5 дней», «5 дня»), а латинская обязана
#: кончаться границей слова, иначе `m` совпало бы внутри `more`. Порядок
#: существен: длинная единица стои́т раньше своей же приставки.
_UNIT_SUFFIX_PARTS = (
    r"bps", r"usd", r"hours?", r"days?", r"млрд", r"млн", r"мин[а-яё]*",
    r"сек[а-яё]*", r"дн[а-яё]*", r"%", r"ч(?![a-zа-яё])", r"с(?![a-zа-яё])",
    r"h(?![a-zа-яё])", r"m(?![a-zа-яё])", r"k(?![a-zа-яё])",
)
_UNIT_PREFIX_PARTS = (r"\$", r"€")
_UNIT_SUFFIX_RE = re.compile(r"\d\s?(?:" + "|".join(_UNIT_SUFFIX_PARTS) + r")")
_UNIT_PREFIX_RE = re.compile(r"(?:" + "|".join(_UNIT_PREFIX_PARTS) + r")\s?\d")


def _witness_adr_cited(raw_low: str, row: dict
                       ) -> Tuple[Optional[bool], Optional[str]]:
    """Называет ли абзац решение, которым порог и объявляется."""
    return bool(_ADR_CITED_RE.search(raw_low)), None


def _witness_executor_dir(raw_low: str, row: dict
                          ) -> Tuple[Optional[bool], Optional[str]]:
    """Называет ли абзац КАТАЛОГ исполнителя — не основу файла (это W2).

    Два отсутствия разведены: исполнителя не записали вовсе и у исполнителя
    нет каталога — это разные состояния и чинятся они в разных местах.
    """
    where = str(row.get("resolved") or "")
    if not where:
        return None, ("исполнитель у срабатывания не записан — каталог "
                      "спросить не у чего")
    parts = [part for part in where.split("/")[:-1] if part]
    if not parts:
        return None, (f"у исполнителя `{where}` нет каталога: путь состоит из "
                      f"одного имени файла, и вопрос к нему неприменим")
    for part in parts:
        if re.search(r"(?<![a-z0-9_])" + re.escape(part.lower())
                     + r"(?![a-z0-9_])", raw_low):
            return True, None
    return False, None


def _witness_unit(raw_low: str, row: dict
                  ) -> Tuple[Optional[bool], Optional[str]]:
    """Несёт ли абзац величину С ЕДИНИЦЕЙ — не просто число."""
    return bool(_UNIT_SUFFIX_RE.search(raw_low)
                or _UNIT_PREFIX_RE.search(raw_low)), None


def _witness_subject(raw_low: str, row: dict
                     ) -> Tuple[Optional[bool], Optional[str]]:
    """Действующий W2: абзац называет разрешённый модуль по основе файла."""
    where = str(row.get("resolved") or "")
    if not where:
        return None, ("исполнитель у срабатывания не записан — основу файла "
                      "спросить не у чего")
    return _module_named(raw_low, where), None


def _witness_value(raw_low: str, row: dict
                   ) -> Tuple[Optional[bool], Optional[str]]:
    """Действующий W3: абзац несёт величину имени в любом из двух прочтений.

    Величина спрашивается у самого абзаца тем же помощником, каким её
    спрашивает разметка (:func:`_paragraph_values`), — вторая копия правила
    двух прочтений была бы ровно тем предметом, который перепись ищет.
    """
    value = row.get("value")
    if value is None:
        return None, ("у срабатывания не записана величина — назвать её "
                      "абзац не может ни назвать, ни не назвать")
    return value_key(str(value)) in _paragraph_values(raw_low), None


#: Кандидаты заказа **G63 п. 1**, объявленные ДО разметки. Первые три — из
#: самого заказа; последние два действуют в правиле уже сегодня и внесены
#: сюда потому, что заказ назвал их тем же именем: свидетель без измеренной
#: частоты ошибки. Поле ``reads`` — не украшение: оно и есть ответ на вопрос
#: «читает ли кандидат абзац», и вердикт независимости его проверяет.
PARAGRAPH_WITNESSES = (
    {"key": WITNESS_ADR, "incumbent": False, "reads": "абзац",
     "declared": "абзац называет решение (ADR), которым порог объявляется",
     "probe": _witness_adr_cited},
    {"key": WITNESS_DIR, "incumbent": False, "reads": "абзац + путь исполнителя",
     "declared": ("абзац называет КАТАЛОГ исполнителя, а не основу его файла "
                  "(основа — это уже действующий W2)"),
     "probe": _witness_executor_dir},
    {"key": WITNESS_UNIT, "incumbent": False, "reads": "абзац",
     "declared": "абзац несёт величину с ЕДИНИЦЕЙ, а не голое число",
     "probe": _witness_unit},
    {"key": WITNESS_SUBJECT, "incumbent": True, "reads": "абзац + путь исполнителя",
     "declared": "ДЕЙСТВУЮЩИЙ W2: абзац называет модуль по основе файла",
     "probe": _witness_subject},
    {"key": WITNESS_VALUE, "incumbent": True, "reads": "абзац + величина имени",
     "declared": "ДЕЙСТВУЮЩИЙ W3: абзац несёт величину имени",
     "probe": _witness_value},
)

#: Ноль решённых `UNDECIDED` у действующего свидетеля — свойство ОПРЕДЕЛЕНИЯ
#: разметки, а не замер: `UNDECIDED` и означает «W1 без W2 и W3».
_STRUCTURAL_ZERO = (
    "`UNDECIDED` по определению разметки есть W1 без W2 и W3, поэтому ноль "
    "решённых у действующего свидетеля — свойство ОПРЕДЕЛЕНИЯ, а не измерение; "
    "число печатается рядом с измеренными, чтобы «ноль по построению» и "
    "«измерено и равно нулю» нельзя было прочесть одинаково (инв. #17)"
)


def _independence_reading(verdict: str, reads: str, reach: dict) -> str:
    """Что вердикт независимости ПОЗВОЛЯЕТ заключить у ЭТОГО кандидата.

    ADR-440 прочитал «вердикт не меняется вместе с абзацем» как «кандидат
    читает ИМЯ», и для ТОГО кандидата вывод был верен: его вход — одно имя.
    В общем случае вывод неверен, и это не осторожность, а замер: действующий
    W2 получает на вход абзац, имени не видит вовсе и всё равно даёт тот же
    вердикт у всех повторов — потому что почти всегда МОЛЧИТ. Постоянный
    ответ и отсутствие различительной силы выглядят одинаково, и различает их
    охват, а не вердикт.
    """
    if verdict == DEPTH_READS_TEXT:
        return "вердикт меняется вместе с абзацем — кандидат различает абзацы"
    if verdict == DEPTH_INDEPENDENCE_UNMEASURED:
        return ("вырождено: повторов имени нет, и спрашивать различительную "
                "силу не на чем")
    fired = sum(int(cell.get("fired", 0)) for cell in reach.values())
    silent = sum(int(cell.get("silent", 0)) for cell in reach.values())
    if not fired or not silent:
        return (f"вердикт постоянен ПОТОМУ, что постоянен сам ответ "
                f"(сработал {fired} раз из {fired + silent}): это отсутствие "
                f"различительной силы, а НЕ чтение имени — на вход кандидат "
                f"получает {reads} и имени не видит")
    return (f"вердикт не меняется вместе с абзацем, хотя на вход кандидат "
            f"получает {reads}: на ЭТОМ населении различительной силы нет, и "
            f"вывести отсюда «читает имя» нельзя")


def _witness_rate(fired: int, askable: int, unaskable: int,
                  *, paragraphs: int, empty_reason: str) -> dict:
    """Доля со ЗНАМЕНАТЕЛЕМ; пустой знаменатель — третий исход, не ноль.

    Рядом с числом срабатываний идёт число РАЗНЫХ абзацев, в которых они
    случились, и это не украшение: ADR-436 уже показал, как свойство выборки
    выдаётся за свойство дерева, а ADR-440 — что весь прибыток второго
    прочтения пришёл из одного абзаца. «Решает 33» при одном абзаце и при
    двадцати — разные утверждения.
    """
    if not askable:
        return {"status": PARAGRAPH_WITNESS_UNMEASURED, "fired": fired,
                "askable": 0, "unaskable": unaskable, "share": None,
                "paragraphs": paragraphs, "reason": empty_reason}
    return {"status": "MEASURED", "fired": fired, "askable": askable,
            "unaskable": unaskable, "share": fired / askable,
            "paragraphs": paragraphs}


def paragraph_witness_price(root: Path, precision: Optional[dict]) -> dict:
    """Кандидаты в третьи свидетели, читающие АБЗАЦ (**заказ G63 п. 1**).

    ADR-440 доказал, что кандидат прежнего заказа — глубина имени в токенах —
    третьим свидетелем не является: его вердикт есть функция ИМЕНИ, и у всех
    23 имён, встреченных в двух и более разных абзацах, он один и тот же.
    Форма искомого свидетеля этим названа, сам свидетель — нет. Здесь
    объявляются кандидаты :data:`PARAGRAPH_WITNESSES` и у каждого меряются
    ровно два числа, которых заказ и потребовал: решённые `UNDECIDED` и
    частота ошибки на контроле.

    Действующие W2 и W3 размечаются тем же мерилом не для симметрии: заказ
    прямо назвал их кандидатами без измеренной частоты ошибки, и пока она не
    измерена, «правило ошибается в N %» есть утверждение, которое нечем
    поверить. Ноль решённых `UNDECIDED` у них — :data:`_STRUCTURAL_ZERO`, и
    несовпадение с этим ожиданием печатается как ПРОТИВОРЕЧИЕ, а не молчит.

    Порог на частоту ошибки НЕ вводится и ни один вердикт переписи эта
    координата не меняет (``applied`` — часть ответа, а не украшение).
    """
    head = {
        "rule": WITNESS_RULE,
        "applied": False,
        "question": ("сколько `UNDECIDED` решает каждый кандидат-свидетель "
                     "абзаца и какова его частота ошибки на контроле "
                     "(заказ G63 п. 1)"),
        "declared": [{"key": cand["key"], "incumbent": cand["incumbent"],
                      "reads": cand["reads"], "declared": cand["declared"]}
                     for cand in PARAGRAPH_WITNESSES],
    }
    # Пять отсутствий разведены отдельными значениями по той же причине, что
    # у соседней координаты: «координаты не было» и «координата отказала»
    # чинятся в разных местах, а «население не записано», «население не
    # перечень» и «население пусто» — три разных утверждения о канале.
    if not isinstance(precision, dict):
        return {**head, "status": PARAGRAPH_WITNESS_UNMEASURED,
                "reason": ("разметки канала имени нет вовсе — перепись собрана "
                           "без соседней координаты, спрашивать свидетелей "
                           "не у чего")}
    if precision.get("status") != "MEASURED":
        return {**head, "status": PARAGRAPH_WITNESS_UNMEASURED,
                "reason": ("точность канала имени ОТКАЗАЛА "
                           f"({precision.get('status')}) — населения "
                           "`UNDECIDED` не существует")}
    rows = precision.get("rows")
    if rows is None:
        return {**head, "status": PARAGRAPH_WITNESS_UNMEASURED,
                "reason": ("разметка не выдала населения: срабатывания "
                           "размечены и не записаны — спрашивать нечего")}
    if not isinstance(rows, list):
        return {**head, "status": PARAGRAPH_WITNESS_UNMEASURED,
                "reason": (f"население разметки имеет форму "
                           f"{type(rows).__name__}, а не перечень — прочитать "
                           "его построчно нельзя")}
    if not rows:
        return {**head, "status": PARAGRAPH_WITNESS_UNMEASURED,
                "reason": ("население разметки пусто: это НЕ «ошибок ноль», а "
                           "отсутствие предмета измерения")}

    cache: Dict[str, Dict[int, List[Tuple[int, str]]]] = {}
    unreadable: List[dict] = []
    unresolved: List[dict] = []
    # Счёт ведётся по сторонам и по кандидатам; `artefact` считается отдельно
    # и не молчит: у него свидетеля не спрашивают по правилу, а не по недосмотру.
    population: Dict[str, int] = {}
    artefact_skipped: Dict[str, int] = {}
    undecided_total = 0
    tally: Dict[str, Dict[str, Dict[str, int]]] = {
        cand["key"]: {} for cand in PARAGRAPH_WITNESSES}
    resolves: Dict[str, Dict[str, int]] = {
        cand["key"]: {"fired": 0, "askable": 0, "unaskable": 0}
        for cand in PARAGRAPH_WITNESSES}
    groups: Dict[str, Dict[str, List[dict]]] = {
        cand["key"]: {} for cand in PARAGRAPH_WITNESSES}
    why_unaskable: Dict[str, Dict[str, int]] = {
        cand["key"]: {} for cand in PARAGRAPH_WITNESSES}
    examples: Dict[str, List[dict]] = {cand["key"]: []
                                       for cand in PARAGRAPH_WITNESSES}
    # Абзацы, а не только срабатывания: «решает 33» при одном абзаце и при
    # двадцати — разные утверждения (ADR-436, ADR-440).
    fired_paragraphs: Dict[str, Dict[str, set]] = {
        cand["key"]: {"undecided": set(), "control": set()}
        for cand in PARAGRAPH_WITNESSES}
    undecided_paragraphs: set = set()
    control_paragraphs: set = set()
    contradictions: Dict[str, List[dict]] = {cand["key"]: []
                                             for cand in PARAGRAPH_WITNESSES}

    for row in rows:
        label = row.get("label")
        side = str(row.get("side") or "")
        if label not in (LABEL_GENUINE, LABEL_ARTEFACT, LABEL_UNDECIDED):
            unreadable.append({
                "text": row.get("text"), "named_as": row.get("named_as"),
                "reason": f"метка {label!r} не из объявленных трёх"})
            continue
        if label == LABEL_ARTEFACT:
            artefact_skipped[side] = artefact_skipped.get(side, 0) + 1
            continue
        rel = str(row.get("text") or "")
        block, why = paragraph_at(root, rel, row.get("block_start"), cache)
        if block is None:
            unresolved.append({"text": rel, "named_as": row.get("named_as"),
                               "reason": why})
            continue
        raw_low = "\n".join(line for _, line in block).lower()
        population[side] = population.get(side, 0) + 1
        undecided = (label == LABEL_UNDECIDED and side == "authority")
        undecided_total += 1 if undecided else 0
        where = (rel, row.get("block_start"))
        if undecided:
            undecided_paragraphs.add(where)
        if side == "control":
            control_paragraphs.add(where)
        for cand in PARAGRAPH_WITNESSES:
            key = cand["key"]
            verdict, reason = cand["probe"](raw_low, row)
            cell = tally[key].setdefault(
                side, {"fired": 0, "silent": 0, "unaskable": 0})
            if verdict is None:
                cell["unaskable"] += 1
                bucket = why_unaskable[key]
                bucket[str(reason)] = bucket.get(str(reason), 0) + 1
                if undecided:
                    resolves[key]["unaskable"] += 1
                continue
            cell["fired" if verdict else "silent"] += 1
            if verdict and side == "control":
                fired_paragraphs[key]["control"].add(where)
            groups[key].setdefault(str(row.get("named_as")), []).append(
                {"text": rel, "block_start": row.get("block_start"),
                 "verdict": verdict})
            if undecided:
                resolves[key]["askable"] += 1
                if verdict:
                    resolves[key]["fired"] += 1
                    fired_paragraphs[key]["undecided"].add(where)
                    item = {"text": rel, "block_start": row.get("block_start"),
                            "named_as": row.get("named_as"),
                            "resolved": row.get("resolved"),
                            "value": row.get("value")}
                    if len(examples[key]) < 5:
                        examples[key].append(item)
                    if cand["incumbent"]:
                        contradictions[key].append(item)

    if not population:
        return {**head, "status": PARAGRAPH_WITNESS_UNMEASURED,
                "reason": ("ни одно срабатывание не дошло до свидетелей: у "
                           "всех либо метка вне объявленных трёх, либо "
                           "`ARTEFACT`, либо абзац не разрешается"),
                "unreadable": unreadable, "unresolved": unresolved,
                "artefact_skipped": artefact_skipped}

    candidates: Dict[str, dict] = {}
    for cand in PARAGRAPH_WITNESSES:
        key = cand["key"]
        got = resolves[key]
        control = tally[key].get("control") or {"fired": 0, "silent": 0,
                                                "unaskable": 0}
        resolved_doc = _witness_rate(
            got["fired"], got["askable"], got["unaskable"],
            paragraphs=len(fired_paragraphs[key]["undecided"]),
            empty_reason=("неразрешённых срабатываний, у которых свидетеля "
                          "можно спросить, нет — «решает ноль» здесь было бы "
                          "ответом не на тот вопрос"))
        error_doc = _witness_rate(
            control["fired"], control["fired"] + control["silent"],
            control["unaskable"],
            paragraphs=len(fired_paragraphs[key]["control"]),
            empty_reason=("контрольных срабатываний, у которых свидетеля можно "
                          "спросить, нет: частоту ошибки сравнивать не с чем, "
                          "и это НЕ «ошибок ноль»"))
        admissible = error_doc["status"] == "MEASURED"
        reach = {side: dict(cell) for side, cell in tally[key].items()}
        independence = independence_verdict(
            groups[key], lambda row: row["verdict"])
        candidates[key] = {
            "declared": cand["declared"],
            "reads": cand["reads"],
            "incumbent": cand["incumbent"],
            "resolves_undecided": resolved_doc,
            "error_rate_on_control": error_doc,
            "reach": reach,
            "admissible_to_rule": admissible,
            "admissibility": (
                "частота ошибки ИЗМЕРЕНА — кандидат допустим к обсуждению "
                "правила; допустим не значит принят, порог на саму частоту "
                "этим решением не вводится"
                if admissible else
                "частота ошибки НЕ измерена — в правило кандидат не входит"),
            "structural_zero": _STRUCTURAL_ZERO if cand["incumbent"] else None,
            "contradictions": contradictions[key],
            "unaskable_reasons": dict(sorted(why_unaskable[key].items())),
            "examples": examples[key],
            "independence": independence,
            "independence_reading": _independence_reading(
                str(independence.get("verdict")), cand["reads"], reach),
        }

    return {
        **head,
        "status": "MEASURED",
        "undecided_population": undecided_total,
        "undecided_paragraphs": len(undecided_paragraphs),
        "control_population": population.get("control", 0),
        "control_paragraphs": len(control_paragraphs),
        "population": population,
        "artefact_skipped": artefact_skipped,
        "candidates": candidates,
        "unreadable": unreadable,
        "unresolved": unresolved,
        "blind": [
            "частота ошибки на контроле есть частота ошибки КАНДИДАТА в том "
            "же смысле, в каком доля `GENUINE` на контроле есть частота ошибки "
            "правила разметки (ADR-439): абзац без языка права изменения "
            "объявлением не является, поэтому срабатывание там ложно по "
            "построению — а не потому, что кто-то его проверил",
            "решённый `UNDECIDED` НЕ означает доказанной копии: `GENUINE` "
            "остаётся ВЕРХНЕЙ границей истины (ADR-439), и свидетель двигает "
            "именно её",
            "порог на частоту ошибки НЕ введён: `applied` ложно, ни один "
            "вердикт переписи этой координатой не меняется. Ввести его, увидев "
            "исход, значило бы выбрать правило после его результата — прямой "
            "запрет заказа G62",
            "вердикт независимости отвечает на «меняется ли ответ вместе с "
            "абзацем», а НЕ на «верен ли ответ»: кандидат, читающий абзац и "
            "читающий его неверно, останется здесь `VERDICT_VARIES_WITH_TEXT`",
        ],
    }



#: Правило заказа **G64 п. 1**, записанное ДО замера и не менявшееся после
#: первого прогона. Свободных параметров, подогнанных по увиденному исходу, у
#: него нет: валюта, население и обе границы интервала названы заранее, а
#: порога на частоту ошибки правило не вводит вовсе.
ADMISSION_RULE = (
    "цена ДОПУСКА кандидата в правило считается в валюте КНИГ — в парах, а не "
    "в срабатываниях разметки (ADR-440: срабатывание книг не достигает, пара "
    "достигает). Допуск читается как ТРЕТИЙ СВИДЕТЕЛЬ: "
    "GENUINE = W1 и (W2 или W3 или Wк), население на месте, убывает "
    "`UNDECIDED`. У цены ДВЕ стороны, и складывать их нельзя: на стороне "
    "объявлений прибывшая пара может оказаться настоящей, на КОНТРОЛЕ она "
    "ложна ПО ПОСТРОЕНИЮ — абзац без языка права изменения объявлением не "
    "является. Интервал истины двигается ОБЕИМИ границами или ни одной, и "
    "какая из них тронулась — замер, а не ожидание. Порог НЕ вводится: мера "
    "судит уже сделанный замер и не меняет ни одного вердикта переписи"
)

WITNESS_ADMISSION_UNMEASURED = "WITNESS_ADMISSION_UNMEASURED"

#: Почему верхняя граница интервала не может тронуться от ДОПУСКА свидетеля.
#: Утверждение печатается рядом с ЗАМЕРОМ обеих границ, а не вместо него:
#: заказ потребовал обе, и «по построению не двигается» без числа было бы
#: ровно тем зелёным ответом на не заданный вопрос, который ищет вся перепись.
_ADMISSION_UPPER_INVARIANT = (
    "верхняя граница есть (GENUINE + UNDECIDED) / labelled, а допуск свидетеля "
    "переносит срабатывание ИЗ `UNDECIDED` В `GENUINE`, не трогая знаменателя: "
    "сумма в числителе сохраняется, и верхняя граница обязана остаться на "
    "месте. Это свойство ОПРЕДЕЛЕНИЯ, а не измерение, — но замер печатается "
    "рядом, и расхождение с ожиданием объявляется ПРОТИВОРЕЧИЕМ, а не молчит"
)

#: Ноль прибывших пар у ДЕЙСТВУЮЩЕГО свидетеля — свойство определения
#: разметки (`UNDECIDED` и означает «W1 без W2 и W3»), а не замер цены.
_ADMISSION_STRUCTURAL_ZERO = (
    "у ДЕЙСТВУЮЩЕГО свидетеля прибыток пар равен нулю ПО ОПРЕДЕЛЕНИЮ разметки: "
    "`UNDECIDED` есть W1 без W2 и W3, поэтому допускать в правило уже стоящего "
    "в нём нечего. Число печатается рядом с измеренными, чтобы «ноль по "
    "построению» и «измерено и равно нулю» нельзя было прочесть одинаково "
    "(инв. #17)"
)


def _pair_key(item: dict, *, line_field: str) -> Tuple:
    """Координата пары: текст, начало абзаца, имя, исполнитель.

    Поле начала абзаца у пары канала зовётся ``line``, у строки разметки —
    ``block_start``, и это ОДНО и то же число (``block[0][0]``). Разные имена
    сводятся здесь один раз: вторая копия этого знания была бы ровно тем
    предметом, который перепись ищет у чужого кода (ADR-417).
    """
    return (item.get("text"), item.get(line_field), item.get("named_as"),
            item.get("resolved"))


def _admission_side(genuine: int, undecided: int, artefact: int,
                    added: int) -> dict:
    """Одна сторона цены: до, после и ОБЕ границы интервала у каждой."""
    labelled = genuine + undecided + artefact
    before = truth_interval(genuine, undecided, labelled)
    after = truth_interval(genuine + added, undecided - added, labelled)
    moved_lower = (before is not None and after is not None
                   and before["lower"] != after["lower"])
    moved_upper = (before is not None and after is not None
                   and before["upper"] != after["upper"])
    return {
        "genuine_before": genuine,
        "genuine_after": genuine + added,
        "undecided_before": undecided,
        "undecided_after": undecided - added,
        "artefact": artefact,
        "labelled": labelled,
        "added": added,
        "interval_before": before,
        "interval_after": after,
        "lower_bound_moved": moved_lower,
        "upper_bound_moved": moved_upper,
        "upper_bound_note": _ADMISSION_UPPER_INVARIANT,
    }


def witness_admission_price(root: Path, precision: Optional[dict],
                            channel: Optional[dict] = None) -> dict:
    """Цена ДОПУСКА кандидата-свидетеля в правило, в валюте пар (**G64 п. 1**).

    ADR-441 измерил у кандидата ``adr_cited`` два числа — решённые `UNDECIDED`
    и частоту ошибки на контроле — и прямо сказал, чего НЕ доказал: что
    кандидата стои́т ввести. Цена введения в валюте книг не измерена вовсе, и
    заказ **G64 п. 1** требует именно её: сколько ПАР прибавляет правило
    ``GENUINE = W1 и (W2 или W3 или Wк)``, сколько из них приходит из абзацев,
    уже давших пару, и как двигается интервал истины — ОБЕ границы.

    Вопрос про «уже давший пару абзац» не украшение, а мера ПРИБЫТКА: пара из
    абзаца, о котором книги уже говорят, доносит до читателя меньше, чем пара
    из абзаца, молчавшего до сих пор. ADR-440 нашёл ровно эту форму — весь
    прибыток второго прочтения пришёл из ОДНОГО абзаца.

    Мера ничего не пересчитывает заново: вердикты кандидатов спрашиваются у
    тех же проб :data:`PARAGRAPH_WITNESSES`, интервал — у той же
    :func:`truth_interval`, абзац — у той же :func:`paragraph_at`. Вызвать
    объявленное один раз правило дважды не значит завести его вторую копию.

    Третий исход везде отдельным значением (инв. #17): разметки нет, разметка
    отказала, население не записано / не перечень / пусто — каждое со своей
    причиной; пары канала недоступны ⇒ подвопрос про абзацы отвечает
    ``UNMEASURED``, а прибыток пар при этом остаётся измеренным. Пустое
    население НЕ есть «цена нулевая».
    """
    head = {
        "rule": ADMISSION_RULE,
        "applied": False,
        "question": ("какова ЦЕНА допуска кандидата в правило в валюте ПАР и "
                     "как двигаются ОБЕ границы интервала истины "
                     "(заказ G64 п. 1)"),
        "declared": [{"key": cand["key"], "incumbent": cand["incumbent"],
                      "reads": cand["reads"]}
                     for cand in PARAGRAPH_WITNESSES],
    }
    if not isinstance(precision, dict):
        return {**head, "status": WITNESS_ADMISSION_UNMEASURED,
                "reason": ("разметки канала имени нет вовсе — перепись собрана "
                           "без соседней координаты, цену допуска считать не "
                           "от чего")}
    if precision.get("status") != "MEASURED":
        return {**head, "status": WITNESS_ADMISSION_UNMEASURED,
                "reason": ("точность канала имени ОТКАЗАЛА "
                           f"({precision.get('status')}) — населения "
                           "`UNDECIDED` не существует")}
    rows = precision.get("rows")
    if rows is None:
        return {**head, "status": WITNESS_ADMISSION_UNMEASURED,
                "reason": ("разметка не выдала населения: срабатывания "
                           "размечены и не записаны — цену считать нечем")}
    if not isinstance(rows, list):
        return {**head, "status": WITNESS_ADMISSION_UNMEASURED,
                "reason": (f"население разметки имеет форму "
                           f"{type(rows).__name__}, а не перечень — прочитать "
                           "его построчно нельзя")}
    if not rows:
        return {**head, "status": WITNESS_ADMISSION_UNMEASURED,
                "reason": ("население разметки пусто: это НЕ «цена нулевая», а "
                           "отсутствие предмета измерения")}

    # Пары канала — то, что доходит до книг СЕГОДНЯ. Их отсутствие закрывает
    # ровно один подвопрос заказа и не отменяет остальных, поэтому отказ здесь
    # локальный, а не общий на всю координату.
    pairs = channel.get("pairs") if isinstance(channel, dict) else None
    if not isinstance(pairs, list):
        paying: Optional[set] = None
        pairs_today: dict = {
            "status": WITNESS_ADMISSION_UNMEASURED,
            "reason": ("канал не выдал перечня пар — какие абзацы уже платят "
                       "книгам, спросить не у чего; это НЕ «не платит ни один»"),
        }
    else:
        paying = {(p.get("text"), p.get("line")) for p in pairs}
        pairs_today = {"status": "MEASURED", "pairs": len(pairs),
                       "paragraphs": len(paying)}

    cache: Dict[str, Dict[int, List[Tuple[int, str]]]] = {}
    unreadable: List[dict] = []
    unresolved: List[dict] = []
    counts: Dict[str, Dict[str, int]] = {}
    # Прибывшие строки собираются ЦЕЛИКОМ: без них «прибыло 33» осталось бы
    # числом без предметов, и ни абзац, ни пересечение с парами спросить было
    # бы не у чего.
    arrivals: Dict[str, Dict[str, List[dict]]] = {
        cand["key"]: {"authority": [], "control": []}
        for cand in PARAGRAPH_WITNESSES}
    unaskable: Dict[str, Dict[str, int]] = {
        cand["key"]: {"authority": 0, "control": 0}
        for cand in PARAGRAPH_WITNESSES}
    genuine_rows: Dict[str, set] = {"authority": set(), "control": set()}

    for row in rows:
        label = row.get("label")
        side = str(row.get("side") or "")
        if label not in (LABEL_GENUINE, LABEL_ARTEFACT, LABEL_UNDECIDED):
            unreadable.append({
                "text": row.get("text"), "named_as": row.get("named_as"),
                "reason": f"метка {label!r} не из объявленных трёх"})
            continue
        tally = counts.setdefault(side, {LABEL_GENUINE: 0, LABEL_ARTEFACT: 0,
                                         LABEL_UNDECIDED: 0})
        tally[label] += 1
        if label == LABEL_GENUINE and side in genuine_rows:
            genuine_rows[side].add(_pair_key(row, line_field="block_start"))
        if label != LABEL_UNDECIDED:
            continue
        rel = str(row.get("text") or "")
        block, why = paragraph_at(root, rel, row.get("block_start"), cache)
        if block is None:
            unresolved.append({"text": rel, "named_as": row.get("named_as"),
                               "reason": why})
            # Неразрешённый абзац остаётся в знаменателе разметки и НЕ
            # переходит ни к одному кандидату: спросить свидетеля не у чего.
            for cand in PARAGRAPH_WITNESSES:
                if side in unaskable[cand["key"]]:
                    unaskable[cand["key"]][side] += 1
            continue
        raw_low = "\n".join(line for _, line in block).lower()
        for cand in PARAGRAPH_WITNESSES:
            key = cand["key"]
            verdict, _reason = cand["probe"](raw_low, row)
            if verdict is None:
                if side in unaskable[key]:
                    unaskable[key][side] += 1
                continue
            if verdict and side in arrivals[key]:
                arrivals[key][side].append({
                    "text": rel, "block_start": row.get("block_start"),
                    "named_as": row.get("named_as"),
                    "resolved": row.get("resolved"), "value": row.get("value"),
                })

    if not counts:
        return {**head, "status": WITNESS_ADMISSION_UNMEASURED,
                "reason": ("ни одно срабатывание не разобрано: ни у одного нет "
                           "метки из объявленных трёх"),
                "unreadable": unreadable, "unresolved": unresolved}

    # Пересечение пар канала с меткой `GENUINE` — ЗАМЕР, а не допущение. Два
    # критерия («величина подтвердила» и «W1 и (W2 или W3)») сегодня дают
    # одно число, и совпадение чисел тождеством множеств не является.
    if paying is not None and isinstance(pairs, list):
        pair_keys = {_pair_key(p, line_field="line") for p in pairs}
        pairs_today["genuine_overlap"] = len(pair_keys & genuine_rows["authority"])
        pairs_today["pairs_not_genuine"] = sorted(
            str(k) for k in (pair_keys - genuine_rows["authority"]))
        pairs_today["genuine_not_pairs"] = sorted(
            str(k) for k in (genuine_rows["authority"] - pair_keys))

    candidates: Dict[str, dict] = {}
    for cand in PARAGRAPH_WITNESSES:
        key = cand["key"]
        per_side: Dict[str, dict] = {}
        for side, tally in sorted(counts.items()):
            # Сторона вне объявленных двух — ТРЕТИЙ ИСХОД, а не ноль: прибыток
            # у неё не считался вовсе, и выдать «прибыло 0» значило бы ответить
            # числом на не заданный вопрос (инв. #17).
            if side not in arrivals[key]:
                per_side[side] = {
                    "status": WITNESS_ADMISSION_UNMEASURED,
                    "labelled": sum(tally.values()),
                    "reason": (f"сторона {side!r} не из объявленных двух "
                               f"(`authority`, `control`) — свидетеля у неё не "
                               f"спрашивали, и прибыток не измерен"),
                }
                continue
            added = len(arrivals[key][side])
            per_side[side] = {
                "status": "MEASURED",
                **_admission_side(tally[LABEL_GENUINE], tally[LABEL_UNDECIDED],
                                  tally[LABEL_ARTEFACT], added),
                "unaskable": unaskable[key].get(side, 0),
            }
        got = arrivals[key]["authority"]
        if paying is None:
            provenance = {
                "status": WITNESS_ADMISSION_UNMEASURED,
                "added": len(got),
                "reason": ("перечня пар у канала нет — из каких абзацев "
                           "прибыли новые пары, сказать нечем; это НЕ «не "
                           "платит ни один»"),
            }
        else:
            already = [item for item in got
                       if (item["text"], item["block_start"]) in paying]
            fresh_paragraphs = {(item["text"], item["block_start"])
                                for item in got
                                if (item["text"], item["block_start"])
                                not in paying}
            provenance = {
                "status": "MEASURED",
                "added": len(got),
                "from_paragraph_already_paying": len(already),
                "from_paragraph_silent_until_now": len(got) - len(already),
                "paragraphs_added": len({(item["text"], item["block_start"])
                                         for item in got}),
                "paragraphs_new_to_books": len(fresh_paragraphs),
            }
        # Прибывшая пара, уже стоя́щая в парах канала, есть ПРОТИВОРЕЧИЕ:
        # `UNDECIDED` означает «без W3», а пара канала — «величина подтвердила»,
        # то есть ровно W3. Пересечение обязано быть пустым, и оно МЕРЯЕТСЯ.
        contradiction = ([] if paying is None else
                         [item for item in got
                          if _pair_key(item, line_field="block_start")
                          in {_pair_key(p, line_field="line") for p in pairs}])
        candidates[key] = {
            "incumbent": cand["incumbent"],
            "reads": cand["reads"],
            "admitted_rule": (f"GENUINE = W1 и (W2 или W3 или `{key}`)"),
            "sides": per_side,
            "pair_provenance": provenance,
            "structural_zero": (_ADMISSION_STRUCTURAL_ZERO
                                if cand["incumbent"] else None),
            # Ноль по построению — ОЖИДАНИЕ, и расхождение с ним обязано
            # кричать, а не тонуть рядом с запиской о том, что ноль неизбежен.
            # Сработавший на `UNDECIDED` действующий свидетель означает, что
            # разметка и эта мера спорят о ТОЙ ЖЕ строке.
            "contradicts_marking": (got if cand["incumbent"] else []),
            "already_a_pair": contradiction,
            "examples": got[:5],
        }

    return {
        **head,
        "status": "MEASURED",
        "pairs_today": pairs_today,
        "candidates": candidates,
        "unreadable": unreadable,
        "unresolved": unresolved,
        "blind": [
            "цена названа, порог НЕ введён: `applied` ложно, и ни один вердикт "
            "переписи этой координатой не меняется — ввести его, увидев исход, "
            "значило бы выбрать правило после его результата (запрет G62)",
            "прибывшая пара НЕ есть доказанная копия: `GENUINE` остаётся "
            "ВЕРХНЕЙ границей истины (ADR-439), и допуск свидетеля двигает "
            "именно её нижнюю сторону, а не саму истину",
            "две стороны цены НЕ складываются и не усредняются: знаменатели у "
            "них разные, а прибыток на КОНТРОЛЕ ложен по построению, тогда как "
            "на стороне объявлений он может быть и верным, и нет",
            "«абзац уже платит книгам» меряет ПРИБЫТОК читателю, а не истину: "
            "вторая пара из того же абзаца может быть настоящей и всё равно "
            "не сказать книгам ничего нового",
        ],
    }

#: --- КАКУЮ БАЗУ БЕРЁТ ЧИТАТЕЛЬ ПЕРЕПИСИ (заказ G65 п. 1) ------------------
#:
#: ADR-442 измерил расхождение у САМОЙ базы: пары, доходящие до книг, и строки
#: с меткой ``GENUINE`` — РАЗНЫЕ множества (4 и 4, пересечение 3). Он не
#: ответил, КТО из читателей переписи какую базу берёт, и заказ G65 п. 1
#: требует спросить поимённо: секция отчёта, мост находок, шаг 0-офис.
#:
#: Читатель, берущий одну базу и называющий её именем другой, и есть вторая
#: копия правила — только снаружи прибора, в словаре.

#: База — множество КООРДИНАТ документа, которые суть одно население. Токены
#: объявлены, СМЕЖНОСТЬ измерена: многозначность токена выводится из замера
#: (один токен встал рядом с двумя базами), а не из этой таблицы.
BASE_BOOKS_PAIRS = "books_pairs"
BASE_GENUINE = "genuine_label"
BASE_GUARD_EXECUTOR = "guard_executor_pairs"

CENSUS_BASES = (
    {"key": BASE_BOOKS_PAIRS,
     "what": "пары канала имени, дошедшие до книг (`channel.pairs`)",
     "coordinates": ("pairs",),
     "tokens": ("пар",)},
    {"key": BASE_GENUINE,
     "what": "строки разметки с меткой `GENUINE`",
     "coordinates": (LABEL_GENUINE,),
     "tokens": ("genuine", "настоящ")},
    {"key": BASE_GUARD_EXECUTOR,
     "what": "пары «сторож × исполнитель» — население самой переписи",
     "coordinates": (CLASS_TWO_COPIES, "findings_on_books"),
     "tokens": ("пар", "двух копи", "две копии", "учёте")},
)

#: Потребители, названные заказом ПОИМЁННО. Реестр литеральный: «кого
#: спрашивали» обязано быть видно, а не выведено обходом дерева, иначе
#: молчание о потребителе неотличимо от его отсутствия.
CONSUMER_REPORT = "report_section"
CONSUMER_BRIDGE = "findings_bridge"
CONSUMER_OFFICE = "office_step"

CENSUS_CONSUMERS = (
    {"key": CONSUMER_REPORT, "path": PRODUCER,
     "scope": ("report", "format_report"),
     "what": "секция отчёта — единственное место, где перепись становится текстом"},
    {"key": CONSUMER_BRIDGE, "path": "spa_core/monitoring/findings_bridge.py",
     "scope": None,
     "what": "мост находок — ступень, зовущая перепись и печатающая её число"},
    {"key": CONSUMER_OFFICE, "path": "scripts/consume_office_reports.py",
     "scope": None,
     "what": "шаг 0-офис — то, что доносит перепись до оркестратора"},
)

#: Предел вложенности тернарников при поиске координаты. Не украшение:
#: разбор идёт вглубь по `IfExp`, и достаточно глубокая запись сорвала бы
#: рекурсию `RecursionError` — то есть заменила бы третий исход падением.
_TERNARY_NESTING_LIMIT = 24

#: Имена, через которые читатель достаёт значение из документа переписи.
_DOC_READERS = ("observed", "observed_number")
#: Имена отрисовщиков производителя: делегирование опознаётся по ВВОЗУ одного
#: из них, а не по совпадению слов.
_PRODUCER_RENDERERS = ("report", "format_report")
#: Имя модуля-производителя без пути — так его зовёт мост.
_PRODUCER_MODULE_NAME = "rule_second_copy_census"

#: Откуда у читателя берётся документ переписи. ОБЪЯВЛЯЕТСЯ спецификацией:
#: вывести это из пути нельзя, потому что внутри одного файла-производителя
#: живут области с РАЗНЫМИ якорями (отрисовщик принимает документ первым
#: параметром, а `main` — аргументы командной строки).
ANCHOR_FIRST_PARAM = "first_param"
ANCHOR_PRODUCER_CALL = "producer_call"
ANCHOR_LOCAL_RUN = "local_run"

#: Имена, рождающие документ ВНУТРИ производителя (голым зовом, без точки).
_LOCAL_DOC_MAKERS = ("run", "measure")

#: Исходы потребителя. «Делегирует» — НЕ ноль: читатель без своей базы
#: доносит до глаз чужую, вместе со всею её многозначностью.
CONSUMER_READS = "READS"
CONSUMER_DELEGATES = "DELEGATES"
CONSUMER_NO_READ = "NO_READ"
CONSUMER_UNMEASURED = "UNMEASURED"

#: Исходы одного НАЗВАННОГО числа.
NAMING_SINGLE = "SINGLE"
NAMING_CROSS = "CROSS_NAMED"
NAMING_AMBIGUOUS = "AMBIGUOUS"
NAMING_UNNAMED = "UNNAMED"


def _module_string_consts(tree: ast.AST) -> Dict[str, str]:
    """Модульные имена со строковым КОНСТАНТНЫМ значением.

    Ключ координаты у читателя стои́т то литералом (``doc.get("counts")``), то
    именем (``counts.get(CLASS_TWO_COPIES)``). Считать вторую форму
    неразрешимой значило бы объявить слепым прибор ровно там, где читатель
    аккуратнее всего.
    """
    out: Dict[str, str] = {}
    for node in getattr(tree, "body", []):
        if not isinstance(node, ast.Assign):
            continue
        if not (isinstance(node.value, ast.Constant)
                and isinstance(node.value.value, str)):
            continue
        for target in node.targets:
            if isinstance(target, ast.Name):
                out[target.id] = node.value.value
    return out


def _literal_key(node: ast.AST, consts: Dict[str, str]) -> Optional[str]:
    """Строковый ключ подстрочника — литералом или через модульную константу."""
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        return node.value
    if isinstance(node, ast.Name) and node.id in consts:
        return consts[node.id]
    return None


def _terminal_coordinate(expr: ast.AST, consts: Dict[str, str],
                         binding: Dict[str, str],
                         depth: int = 0) -> Optional[str]:
    """Координата, которой значение ЯВЛЯЕТСЯ — ПОСЛЕДНЯЯ применённая.

    Не объединение всех ключей цепи, и это замер, а не педантизм: у
    ``row["name"]``, где ``row`` пробегает ``channel["pairs"]``, объединение
    дало бы координату ``pairs`` каждому полю каждой пары — то есть приписало
    бы базе книг все её элементы. Ровно эта форма («контейнер привязкой не
    является») уже стоила нам бомбы в `.claude/rules/deployment.md`.

    Обёртки, прозрачные для значения (``int``, ``len``, ``str``, ``or``,
    тернарник), проходятся насквозь: имя числа от них не меняется.
    """
    if depth > _TERNARY_NESTING_LIMIT:  # предел вложенности — третий исход, не срыв
        return None
    node = expr
    while True:
        if isinstance(node, ast.Call):
            func = node.func
            if (isinstance(func, ast.Attribute) and func.attr == "get"
                    and node.args):
                key = _literal_key(node.args[0], consts)
                if key is not None:
                    return key
                node = func.value
                continue
            if (isinstance(func, ast.Name) and func.id in _DOC_READERS
                    and len(node.args) >= 2):
                key = _literal_key(node.args[1], consts)
                if key is not None:
                    return key
            if node.args:
                node = node.args[0]
                continue
            return None
        if isinstance(node, ast.Subscript):
            key = _literal_key(node.slice, consts)
            if key is not None:
                return key
            node = node.value
            continue
        if isinstance(node, ast.BoolOp) and node.values:
            node = node.values[0]
            continue
        if isinstance(node, ast.IfExp):
            got = _terminal_coordinate(node.body, consts, binding, depth + 1)
            if got is not None:
                return got
            node = node.orelse
            continue
        if isinstance(node, ast.Name):
            return binding.get(node.id)
        return None


def _derives_from_census(node: ast.AST, anchors: set,
                        local_makers: frozenset = frozenset(),
                        producer_aliases: Optional[frozenset] = None) -> bool:
    """Происходит ли выражение из документа ЭТОЙ переписи.

    Без этого вопроса соседский ``pairs`` (у моста их читает другая перепись)
    попал бы в замер как наш — то есть прибор выдумал бы находку ровно того
    класса, который ищет.

    ``local_makers`` — имена, которые ВНУТРИ производителя рождают его же
    документ (``run``, ``measure``): там зов стои́т голым именем и формы
    ``rule_second_copy_census.run(...)`` не имеет ПО ПОСТРОЕНИЮ. Умолчание
    пусто, поэтому у всех прежних читателей правило то же, что и было.

    ``producer_aliases`` — под каким именем производитель виден У ЭТОГО
    читателя. Умолчание — его собственное имя модуля; но ввоз
    ``import … as census`` связывает документ с именем `census`, и правило,
    знающее только одно написание, объявило бы НЕ ЧИТАЮЩИМ читателя, который
    зовёт ``census.measure(root)`` прямо.
    """
    names = (frozenset({_PRODUCER_MODULE_NAME}) if producer_aliases is None
             else producer_aliases)
    for inner in ast.walk(node):
        if isinstance(inner, ast.Name) and inner.id in anchors:
            return True
        if isinstance(inner, ast.Call):
            func = inner.func
            if (isinstance(func, ast.Attribute)
                    and func.attr in ("run", "measure")
                    and isinstance(func.value, ast.Name)
                    and func.value.id in names):
                return True
            if isinstance(func, ast.Name) and func.id in local_makers:
                return True
    return False


#: Окно имени: сколько символов текста ВПЛОТНУЮ к числу считается его именем.
#: Величина объявлена, а не выведена, и это сказано вслух — но она не
#: произвольна: брать текстовый прогон между числами ЦЕЛИКОМ значило бы
#: считать именем каждое слово абзаца, и при семи числах в одной строке все
#: семь вышли бы многозначными разом. Обе стороны закреплены сторожем: токен
#: внутри окна называет число, он же за окном — нет.
NAME_WINDOW_CHARS = 40


def _adjacent_text(values: List[ast.AST], index: int) -> Tuple[str, str]:
    """Литеральный текст СЛЕВА и СПРАВА от значения в той же f-строке.

    Имя числа для читателя есть то, что стои́т рядом с ним, в пределах
    объявленного окна :data:`NAME_WINDOW_CHARS`.
    """
    before = ""
    after = ""
    if index > 0 and isinstance(values[index - 1], ast.Constant):
        raw = values[index - 1].value
        before = raw[-NAME_WINDOW_CHARS:] if isinstance(raw, str) else ""
    if index + 1 < len(values) and isinstance(values[index + 1], ast.Constant):
        raw = values[index + 1].value
        after = raw[:NAME_WINDOW_CHARS] if isinstance(raw, str) else ""
    return before, after


def _consumer_scope(tree: ast.AST, scope: Optional[Tuple[str, ...]]) -> List[ast.AST]:
    """Узлы, внутри которых читатель разбирается."""
    if not scope:
        return [tree]
    return [node for node in ast.walk(tree)
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
            and node.name in scope]


def _binding_regions(nodes: List[ast.AST]) -> List[List[ast.AST]]:
    """Области СВЯЗЫВАНИЯ имени: функция — своя, модуль — своя.

    Не украшение, а исправление собственной ошибки замера 21.09: якорь есть
    ИМЯ, и имя, связанное с документом переписи в одной функции, в соседней
    не связано ничем. Обход всего файла разом объявил бы `doc` из чужой
    функции нашим документом — и прибор выдумал бы находку ровно того класса,
    который ищет («контейнер привязкой не является», `.claude/rules/`).

    Вложенная функция остаётся ВНУТРИ области родителя: замыкание читает его
    имена по-настоящему, и делить их значило бы потерять верное чтение.
    """
    regions: List[List[ast.AST]] = []

    def _split(container: ast.AST) -> List[ast.AST]:
        rest: List[ast.AST] = []
        for stmt in getattr(container, "body", []):
            if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):
                regions.append([stmt])
            elif isinstance(stmt, ast.ClassDef):
                rest.extend(_split(stmt))
            else:
                rest.append(stmt)
        return rest

    for node in nodes:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            regions.append([node])
            continue
        outer = _split(node)
        if outer:
            regions.append(outer)
    return regions


def _read_consumer(root: Path, spec: dict) -> dict:
    """Разбор ОДНОГО потребителя: какие базы читает и как их зовёт."""
    path = root / spec["path"]
    head = {"key": spec["key"], "path": spec["path"], "what": spec["what"]}
    try:
        source = path.read_text(encoding="utf-8")
    except OSError as exc:
        return {**head, "status": CONSUMER_UNMEASURED,
                "reason": f"файл потребителя не прочитан: {exc}"}
    try:
        tree = ast.parse(source)
    except SyntaxError as exc:
        return {**head, "status": CONSUMER_UNMEASURED,
                "reason": f"файл потребителя не разобран: {exc}"}

    consts = _module_string_consts(tree)
    nodes = _consumer_scope(tree, spec.get("scope"))
    if spec.get("scope") and not nodes:
        return {**head, "status": CONSUMER_UNMEASURED,
                "reason": ("объявленной области "
                           f"{list(spec['scope'])} в файле нет — читать нечего")}

    # Якорь: документ переписи. У производителя это первый параметр
    # отрисовщика, у чужого модуля — возврат `run`/`measure` производителя.
    #
    # Режим ОБЪЯВЛЯЕТСЯ спецификацией, а не выводится из пути, и разница не
    # педантизм: у `main` производителя первый параметр — `argv`, а вовсе не
    # документ, и правило «первый параметр» приписало бы якорь строке разбора
    # аргументов. Умолчание повторяет прежнее поведение буква в букву.
    mode = spec.get("anchor") or (ANCHOR_FIRST_PARAM if spec["path"] == PRODUCER
                                  else ANCHOR_PRODUCER_CALL)
    local_makers = (frozenset(_LOCAL_DOC_MAKERS) if mode == ANCHOR_LOCAL_RUN
                    else frozenset())
    # Местное имя производителя. Объявляется спецификацией: у моста это
    # `rule_second_copy_census`, у соседних переписей — `census`/`rules`.
    aliases = frozenset(spec.get("aliases")
                        or (_PRODUCER_MODULE_NAME,))
    regions = _binding_regions(nodes)
    region_state: List[Tuple[List[ast.AST], set, Dict[str, str]]] = []
    for region in regions:
        anchors: set = set()
        if mode == ANCHOR_FIRST_PARAM:
            for node in region:
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) \
                        and node.args.args:
                    anchors.add(node.args.args[0].arg)
        binding: Dict[str, str] = {}
        for _ in range(16):             # до неподвижной точки, не «на глазок»
            before = (len(anchors), len(binding))
            for scope_node in region:
                for node in ast.walk(scope_node):
                    target = source_expr = None
                    if (isinstance(node, ast.Assign) and len(node.targets) == 1
                            and isinstance(node.targets[0], ast.Name)):
                        target, source_expr = node.targets[0].id, node.value
                    elif (isinstance(node, ast.For)
                          and isinstance(node.target, ast.Name)):
                        target, source_expr = node.target.id, node.iter
                    if target is None:
                        continue
                    if not _derives_from_census(source_expr, anchors,
                                                local_makers, aliases):
                        continue
                    anchors.add(target)
                    if isinstance(node, ast.Assign) and target not in binding:
                        coord = _terminal_coordinate(source_expr, consts,
                                                     binding)
                        if coord is not None:
                            binding[target] = coord
            if before == (len(anchors), len(binding)):
                break
        region_state.append((region, anchors, binding))

    delegates = sorted({
        alias.asname or alias.name
        for node in ast.walk(tree)
        if isinstance(node, ast.ImportFrom) and node.module
        and node.module.split(".")[-1] == _PRODUCER_MODULE_NAME
        for alias in node.names if alias.name in _PRODUCER_RENDERERS})
    if mode == ANCHOR_LOCAL_RUN:
        # Внутри производителя отрисовщик ввозить неоткуда: он зовётся голым
        # именем. Искать здесь ТОЛЬКО ввоз значило бы объявить `main`, который
        # печатает `report(doc)`, ничего не читающим.
        local_calls = set()
        for scope_node in nodes:
            for node in ast.walk(scope_node):
                if (isinstance(node, ast.Call)
                        and isinstance(node.func, ast.Name)
                        and node.func.id in _PRODUCER_RENDERERS):
                    local_calls.add(node.func.id)
        delegates = sorted(set(delegates) | local_calls)

    coord_to_base: Dict[str, set] = {}
    for base in CENSUS_BASES:
        for coord in base["coordinates"]:
            coord_to_base.setdefault(coord, set()).add(base["key"])

    numbers: List[dict] = []
    outside_fstring = 0
    for region, anchors, binding in region_state:
        for scope_node in region:
            for node in ast.walk(scope_node):
                if not isinstance(node, ast.JoinedStr):
                    continue
                for index, value in enumerate(node.values):
                    if not isinstance(value, ast.FormattedValue):
                        continue
                    if not _derives_from_census(value.value, anchors,
                                                local_makers, aliases):
                        continue
                    coord = _terminal_coordinate(value.value, consts, binding)
                    bases = coord_to_base.get(coord or "", set())
                    if len(bases) != 1:
                        continue
                    base_key = next(iter(bases))
                    before, after = _adjacent_text(node.values, index)
                    near = f"{before} {after}".lower()
                    tokens = sorted({token for base in CENSUS_BASES
                                     for token in base["tokens"]
                                     if token in near})
                    numbers.append({
                        "line": node.lineno, "base": base_key,
                        "coordinate": coord, "tokens": tokens,
                        "before": before, "after": after})
    # Чтение ВНЕ f-строки прибор не разбирает — и говорит это числом, а не
    # молчанием: `%`, `.format` и склейка остаются слепым пятном.
    for region, anchors, binding in region_state:
        for scope_node in region:
            for node in ast.walk(scope_node):
                if not isinstance(node, ast.Call):
                    continue
                for arg in node.args:
                    if isinstance(arg, ast.JoinedStr):
                        continue
                    if not _derives_from_census(arg, anchors, local_makers,
                                                aliases):
                        continue
                    coord = _terminal_coordinate(arg, consts, binding)
                    if coord and coord in coord_to_base:
                        outside_fstring += 1

    if numbers:
        status = CONSUMER_READS
    elif delegates:
        status = CONSUMER_DELEGATES
    else:
        status = CONSUMER_NO_READ
    return {**head, "status": status, "numbers": numbers,
            "delegates_via": delegates,
            "bases_read": sorted({item["base"] for item in numbers}),
            "reads_outside_fstring": outside_fstring}


def consumer_base_naming(root: Path) -> dict:
    """Какую БАЗУ берёт каждый названный потребитель и каким ИМЕНЕМ зовёт (**G65 п. 1**).

    ADR-442 нашёл расхождение у самой базы: пары книг и строки ``GENUINE`` —
    разные множества. Заказ G65 п. 1 спрашивает следующий вопрос: **кто из
    читателей какую базу берёт**, и не зовёт ли он её именем другой.

    Мера устроена из двух половин, и вторая — ЗАМЕР:

    * **объявлено** — какие координаты документа суть одна база и какими
      токенами базу зовут (:data:`CENSUS_BASES`);
    * **измерено** — рядом с какими базами токен ФАКТИЧЕСКИ встал в коде
      читателей. Токен, оказавшийся смежным ДВУМ базам, многозначен по
      ЗАМЕРУ, а не по объявлению; именно это отличает находку от таблицы.

    Именем числа считается литеральный текст, стоящий вплотную слева и справа
    от него в той же f-строке: читатель видит имя рядом с числом, а не абзац
    целиком.

    Третий исход назван везде (инв. #17): файла нет / не разобран / области
    нет ⇒ ``UNMEASURED`` с причиной; читатель без своей базы, но зовущий
    отрисовщик производителя, ⇒ ``DELEGATES`` — это НЕ ноль, он доносит чужую
    базу вместе с её многозначностью; читатель, не делающий ни того, ни
    другого, ⇒ ``NO_READ``, и это находка о реестре, а не тишина. Чтения вне
    f-строки прибор не разбирает и говорит об этом числом
    (``reads_outside_fstring``), а не молчанием.
    """
    head = {
        "question": ("какую БАЗУ берёт каждый названный потребитель переписи "
                     "и каким ИМЕНЕМ её зовёт (заказ G65 п. 1)"),
        "declared_bases": [{"key": base["key"], "what": base["what"],
                            "coordinates": list(base["coordinates"]),
                            "tokens": list(base["tokens"])}
                           for base in CENSUS_BASES],
        "declared_consumers": [spec["key"] for spec in CENSUS_CONSUMERS],
    }
    if not CENSUS_BASES or not CENSUS_CONSUMERS:
        return {**head, "status": "UNMEASURED",
                "reason": ("реестр баз или потребителей пуст — спрашивать "
                           "некого и не о чем; это НЕ «расхождений нет»")}

    consumers = [_read_consumer(root, spec) for spec in CENSUS_CONSUMERS]

    # СМЕЖНОСТЬ токена с базами — по всему населению читателей сразу. Токен,
    # вставший рядом с двумя базами, читателю их не различает ничем.
    token_bases: Dict[str, set] = {}
    for consumer in consumers:
        for item in consumer.get("numbers") or []:
            for token in item["tokens"]:
                token_bases.setdefault(token, set()).add(item["base"])
    ambiguous_tokens = sorted(token for token, bases in token_bases.items()
                              if len(bases) > 1)

    declared_token_bases: Dict[str, set] = {}
    for base in CENSUS_BASES:
        for token in base["tokens"]:
            declared_token_bases.setdefault(token, set()).add(base["key"])

    findings: List[dict] = []
    tally = {NAMING_SINGLE: 0, NAMING_CROSS: 0,
             NAMING_AMBIGUOUS: 0, NAMING_UNNAMED: 0}
    for consumer in consumers:
        for item in consumer.get("numbers") or []:
            if not item["tokens"]:
                verdict = NAMING_UNNAMED
            elif any(token in ambiguous_tokens for token in item["tokens"]):
                verdict = NAMING_AMBIGUOUS
            elif all(item["base"] not in declared_token_bases.get(token, set())
                     for token in item["tokens"]):
                verdict = NAMING_CROSS
            else:
                verdict = NAMING_SINGLE
            item["verdict"] = verdict
            tally[verdict] += 1
            if verdict in (NAMING_CROSS, NAMING_AMBIGUOUS):
                findings.append({"consumer": consumer["key"], **item})

    # Делегирующий читатель несёт ровно те имена, что печатает отрисовщик
    # производителя: своих у него нет. Поэтому спрашивается СЕКЦИЯ ОТЧЁТА, а
    # не сам делегат — у делегата чисел ноль ПО ПОСТРОЕНИЮ.
    renderer_ambiguous = any(
        item.get("verdict") in (NAMING_CROSS, NAMING_AMBIGUOUS)
        for consumer in consumers if consumer["path"] == PRODUCER
        for item in (consumer.get("numbers") or []))
    carriers = sorted({consumer["key"] for consumer in consumers
                       if consumer.get("status") == CONSUMER_DELEGATES
                       and renderer_ambiguous})

    return {
        **head,
        "status": "MEASURED",
        "consumers": consumers,
        "token_adjacency": {token: sorted(bases)
                            for token, bases in sorted(token_bases.items())},
        "ambiguous_tokens": ambiguous_tokens,
        "naming": tally,
        "findings": findings,
        # Делегирующий читатель своей базы не имеет — и потому доносит до глаз
        # ЧУЖУЮ, вместе со всею её многозначностью. Ноль здесь был бы ответом
        # не на тот вопрос.
        "carries_ambiguity_by_delegation": carriers,
        "blind": [
            "чтения вне f-строки (`%`, `.format`, склейка) не разбираются — "
            "их число названо полем `reads_outside_fstring` у каждого читателя",
            "таблица токенов ОБЪЯВЛЕНА; многозначность выведена из ЗАМЕРА "
            "смежности, но токен, не объявленный ни одной базе, прибору невидим",
            "«назвал верно» не означает, что число верно: мера про ИМЯ у "
            "числа, а не про его происхождение",
            f"именем считается текст в окне {NAME_WINDOW_CHARS} символов "
            "вплотную к числу: слово из другого конца длинного прогона именем "
            "не признаётся, и это ОБЪЯВЛЕННЫЙ выбор, а не замер",
        ],
    }


#: --- РЕЕСТР ЧИТАТЕЛЕЙ ПРОТИВ ЗАМЕРА ЗОВУЩИХ (заказ G66 п. 1) -------------
#:
#: ADR-443 измерил, какую базу берёт каждый НАЗВАННЫЙ читатель, и сказал
#: вслух, чего не спрашивал: реестр :data:`CENSUS_CONSUMERS` литерален, и
#: читатель, в нём не названный, прибору невидим. Заказ G66 п. 1 требует
#: свести два населения — объявленное реестром и ИЗМЕРЕННОЕ — и спросить,
#: есть ли среди неназванных печатающий числа переписи.

#: Сосед, у которого спрашивается измеренное население зовущих. Своего обхода
#: здесь нет намеренно: второй экземпляр того же правила и есть предмет, за
#: которым вся перепись и написана.
NEIGHBOUR_CENSUS = "spa_core.monitoring.census_consumer_census"

#: Что у соседа обязано быть, чтобы вопрос был задан. Отсутствие — третий
#: исход с названной причиной, а не ноль зовущих.
_NEIGHBOUR_API = ("find_callees", "find_by_name_consumers",
                  "find_cli_consumers", "find_dynamic_consumers",
                  "find_fleet_consumers", "_CODE_DIRS")

#: Область производителя, в которой живёт его собственный CLI. ОБЪЯВЛЕНА:
#: сосед называет класс `cli` ФАЙЛОМ, реестр читателей — ОБЛАСТЬЮ, и свести
#: их по одному файлу значило бы объявить названным то, чего реестр не читает.
CLI_SCOPE = "main"

#: Происхождение места-потребителя. Разделено, потому что вопросы разные:
#: сосед спрашивает «кто ЗОВЁТ `run`», поверхность ввоза — «кто вообще берёт
#: этот модуль в руки». Второе шире первого ровно на тех, кто ввозит
#: отрисовщик; именно они соседу невидимы по построению.
ORIGIN_BY_NAME = "neighbour:by_name"
ORIGIN_CLI = "neighbour:cli"
ORIGIN_DYNAMIC = "neighbour:dynamic"
ORIGIN_FLEET = "neighbour:fleet"
ORIGIN_IMPORT = "import_surface"

SITE_NAMED = "NAMED"
SITE_UNNAMED = "UNNAMED"

#: Почему объявленный реестром читатель не встретился в измеренном населении.
#: Три исхода, и первые два — НЕ дефект реестра: они про РАЗНИЦУ ВОПРОСОВ.
UNSEEN_INSIDE_PRODUCER = "inside_producer"
UNSEEN_RENDERER_IMPORT = "renderer_import"
UNSEEN_NO_LINK = "no_link_found"

#: Канал места. Печать теста до оркестратора не доезжает, и складывать её с
#: печатью кода значило бы ответить не на тот вопрос. Разделение ОБЪЯВЛЕНО
#: здесь, до замера, а не выбрано по его исходу (запрет G62).
CHANNEL_CODE = "code"
CHANNEL_TEST = "test"

#: Что именно читатель берёт из производителя — от этого зависит, способен ли
#: он вообще напечатать его числа.
IMPORT_MODULE = "module"
IMPORT_RENDERER = "renderer"
IMPORT_SYMBOLS = "symbols_only"


def _enclosing_scope(tree: ast.AST, lineno: int) -> Optional[str]:
    """Имя САМОЙ ВНУТРЕННЕЙ функции, накрывающей строку; ``None`` — модуль.

    Нужна потому, что сосед называет место ФАЙЛОМ и СТРОКОЙ, а реестр
    читателей — ОБЛАСТЬЮ. Без приведения к общей координате сведение двух
    населений было бы сведением по разным осям.
    """
    best: Optional[Tuple[int, str]] = None
    for node in ast.walk(tree):
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        end = getattr(node, "end_lineno", None)
        if end is None or not (node.lineno <= lineno <= end):
            continue
        if best is None or node.lineno > best[0]:
            best = (node.lineno, node.name)
    return best[1] if best else None


def _channel_of(rel: str) -> str:
    """Канал места: печать теста до оркестратора не доезжает."""
    name = rel.replace("\\", "/").split("/")[-1]
    return CHANNEL_TEST if name.startswith("test_") else CHANNEL_CODE


def producer_import_surface(root: Path,
                            code_dirs: Iterable[str]) -> List[dict]:
    """Кто ВВОЗИТ производителя — в любой из трёх форм ввоза.

    Разбор идёт AST, а не текстом, и это замер, а не педантизм: форма
    ``from spa_core.monitoring import rule_second_copy_census`` полного имени
    в тексте не оставляет вовсе, а по ней перепись зовёт мост. Текстовое
    правило потеряло бы ровно того потребителя, который до оркестратора и
    доезжает.

    ``code_dirs`` — ЧУЖОЙ параметр: каталоги берутся у соседа, чьё население
    мы и сводим. Объявить их здесь своей константой значило бы завести вторую
    копию определения населения — ровно тот класс, который перепись и ищет; и
    расхождение двух копий читалось бы как расхождение двух ПРИБОРОВ.
    """
    out: List[dict] = []
    for sub in code_dirs:
        base = root / sub
        if not base.is_dir():
            continue
        for path in sorted(base.rglob("*.py")):
            rel = str(path.relative_to(root))
            if rel == PRODUCER:          # производитель себя не ввозит
                continue
            try:
                tree = ast.parse(path.read_text(encoding="utf-8"))
            except (OSError, SyntaxError, UnicodeDecodeError) as exc:
                out.append({"file": rel, "line": 0, "kind": None,
                            "names": [], "unreadable": str(exc)})
                continue
            for node in ast.walk(tree):
                names: List[str] = []
                kind: Optional[str] = None
                aliases: List[str] = []
                if isinstance(node, ast.ImportFrom) and node.module:
                    tail = node.module.split(".")[-1]
                    if tail == _PRODUCER_MODULE_NAME:
                        names = [alias.name for alias in node.names]
                        kind = (IMPORT_RENDERER
                                if any(n in _PRODUCER_RENDERERS for n in names)
                                else IMPORT_SYMBOLS)
                    else:
                        for alias in node.names:
                            if alias.name == _PRODUCER_MODULE_NAME:
                                names = [_PRODUCER_MODULE_NAME]
                                kind = IMPORT_MODULE
                                aliases.append(alias.asname or alias.name)
                elif isinstance(node, ast.Import):
                    for alias in node.names:
                        if alias.name.split(".")[-1] == _PRODUCER_MODULE_NAME:
                            names = [alias.name]
                            kind = IMPORT_MODULE
                            aliases.append(alias.asname or alias.name)
                if kind is None:
                    continue
                out.append({"file": rel, "line": node.lineno, "kind": kind,
                            "names": sorted(names), "aliases": sorted(aliases),
                            "scope": _enclosing_scope(tree, node.lineno)})
    return out


def _site_registry_key(site: dict) -> Optional[str]:
    """Какой записью реестра место НАЗВАНО; ``None`` — не названо ни одной.

    Область существенна: запись с объявленной областью не называет место вне
    неё, даже если файл тот же. Иначе `main` производителя оказался бы
    «названным» записью, которая читает только отрисовщик.
    """
    for spec in CENSUS_CONSUMERS:
        if spec["path"] != site["file"]:
            continue
        scope = spec.get("scope")
        if not scope:
            return spec["key"]
        if site.get("scope") in scope:
            return spec["key"]
    return None


def consumer_registry_completeness(root: Path) -> dict:
    """Реестр читателей против ИЗМЕРЕННОГО населения зовущих (**G66 п. 1**).

    Два населения сводятся по общей координате «файл + область»:

    * **объявлено** — литеральный реестр :data:`CENSUS_CONSUMERS`;
    * **измерено** — (а) четыре класса соседа
      :data:`NEIGHBOUR_CENSUS` (он мерит, кто зовёт ``run``) и (б) поверхность
      ВВОЗА производителя, измеряемая здесь.

    Две половины измеренного населения разные ПО ВОПРОСУ, и это главное:
    соседний вопрос («кто зовёт ``run``») не выражает потребителя, который
    ввозит ОТРИСОВЩИК. Такой потребитель соседу невидим по построению, и ноль
    в его классах про него ничего не говорит.

    Третий исход назван везде (инв. #17): соседа нет / у него нет нужного
    имени / он не числит эту перепись переписью ⇒ ``UNMEASURED`` с причиной,
    а не «зовущих нет». Неразрешимый статикой зов соседа едет отдельным
    ЧИСЛОМ, а не тонет в нуле.

    Порог не вводится: ни один вердикт переписи этой координатой не меняется
    (``applied`` ложно). Выбирать правило, увидев его исход, — запрет G62.
    """
    head = {
        "question": ("сколько зовущих эту перепись НЕ названо реестром имён "
                     "и есть ли среди них печатающий её числа (заказ G66 п. 1)"),
        "neighbour": NEIGHBOUR_CENSUS,
        "declared_consumers": [
            {"key": spec["key"], "path": spec["path"],
             "scope": list(spec["scope"]) if spec.get("scope") else None}
            for spec in CENSUS_CONSUMERS],
        "applied": False,
    }
    if not CENSUS_CONSUMERS:
        return {**head, "status": "UNMEASURED",
                "reason": ("реестр читателей пуст — сводить не с чем; это НЕ "
                           "«неназванных нет»")}
    try:
        neighbour = importlib.import_module(NEIGHBOUR_CENSUS)
    except Exception as exc:                        # noqa: BLE001 — причина важнее класса
        return {**head, "status": "UNMEASURED",
                "reason": (f"соседняя координата {NEIGHBOUR_CENSUS} не ввезена "
                           f"({type(exc).__name__}: {exc}) — измеренного "
                           f"населения зовущих нет, и это не ноль зовущих")}
    missing = [name for name in _NEIGHBOUR_API if not hasattr(neighbour, name)]
    if missing:
        return {**head, "status": "UNMEASURED",
                "reason": (f"у соседа нет имён {missing} — спросить население "
                           f"нечем; сведение не выполнено")}
    try:
        callees = neighbour.find_callees(root)
    except Exception as exc:                        # noqa: BLE001
        return {**head, "status": "UNMEASURED",
                "reason": (f"сосед не смог перечислить переписи "
                           f"({type(exc).__name__}: {exc})")}
    if _PRODUCER_MODULE_NAME not in callees:
        return {**head, "status": "UNMEASURED",
                "reason": ("сосед не числит эту перепись переписью (контракт "
                           "`run(root=…)` у неё им не найден) — его население "
                           "зовущих про неё молчит ПО ПОСТРОЕНИЮ")}

    sites: List[dict] = []
    trees: Dict[str, Optional[ast.AST]] = {}

    def _tree(rel: str) -> Optional[ast.AST]:
        if rel not in trees:
            try:
                trees[rel] = ast.parse((root / rel).read_text(encoding="utf-8"))
            except (OSError, SyntaxError, UnicodeDecodeError):
                trees[rel] = None
        return trees[rel]

    for item in neighbour.find_by_name_consumers(root, callees):
        if item.get("callee") != _PRODUCER_MODULE_NAME:
            continue
        tree = _tree(item["file"])
        sites.append({
            "origin": ORIGIN_BY_NAME, "file": item["file"],
            "line": item["line"],
            "scope": _enclosing_scope(tree, item["line"]) if tree else None,
            "whole_file": False,
            "channel": _channel_of(item["file"]),
            "detail": f"root_argument={item.get('root_argument')}"})
    for item in neighbour.find_cli_consumers(root, callees):
        if item.get("callee") != _PRODUCER_MODULE_NAME:
            continue
        if not item.get("has_main"):
            continue
        tree = _tree(item["file"])
        line = 0
        if tree is not None:
            for node in ast.walk(tree):
                if (isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
                        and node.name == CLI_SCOPE):
                    line = node.lineno
        sites.append({
            "origin": ORIGIN_CLI, "file": item["file"], "line": line,
            "scope": CLI_SCOPE, "whole_file": False,
            "channel": _channel_of(item["file"]),
            "detail": f"run_root_default={item.get('run_root_default')}"})
    dynamic = neighbour.find_dynamic_consumers(root, callees)
    for item in (dynamic.get("resolved") or []):
        if item.get("callee") != _PRODUCER_MODULE_NAME:
            continue
        tree = _tree(item["file"])
        sites.append({
            "origin": ORIGIN_DYNAMIC, "file": item["file"],
            "line": item.get("line", 0),
            "scope": (_enclosing_scope(tree, item.get("line", 0))
                      if tree else None),
            "whole_file": False,
            "channel": _channel_of(item["file"]), "detail": "importlib"})
    for item in neighbour.find_fleet_consumers(root, callees):
        if item.get("callee") != _PRODUCER_MODULE_NAME:
            continue
        sites.append({
            "origin": ORIGIN_FLEET, "file": item.get("file", ""),
            "line": item.get("line", 0), "scope": None, "whole_file": True,
            "channel": _channel_of(item.get("file", "")),
            "detail": "обёртка флота"})

    imports = producer_import_surface(root, neighbour._CODE_DIRS)
    import_unreadable = [item for item in imports if item.get("unreadable")]
    by_file: Dict[str, dict] = {}
    for item in imports:
        if item.get("unreadable"):
            continue
        # Единицей ввоза является ФАЙЛ, а не строка: ввезённое имя живёт во
        # всём модуле, и приписывать потребителя области импорта значило бы
        # спросить о чтении там, где его заведомо нет.
        kept = by_file.get(item["file"])
        rank = {IMPORT_RENDERER: 2, IMPORT_MODULE: 2, IMPORT_SYMBOLS: 1}
        if kept is None:
            by_file[item["file"]] = dict(item)
            continue
        # Псевдонимы СКЛАДЫВАЮТСЯ: файл, ввёзший производителя дважды под
        # разными именами, читает его под обоими, и потерять одно значило бы
        # объявить не читающим то, что читается.
        kept["aliases"] = sorted(set(kept.get("aliases") or [])
                                 | set(item.get("aliases") or []))
        if rank[item["kind"]] > rank[kept["kind"]]:
            merged = dict(item)
            merged["aliases"] = kept["aliases"]
            by_file[item["file"]] = merged
    for rel, item in sorted(by_file.items()):
        sites.append({
            "origin": ORIGIN_IMPORT, "file": rel, "line": item["line"],
            "scope": None, "whole_file": True, "channel": _channel_of(rel),
            "import_kind": item["kind"], "imports": item["names"],
            "aliases": item.get("aliases") or [],
            "detail": f"ввоз {item['kind']}"})

    seen_keys: set = set()
    seen_by_neighbour: set = set()
    for site in sites:
        key = _site_registry_key(site)
        site["registry"] = key
        site["verdict"] = SITE_NAMED if key else SITE_UNNAMED
        if key:
            seen_keys.add(key)
            if site["origin"] != ORIGIN_IMPORT:
                seen_by_neighbour.add(key)

    for site in sites:
        if site["verdict"] != SITE_UNNAMED:
            continue
        spec = {
            "key": f"{site['file']}:{site.get('scope') or '<модуль>'}",
            "path": site["file"],
            "scope": None if site["whole_file"] else (site["scope"],),
            "anchor": (ANCHOR_LOCAL_RUN if site["file"] == PRODUCER
                       else ANCHOR_PRODUCER_CALL),
            "aliases": tuple(site.get("aliases")
                             or (_PRODUCER_MODULE_NAME,)),
            "what": "место, измеренное как потребитель и не названное реестром",
        }
        if not site["whole_file"] and not site.get("scope"):
            site["read"] = {"status": CONSUMER_UNMEASURED,
                            "reason": ("место вне функции, и областью его "
                                       "назвать нечем")}
            continue
        site["read"] = _read_consumer(root, spec)

    declared_unseen: List[dict] = []
    for spec in CENSUS_CONSUMERS:
        if spec["key"] in seen_by_neighbour:
            continue
        seen_elsewhere = spec["key"] in seen_keys
        if spec["path"] == PRODUCER:
            reason = UNSEEN_INSIDE_PRODUCER
        elif seen_elsewhere:
            reason = UNSEEN_RENDERER_IMPORT
        else:
            reason = UNSEEN_NO_LINK
        declared_unseen.append({
            "key": spec["key"], "path": spec["path"], "reason": reason,
            "seen_by_import_surface": seen_elsewhere})

    unnamed = [site for site in sites if site["verdict"] == SITE_UNNAMED]
    unnamed_reading = [site for site in unnamed
                       if (site.get("read") or {}).get("status") == CONSUMER_READS]
    findings: List[dict] = []
    for site in unnamed_reading:
        findings.append({
            "kind": "unnamed_reader_prints_numbers",
            "file": site["file"], "line": site["line"],
            "scope": site.get("scope"), "channel": site["channel"],
            "numbers": len((site.get("read") or {}).get("numbers") or []),
            "why": ("место печатает числа переписи, а реестр читателей о нём "
                    "молчит — его имена не мерил никто")})
    for item in declared_unseen:
        if item["reason"] != UNSEEN_RENDERER_IMPORT:
            continue
        findings.append({
            "kind": "declared_consumer_invisible_to_neighbour",
            "file": item["path"], "line": 0, "scope": None,
            "channel": _channel_of(item["path"]), "numbers": 0,
            "why": ("объявленный читатель ВВОЗИТ отрисовщик и `run` не зовёт — "
                    "соседний вопрос «кто зовёт run» его не выражает вовсе, и "
                    "ноль в его классах про этого читателя не говорит ничего")})

    counts = {
        "declared": len(CENSUS_CONSUMERS),
        "sites": len(sites),
        "named": len(sites) - len(unnamed),
        "unnamed": len(unnamed),
        "unnamed_reading": len(unnamed_reading),
        "unnamed_code": len([s for s in unnamed if s["channel"] == CHANNEL_CODE]),
        "unnamed_test": len([s for s in unnamed if s["channel"] == CHANNEL_TEST]),
        "seen_by_neighbour": len(seen_by_neighbour),
        "declared_unseen_by_neighbour": len(declared_unseen),
        "import_surface": len(by_file),
        # Неразрешимый статикой зов — ЧИСЛО, а не ноль: «мы не смогли
        # посмотреть» и «там никого нет» разные утверждения (ADR-326).
        "neighbour_dynamic_unresolved": len(dynamic.get("unresolved") or []),
        "import_files_unreadable": len(import_unreadable),
    }
    by_origin: Dict[str, int] = {}
    for site in sites:
        by_origin[site["origin"]] = by_origin.get(site["origin"], 0) + 1

    return {
        **head,
        "status": "MEASURED",
        "counts": counts,
        "by_origin": by_origin,
        "sites": sites,
        "declared_unseen": declared_unseen,
        "unreadable": import_unreadable,
        "findings": findings,
        "blind": [
            "население зовущих у соседа ограничено четырьмя классами: зов "
            "через отрисовщик ему невидим ПО ПОСТРОЕНИЮ, и поверхность ввоза "
            "здесь — НАША добавка к его вопросу, а не его ответ",
            f"зовов, не разрешимых статикой, у соседа "
            f"{counts['neighbour_dynamic_unresolved']} — среди них может быть "
            f"и наш, и это число, а не ноль",
            "ввоз не есть ЧТЕНИЕ: файл, ввёзший имя и ни разу его не "
            "позвавший, попадает в население и честно получает NO_READ",
            "канал теста считается ОТДЕЛЬНО и ОБЪЯВЛЕН заранее: печать теста "
            "до оркестратора не доезжает, но потребителем контракта он быть "
            "не перестаёт",
            "порог не введён: ни один вердикт переписи эта координата не "
            "меняет (`applied` ложно)",
        ],
    }


def bilingual_reach(root: Path, rows: List[dict],
                    index: Dict[str, List[str]],
                    synonyms: Optional[dict] = None) -> dict:
    """Свод заказа **G60**: одноязычие — свойство ОДНОГО свидетеля или ВСЕХ.

    Сводится здесь, а не доливается в соседние координаты, по той же причине,
    по которой отдельны все пять прежних: «сколько объявлено» и «что прибавило
    бы двуязычие» суть разные вопросы, и общий ключ слил бы их ответы.
    """
    table = _TOKEN_SYNONYMS if synonyms is None else synonyms
    if not table:
        return {
            "verdict": BILINGUAL_NOTHING_TO_ASK,
            "reason": ("карта синонимов пуста — спрашивать двуязычие нечем; "
                       "это НЕ «одноязычие безвредно»"),
            "witnesses": {},
        }
    subject = bilingual_subject_reach(root, rows, table)
    names = bilingual_name_reach(root, index, table)
    coverage = synonym_map_coverage(root, table)
    witnesses = {WITNESS_SUBJECT: subject, WITNESS_NAME_CHANNEL: names}
    unmeasured = [who for who, what in witnesses.items()
                  if what.get("status") == BILINGUAL_UNMEASURED]
    if unmeasured:
        return {
            "verdict": BILINGUAL_UNMEASURED,
            "reason": "; ".join(
                f"{who}: {witnesses[who].get('reason')}" for who in unmeasured),
            "witnesses": witnesses,
            "map_coverage": coverage,
        }
    gained = subject["changed"] + names["authority_corroborated"]
    if gained:
        verdict = BILINGUAL_SHIFT
        reason = (
            f"двуязычие прибавляет свидетеля: у `{WITNESS_SUBJECT}` "
            f"{subject['changed']} пар(ы) из {subject['pairs_read']}, у канала "
            f"имени {names['authority_corroborated']} пар(ы) с подтверждающей "
            f"величиной из {names['authority_raw']} названных — одноязычие "
            f"свойство НЕ одной координаты")
    else:
        verdict = BILINGUAL_INERT
        reason = (
            f"карта спрошена и не сдвинула ни одного вердикта: у "
            f"`{WITNESS_SUBJECT}` карта применима к {subject['askable']} из "
            f"{subject['modules']} модулей населения, у канала имени "
            f"{names['candidates']} разрешимых имён — ноль ИЗМЕРЕН")
    return {
        "verdict": verdict,
        "reason": reason,
        "question": ("одноязычие — свойство ОДНОЙ координаты или ВСЕХ "
                     "свидетелей имени (заказ G60 пп. 1–2)"),
        "witnesses": witnesses,
        "map_coverage": coverage,
        "blind": [
            "подтверждение ВЕЛИЧИНОЙ есть фильтр обозримости, а НЕ доказательство "
            "тождества смысла: одно число называет несколько порогов (ADR-418), и "
            "названные пары проверяет человек, а не эта координата",
            "ноль у свидетеля предмета есть свойство КАРТЫ, а не дерева, ровно "
            "настолько, насколько мал `askable`: карту спросили не у всего населения",
            "полнота карты измерена ТОЛЬКО по порогам, уже известным переписи; "
            "порог, не объявленный ни одной поверхностью решения, этой мере не виден",
            "контроль мерит ЧАСТОТУ канала на абзацах без языка права изменения, а "
            "не верность найденной пары — это разные вопросы",
            "канал имени по ТОКЕНАМ строго слабее дословного: двуязычие его не "
            "усиливает, а расширяет население, и цена расширения названа числом",
        ],
    }


def measure(root: Path, *, now: Optional[dt.datetime] = None,
            probe_ledger: Optional[Path] = None) -> dict:
    """Перепись пар «сторож × исполнитель × имя»."""
    root = Path(root)
    if not root.is_dir():
        raise NotMeasured(f"корень дерева не прочитан: {root}")

    unreadable: List[dict] = []

    # --- сторона исполнителя: имя -> [(модуль, значение)] --------------------
    executors: Dict[str, List[Tuple[str, Optional[str]]]] = {}
    # Второе население — ВСЕ имена верхнего уровня, включая приватные: ось
    # «исполнитель × исполнитель» (заказ G52 п. 1) считает их копиями, и
    # основание этой разницы названо в докстринге `peer_pairs`.
    declared: Dict[str, List[Tuple[str, Optional[str]]]] = {}
    exec_imports: Dict[str, set] = {}
    executor_files = _executor_files(root)
    for path in executor_files:
        rel = path.relative_to(root).as_posix()
        try:
            tree = ast.parse(path.read_text(encoding="utf-8"))
        except Exception as exc:  # noqa: BLE001
            unreadable.append({"file": rel, "side": "executor",
                               "reason": f"{type(exc).__name__}: {exc}"})
            continue
        exec_imports[rel] = imported_modules(tree)
        for name, value in toplevel_constants(tree).items():
            declared.setdefault(name, []).append((rel, value))
            if name.startswith("_"):
                continue        # приватное имя правилом наружу не является
            executors.setdefault(name, []).append((rel, value))

    # --- сторона сторожа ----------------------------------------------------
    rows: List[dict] = []
    counts = {CLASS_TWO_COPIES: 0, CLASS_DELEGATES: 0, CLASS_VALUE_DIFFERS: 0,
              CLASS_NOT_CONSTANT: 0, CLASS_AMBIGUOUS: 0}
    surface: List[str] = []
    # Третья ось (заказ G53 п. 1) спрашивает сторожей о тех же именах, что и
    # ось исполнителей. Держатся ИМЯ и ЗНАЧЕНИЕ (дёшево), а текст сторожа
    # перечитывается лениво и только у кандидатов — тем же `_text`, что и у
    # соседней оси: вторая копия правила «как читать файл» здесь не заводится.
    guard_declared: Dict[str, List[Tuple[str, Optional[str]]]] = {}
    guard_imports_by_rel: Dict[str, set] = {}
    guard_files = _guard_files(root)
    # Пороги спрашиваются ПОСЛЕ корней населения и ДО разбора форм. Порядок
    # обоих отказов измерен тестами: «корень не прочитан» остаётся первым
    # (он отменяет перепись целиком), а «пороги не прочитаны» отменяет право
    # чинить — и ни один из них не выдаётся за пустой результат.
    thresholds = risk_policy_thresholds(root)
    for path in guard_files:
        rel = path.relative_to(root).as_posix()
        try:
            source = path.read_text(encoding="utf-8")
            tree = ast.parse(source)
        except Exception as exc:  # noqa: BLE001
            unreadable.append({"file": rel, "side": "guard",
                               "reason": f"{type(exc).__name__}: {exc}"})
            continue

        guard_imports = imported_modules(tree)
        guard_imports_by_rel[rel] = guard_imports
        touches_state = any(mark in source for mark in _REPO_STATE_MARKS)

        for name, guard_value in toplevel_constants(tree).items():
            if name.startswith("_") or name.startswith("test_"):
                continue
            guard_declared.setdefault(name, []).append((rel, guard_value))
            side = executors.get(name)
            if not side:
                continue
            if len(side) > 1:
                # Имя, объявленное многими исполнителями, не называет ОДНО
                # правило. Это не находка и не «сошлось» — это своя корзина.
                counts[CLASS_AMBIGUOUS] += 1
                continue
            exec_rel, exec_value = side[0]
            if guard_value is None or exec_value is None:
                counts[CLASS_NOT_CONSTANT] += 1
                continue
            if guard_value != exec_value:
                counts[CLASS_VALUE_DIFFERS] += 1
                continue
            if reaches(source, guard_imports, exec_rel):
                counts[CLASS_DELEGATES] += 1
                continue
            counts[CLASS_TWO_COPIES] += 1
            rows.append({
                "verdict": CLASS_TWO_COPIES,
                "guard": rel,
                "executor": exec_rel,
                "name": name,
                "value": guard_value,
            })

        # Сторож трогает состояние репозитория и НИ ОДНОЙ дверью не достаёт
        # дерева-предмета ⇒ каждое проверяемое им условие — его собственная
        # копия ПО ПОСТРОЕНИЮ. Переименованную копию правило имени не видит
        # никогда, и вот её верхняя граница.
        if touches_state and not _reaches_subject_tree(source):
            surface.append(rel)

    rows.sort(key=lambda r: (r["guard"], r["name"]))

    # --- форма починки у каждой находки (заказ G42 п. 1) --------------------
    # Витрина порогов читается ДО разбора форм: с заказа G54 п. 1 её
    # спрашивают ВСЕ ТРИ оси, а не одна лишь третья.
    constitution, constitution_unread = constitution_values(root)
    remedy_counts = {cls: 0 for cls in _REMEDY_CLASSES}
    text_cache: Dict[str, Optional[str]] = {}

    def _text(rel: str) -> Optional[str]:
        if rel not in text_cache:
            try:
                text_cache[rel] = (root / rel).read_text(encoding="utf-8")
            except OSError:
                text_cache[rel] = None
        return text_cache[rel]

    ledger, ledger_absent = load_probe_ledger(
        Path(probe_ledger) if probe_ledger is not None else root / PROBE_LEDGER)
    probe_stats = {"fresh": 0, "stale": 0, "missing": 0,
                   "ledger_absent": ledger_absent}

    for row in rows:
        if row["verdict"] not in _FINDING_CLASSES:
            continue
        probe = _probe_verdict(root, row, ledger, probe_stats)
        guard_text = _text(row["guard"])
        guard_loads: Optional[bool] = None
        if guard_text is not None:
            try:
                guard_loads = constant_is_loaded(ast.parse(guard_text), row["name"])
            except SyntaxError:
                guard_loads = None       # не разобрано ⇒ НЕ «не читается»
        row.update(classify_remedy(row, guard_text=guard_text,
                                   executor_text=_text(row["executor"]),
                                   thresholds=thresholds,
                                   constitution=constitution,
                                   constitution_unread=constitution_unread,
                                   probe=probe, guard_loads=guard_loads))
        remedy_counts[row["remedy"]] += 1

    # --- вторая ось: копия между двумя исполнителями (заказ G52 п. 1) ------
    # Текст стороны перечитывается лениво и только у кандидатов: держать в
    # памяти исходники всех исполнителей ради вопроса, который задаётся
    # шестистам именам, — цена без покупателя.
    peer_rows, peer_counts = peer_pairs(
        declared,
        source_of=_text,
        imports_of=lambda rel: exec_imports.get(rel, set()),
        thresholds=thresholds,
        constitution=constitution,
        constitution_unread=constitution_unread)

    # --- третья ось: ТРИ копии одного правила (заказ G53 п. 1) -------------
    triple_rows, triple_counts = triple_copies(
        peer_rows, guard_declared,
        source_of=_text,
        imports_of=lambda rel: guard_imports_by_rel.get(rel, set()),
        thresholds=thresholds,
        constitution=constitution,
        constitution_unread=constitution_unread)
    intersection = axes_intersection(rows, peer_rows, declared)

    # --- население ПОВЕРХНОСТЕЙ РЕШЕНИЯ (заказ G55 п. 1) -------------------
    # Спрашивается у находок ВСЕХ ТРЁХ осей разом: поверхность решения не
    # знает, какая ось нашла пару, и делить население по осям значило бы
    # ответить на вопрос об устройстве прибора вместо вопроса о репозитории.
    surface_population = (
        [r for r in rows if r["verdict"] in _FINDING_CLASSES]
        + [r for r in peer_rows if r["verdict"] == CLASS_PEER_TWO_COPIES]
        + [r for r in triple_rows if r["verdict"] == CLASS_TRIPLE])
    surfaces = decision_surfaces(root, surface_population)

    # --- канал ОБЪЯВЛЕНИЯ ИМЕНЕМ (заказ G56 п. 2) -------------------------
    # Мера выше ходит по ПУТЯМ и сама называет свою слепоту: объявление бывает
    # именем класса. Здесь у слепоты появляется число — население пути
    # перестаёт быть нижней границей с неизвестным зазором.
    definitions = toplevel_definitions(root)
    names = name_channel(
        root, surface_population,
        path_candidates=[s["path"] for s in (surfaces.get("surfaces") or [])],
        definitions=definitions)

    # --- канал ШИРОКОГО АБЗАЦА (заказ G57 п. 1) ---------------------------
    # Оба прежних канала молчат об абзаце, который мера пути отбрасывает как
    # широкий: канал пути его не читает, канал имени видит в нём только имена.
    # Здесь считается ПОТОЛОК зазора — и считается отдельной координатой,
    # которая в население объявленных поверхностей ничего не доливает.
    wide = wide_paragraph_channel(
        root, surface_population,
        path_candidates=[s["path"] for s in (surfaces.get("surfaces") or [])],
        name_candidates=[s["path"] for s in (names.get("surfaces") or [])]
        + list(names.get("already_declared_by_path") or []))

    # --- ФОРМА ШИРОКОЙ ТАБЛИЦЫ (заказ G58 п. 1) ---------------------------
    # Канал выше назвал ЦЕНУ широкого абзаца; заказ спрашивает, редка ли его
    # ФОРМА. Вопрос о выборке, поэтому меряется он и контролем — но контроль
    # каналом объявления не становится и в население поверхностей не входит.
    table_form = table_form_census(root)

    # --- ЧИСЛА ВНЕ КАНАЛА (заказ G59 п. 2) --------------------------------
    # Координата выше НАЗЫВАЕТ семь мест той же формы в `docs/**`; права
    # чинить у их чисел не спрашивает никто. Здесь спрашивается, пороги ли
    # это: если да — узка не форма, а ГРАНИЦА канала объявления.
    out_channel = out_of_channel_numbers(
        root, (table_form.get("channels", {})
               .get(TABLE_CHANNEL_DOCS, {})
               .get("long_line_hits") or []))

    # --- ДОСЯГАЕМОСТЬ ДВУЯЗЫЧИЯ (заказ G60 пп. 1–2) -----------------------
    # Координата выше нашла одноязычие У СЕБЯ и починила его картой. Здесь
    # спрашивается, класс это или единичный случай: населением служат ВСЕ три
    # оси переписи, а не та выборка, на которой одноязычие нашлось.
    bilingual = bilingual_reach(root, rows + peer_rows + triple_rows,
                                definitions[0])

    # --- ТОЧНОСТЬ КАНАЛА ИМЕНИ (заказ G61 п. 1) ---------------------------
    # Координата выше сказала, что двуязычие ПРИБАВЛЯЕТ пары. Сколько из них
    # настоящие — она не спрашивает, и «2 из 4» ADR-438 есть замер выборки
    # размера четыре. Здесь размечается ВСЁ население канала правилом,
    # записанным до разметки; в население объявленных поверхностей эта
    # координата ничего не доливает — она судит уже сделанный замер.
    name_channel_doc = (bilingual.get("witnesses") or {}).get(WITNESS_NAME_CHANNEL)
    name_precision = bilingual_name_precision(root, name_channel_doc)

    # --- ЦЕНА ТРЕБОВАНИЯ ДВУХ ТОКЕНОВ (заказ G62 п. 1) --------------------
    # Ширину интервала выше держит `UNDECIDED`, и заказ назвал кандидата:
    # потребовать у имени не один различающий токен, а два. Здесь считается
    # ЦЕНА кандидата в двух валютах и его независимость — сам порог не
    # вводится, поэтому координата ничего не гейтит и ни во что не входит.
    depth_price = token_depth_price(name_precision, name_channel_doc)

    # --- КАНДИДАТЫ В ТРЕТЬИ СВИДЕТЕЛИ (заказ G63 п. 1) --------------------
    # Координата выше доказала, что кандидат прежнего заказа читает ИМЯ и
    # потому свидетелем не является. Форма искомого названа — читать АБЗАЦ, —
    # и здесь кандидаты этой формы объявляются ДО разметки и меряются двумя
    # числами: решённые `UNDECIDED` и частота ошибки на контроле. Ни один
    # вердикт переписи эта координата не меняет.
    witness_price = paragraph_witness_price(root, name_precision)

    # --- ЦЕНА ДОПУСКА СВИДЕТЕЛЯ В ПРАВИЛО (заказ G64 п. 1) ---------------
    # Координата выше измерила у кандидатов два числа и прямо сказала, чего
    # не доказала: что кандидата стои́т ВВЕСТИ. Цена введения платится в
    # валюте книг — в парах, — и здесь считается именно она, вместе с обеими
    # границами интервала истины. Порог по-прежнему не вводится.
    admission_price = witness_admission_price(root, name_precision,
                                              name_channel_doc)

    # --- КАКУЮ БАЗУ БЕРЁТ ЧИТАТЕЛЬ (заказ G65 п. 1) ----------------------
    # Координата выше нашла расхождение у САМОЙ базы (пары книг ≠ `GENUINE`)
    # и честно сказала, чего не спрашивала: КТО из читателей какую базу берёт.
    # Здесь спрошены все три названных заказом читателя поимённо. Ни один
    # вердикт переписи эта координата не меняет — она мерит СЛОВАРЬ.
    base_naming = consumer_base_naming(root)

    # --- РЕЕСТР ЧИТАТЕЛЕЙ ПРОТИВ ЗАМЕРА ЗОВУЩИХ (заказ G66 п. 1) ---------
    # Координата выше мерила ИМЕНА у чисел трёх НАЗВАННЫХ читателей и честно
    # сказала, чего не спрашивала: полно ли само население читателей. Здесь
    # объявленное сводится с измеренным — и ни один вердикт переписи этой
    # координатой не меняется.
    registry_completeness = consumer_registry_completeness(root)

    scanned = len(guard_files) + len(executor_files)
    classified = scanned - len(unreadable)
    findings = [r for r in rows if r["verdict"] in _FINDING_CLASSES]
    return {
        "generated_at": (now or _utcnow()).isoformat(),
        "generated_by": PRODUCER,
        "invoked_by": call_provenance(tree_root=root),
        "status": "FINDING" if findings else "CLEAN",
        "question": "у скольких правил есть ИСПОЛНИТЕЛЬ и СТОРОЖ, проверяющие одно условие РАЗНЫМ кодом",
        "population_rule": (
            "сторож — собираемый pytest файл test_*.py из каталогов предписанного "
            "прогона; исполнитель — не-тестовый модуль spa_core/ + scripts/ (без "
            "scripts/archive/); координата — имя верхнего уровня с КОНСТАНТНЫМ "
            "значением, у которого исполнитель РОВНО ОДИН"
        ),
        "scanned": scanned,
        "guards": len(guard_files),
        "executors": len(executor_files),
        "counts": dict(counts, unreadable=len(unreadable)),
        "remedy_counts": remedy_counts,
        # Пара, у которой имя сторожа не читается, из населения не исчезает:
        # строка остаётся, меняется её форма. Число «на учёте» считается здесь,
        # чтобы «стало меньше» нельзя было выдать за «нашлось меньше».
        "findings_on_books": len(
            [r for r in rows if r["verdict"] in _FINDING_CLASSES
             and r.get("remedy") != REMEDY_UNUSED]),
        "probe": probe_stats,
        # Вторая ось — ЧИСЛО поверхности, а не перечень приговоров, и на
        # `status` она НАМЕРЕННО не влияет: 189 строк, влитые в находки,
        # утопили бы девять пар первой оси, а заказ просил числа. Читателем
        # числа служит строка отчёта шага 0-офис, печатаемая каждый прогон;
        # храповика у него сегодня нет, и это сказано вслух, а не подразумевается.
        "peer_counts": peer_counts,
        "peer_rows": peer_rows,
        "peer_owner_subject": len([r for r in peer_rows
                                   if r.get("remedy") == REMEDY_OWNER]),
        "peer_remedy_counts": {
            cls: len([r for r in peer_rows
                      if r.get("verdict") == CLASS_PEER_TWO_COPIES
                      and r.get("remedy") == cls])
            for cls in _PEER_REMEDY_CLASSES},
        # Сдвиг формы починки от вопроса к ВТОРОЙ поверхности решения
        # (заказ G54 п. 1) — по каждой соседней оси отдельно: числа разные,
        # и одно из них ноль, который обязан быть ИЗМЕРЕННЫМ, а не структурным.
        "constitution_shift": {
            "first_axis": constitution_shift(
                rows, finding_classes=_FINDING_CLASSES,
                constitution_unread=constitution_unread),
            "peer_axis": constitution_shift(
                peer_rows, finding_classes=(CLASS_PEER_TWO_COPIES,),
                constitution_unread=constitution_unread),
        },
        "peer_private_names": len([r for r in peer_rows
                                   if r.get("private_name")]),
        "risk_policy_thresholds": len(thresholds),
        # Пересечение осей ПО ИМЕНИ (заказ G53 п. 1) и — отдельным вопросом —
        # ПОЧЕМУ оно такое. Ноль без второго поля был бы не ответом.
        "axes_intersection": intersection,
        # Третья ось. На `status` не влияет по той же причине, что и вторая:
        # она мерит ПОВЕРХНОСТЬ числом, а не выносит приговор каждой строке.
        "triple_counts": triple_counts,
        "triple_rows": triple_rows,
        "triple_names": triple_name_count(triple_rows),
        "triple_remedy_counts": {
            cls: len([r for r in triple_rows if r.get("remedy") == cls])
            for cls in _TRIPLE_REMEDY_CLASSES},
        # Население ОБЪЯВЛЕННЫХ поверхностей решения (заказ G55 п. 1). На
        # `status` не влияет по той же причине, что вторая и третья оси: это
        # число о поверхности, а не приговор строке.
        "decision_surfaces": surfaces,
        # Канал объявления ИМЕНЕМ (заказ G56 п. 2). Отдельной координатой, а не
        # доливкой в `decision_surfaces`: там число есть ответ на вопрос «что
        # объявлено ПУТЁМ», и подмешать туда имена значило бы стереть разницу
        # между двумя каналами вместо того, чтобы её измерить.
        "name_channel": names,
        # Третья координата того же вопроса (заказ G57 п. 1). Отдельным
        # ключом, а не доливкой в две прежних: население объявленных
        # поверхностей и ПОТОЛОК зазора — разные числа, и предел
        # `MAX_DECLARING_PARAGRAPH` этой координатой не ослабляется.
        "wide_paragraph_channel": wide,
        # Четвёртая координата того же вопроса (заказ G58 п. 1). Отдельным
        # ключом по той же причине, что и три прежних: «сколько правил имеют
        # эту форму» и «что объявлено» — разные вопросы, и контроль здесь
        # объявлением не является.
        "table_form_census": table_form,
        # Пятая координата того же вопроса (заказ G59 п. 2). Отдельным
        # ключом: «какой формы абзац» и «порог ли стоящее в нём число» —
        # разные вопросы, и общий ключ слил бы их ответы.
        "out_of_channel_numbers": out_channel,
        # Шестая координата того же вопроса (заказ G60 пп. 1–2). Отдельным
        # ключом: «одноязычен ли ЭТОТ канал» и «одноязычны ли ВСЕ свидетели
        # имени» — разные вопросы, и ответ второго не является поправкой к
        # первому.
        "bilingual_reach": bilingual,
        "bilingual_name_precision": name_precision,
        "token_depth_price": depth_price,
        "paragraph_witness_price": witness_price,
        "witness_admission_price": admission_price,
        # Седьмая координата того же вопроса (заказ G65 п. 1). Отдельным
        # ключом: «разошлись ли базы» и «какую из них берёт читатель» —
        # разные вопросы, и ответ второго не является поправкой к первому.
        "consumer_base_naming": base_naming,
        # Восьмая координата того же вопроса (заказ G66 п. 1). Отдельным
        # ключом: «как читатель зовёт базу» и «все ли читатели названы» —
        # разные вопросы, и ответ второго не является поправкой к первому.
        "consumer_registry_completeness": registry_completeness,
        "constitution_values": len(constitution),
        "constitution_unread": constitution_unread,
        "classified": classified,
        "rows": rows,
        "unreadable": unreadable,
        # Доказанный МИНИМУМ переименованных копий: сторож, ни разу не
        # упомянувший дерево-предмет, держит свою копию наверняка. Потолком это
        # число не является — см. docstring.
        "renamed_copy_surface": sorted(surface),
        "what_it_does_not_prove": [
            "что у найденной пары копия вредит СЕГОДНЯ — вред приходит с правкой одной из копий",
            "что совпавшее значение имеет общее происхождение (SEED = 42 может быть совпадением)",
            "что население полно — переименованная копия невидима; renamed_copy_surface есть доказанный МИНИМУМ, а не потолок",
            "что сторож из delegates не держит второй копии рядом — дверь найдена, пользование ею не спрошено",
            "что пара subject_unproven есть СОВПАДЕНИЕ — свидетели общего предмета односторонние, «не доказан» третий исход",
            "что пара owner_subject есть ОДНА величина — равенство с порогом RiskPolicy отправляет её владельцу, а не выносит приговор",
            "что у пары subject_proven_by_behaviour общий ключ читается ИМЕННО из общего артефакта — статически связать их нечем, и прибор связи не выдумывает",
            "что пара independent_by_probe не имеет общего предмета — зонд мерит ЗАВИСИМОСТЬ ВЕРДИКТА от значения, а не происхождение числа; несогласие со свидетелем называется в строке",
            "что у пары ОСИ ИСПОЛНИТЕЛЕЙ (peer_*) копия вредна — ось мерит ПОВЕРХНОСТЬ числом; вреда у неё не спрашивали, и зонд независимости её пар не трогает",
            "что 189 у оси исполнителей есть потолок класса — переименованная копия невидима ей так же, как и первой оси, и ровно по той же причине",
            "что пустое пересечение осей означает отсутствие правил с ТРЕМЯ копиями — оно пусто ПО ПОСТРОЕНИЮ (1 исполнитель против 2), и на вопрос отвечает отдельная координата triple_copies",
            "что у находки третьей оси копия вредна СЕГОДНЯ — ось мерит поверхность; зонд независимости её строк не трогает так же, как и строк второй оси",
            "что право чинить спрошено у ВСЕХ поверхностей решения — население ОБЪЯВЛЕННЫХ правилами измерено (decision_surfaces) и есть доказанный минимум: поверхность, не названную ни одним правилом, мера не видит",
            "что объявленная поверхность решения ДЕЙСТВИТЕЛЬНО им является — объявлением считается абзац правила с языком права изменения, и ошибка отбора направлена в сторону «спросить», а не «чинить молча»",
            "что пара `constitution_subject` держит ТО ЖЕ число, что и витрина, — равенство величины не есть тождество смысла ровно так же, как у порога RiskPolicy; потому пара и уходит владельцу, а не чинится",
            "что нулевой сдвиг на первой оси есть свойство ДЕРЕВА — знаменатель там 5 сравнимых пар из 9, и это сказано числом, а не словом",
            "что население поверхностей решения ПОЛНО и после канала имени — объявление модулем через точку (`spa_core.risk.policy`) не ловится ни одним из двух каналов, и зазор остаётся, только теперь он МЕНЬШЕ и назван",
            "что имя, разрешённое единственным файлом, объявлено правилом ИМЕННО как поверхность решения — канал имени, как и канал пути, ошибается в сторону «спросить», а не «починить молча»",
            "что пара, найденная ДВУЯЗЫЧНЫМ каналом имени, есть вторая копия того же порога — совпадение величины в абзаце фильтрует пары для обозримости, а тождество смысла проверяет человек",
            "что нулевой сдвиг у свидетеля предмета есть свойство ДЕРЕВА — он ровно настолько свойство КАРТЫ, насколько мал `askable`, и это число едет рядом с нулём",
            "что карта синонимов ПОЛНА — её полнота измерена только по порогам, уже известным переписи, и число незакрытых токенов названо",
            "что читатель, назвавший базу ВЕРНО, печатает верное ЧИСЛО — мера про имя у числа, а не про его происхождение",
            "что население читателей полно — реестр `CENSUS_CONSUMERS` литерален по замыслу, и читатель, в нём не названный, прибору невидим",
            "что чтение вне f-строки отсутствует — оно НЕ разбирается, и его число едет отдельным полем у каждого читателя",
            "что население зовущих ПОЛНО и после сведения с соседом — у соседа четыре класса зова, и зов, не разрешимый статикой, едет у него ЧИСЛОМ; поверхность ввоза добавляет ввозящих, а не исчерпывает зовущих",
            "что неназванный читатель БЕЗВРЕДЕН — измерено «печатает ли он числа переписи», а не «верно ли он их понимает»",
        ],
    }


def _reaches_subject_tree(source: str) -> bool:
    """Достаёт ли сторож дерево-предмет хоть как-нибудь.

    Отдельная функция, а не выражение на месте: поверхность слепоты — второе
    по важности число прибора, и правило её отбора обязано быть одним и
    проверяемым тестом.
    """
    return ("spa_core" in source) or ("scripts" in source)


def report(doc: dict, *, max_rows: int = 20) -> List[str]:
    """Строки отчёта. Единственное место, где перепись превращается в текст."""
    status = str(doc.get("status"))
    if status == "UNMEASURED":
        return [f"НЕ ИЗМЕРЕНО — {observed(doc, 'reason', kind=str) or 'причина не записана'}"]
    counts = observed(doc, "counts", kind=dict) or {}
    out = [
        f"одно правило — две копии (заказ G41 п. 1): {status} · "
        f"две копии {counts.get(CLASS_TWO_COPIES)} · "
        f"сторож достаёт исполнителя {counts.get(CLASS_DELEGATES)} · "
        f"значения разные {counts.get(CLASS_VALUE_DIFFERS)} · "
        f"сравнить нечем {counts.get(CLASS_NOT_CONSTANT)} · "
        f"исполнитель не один {counts.get(CLASS_AMBIGUOUS)}",
        f"[ЗВАВШИЙ] {provenance_line(observed(doc, 'invoked_by', kind=dict))}",
        f"[УЧЁТ] осмотрено {doc.get('scanned')} = разобрано {doc.get('classified')} "
        f"+ не разобрано {counts.get('unreadable')} "
        f"(сторожей {doc.get('guards')}, исполнителей {doc.get('executors')})",
    ]
    remedy = observed(doc, "remedy_counts", kind=dict)
    if remedy is None:
        out.append("[ФОРМА ПОЧИНКИ] НЕ ИЗМЕРЕНА — перепись собрана без разбора форм")
    else:
        out.append(
            f"[ФОРМА ПОЧИНКИ] ввозом {remedy.get(REMEDY_IMPORT)} · "
            f"предмет владельца {remedy.get(REMEDY_OWNER)} · "
            f"предмет витрины порогов {remedy.get(REMEDY_CONSTITUTION)} · "
            f"право чинить НЕ ИЗМЕРЕНО {remedy.get(REMEDY_RIGHT_UNMEASURED)} · "
            f"предмет доказан поведением {remedy.get(REMEDY_BEHAVIOUR)} · "
            f"имя у сторожа не читается {remedy.get(REMEDY_UNUSED)} · "
            f"предмет НЕ доказан {remedy.get(REMEDY_UNPROVEN)} · "
            f"не разобрано {remedy.get(REMEDY_UNREADABLE)}")
        on_books = observed(doc, "findings_on_books", kind=int)
        out.append(
            f"[НА УЧЁТЕ] {on_books if on_books is not None else 'НЕ ИЗМЕРЕНО'} "
            f"из {counts.get(CLASS_TWO_COPIES)} пар — с учёта снимает ровно одно "
            f"основание (имя у сторожа не читается), и снятая пара из НАСЕЛЕНИЯ "
            f"не исчезает")
    probe = observed(doc, "probe", kind=dict)
    if probe is None:
        out.append("[ЗОНД] НЕ ИЗМЕРЕН — перепись собрана без чтения журнала зонда")
    else:
        absent = probe.get("ledger_absent")
        drift = {}
        for row in (doc.get("rows") or []):
            if row.get("drift"):
                drift[row["drift"]] = drift.get(row["drift"], 0) + 1
        out.append(
            f"[ЗОНД] годных записей {probe.get('fresh')} · протухших "
            f"{probe.get('stale')} · нет записи {probe.get('missing')}"
            + (f" · {absent}" if absent else "")
            + " — протухшая запись возвращает пару НА учёт, а не снимает с него")
        toothless = len([r for r in (doc.get("rows") or [])
                         if r.get("verdict_teeth") == "none"])
        out.append(
            f"[СНОС ВРОЗЬ] молча {drift.get(PROBE_DRIFT_SILENT, 0)} · с краснотой "
            f"{drift.get(PROBE_DRIFT_LOUD, 0)} · вердикт сторожа без зубов "
            f"{toothless} — это про ВРЕД, а не про предмет: ни один из трёх пару "
            f"с учёта НЕ снимает; снимает только СТАТИЧЕСКОЕ «имя не читается»")
    findings = [r for r in (doc.get("rows") or []) if r["verdict"] in _FINDING_CLASSES]
    for row in findings[:max_rows]:
        tail = ""
        if row.get("remedy"):
            tail = f" · {row['remedy']}: {row.get('remedy_evidence', 'основание не записано')}"
        out.append(
            f"[НАХОДКА] {row['name']} = {row['value']} — сторож {row['guard']} "
            f"против исполнителя {row['executor']}{tail}")
    if len(findings) > max_rows:
        # Умолчание об укорочении и есть способ соврать усечением.
        out.append(f"[…] показаны {max_rows} находки из {len(findings)}; "
                   f"полный перечень — в артефакте")
    peer = observed(doc, "peer_counts", kind=dict)
    if peer is None:
        out.append("[ПАРА ИСПОЛНИТЕЛЕЙ] НЕ ИЗМЕРЕНА — перепись собрана без второй оси")
    else:
        owner = observed(doc, "peer_owner_subject", kind=int)
        priv = observed(doc, "peer_private_names", kind=int)
        two = peer.get(CLASS_PEER_TWO_COPIES)
        out.append(
            f"[ПАРА ИСПОЛНИТЕЛЕЙ] копия между двумя исполнителями {two} · "
            f"дверь открыта {peer.get(CLASS_PEER_DELEGATES)} · значения разные "
            f"{peer.get(CLASS_PEER_VALUE_DIFFERS)} · сравнить нечем "
            f"{peer.get(CLASS_PEER_NOT_CONSTANT)} · имя у многих исполнителей "
            f"{peer.get(CLASS_PEER_MANY)} · дверь НЕ ИЗМЕРЕНА "
            f"{peer.get(CLASS_PEER_UNMEASURED)}")
        peer_remedy = observed(doc, "peer_remedy_counts", kind=dict) or {}
        out.append(
            f"[ПРАВО ЧИНИТЬ] из них величина равна порогу RiskPolicy у "
            f"{owner if owner is not None else 'НЕ ИЗМЕРЕНО'} · объявлена "
            f"витриной порогов сайта у {peer_remedy.get(REMEDY_CONSTITUTION)} · "
            f"НЕ ИЗМЕРЕНО {peer_remedy.get(REMEDY_RIGHT_UNMEASURED)} · "
            f"не возражает никто {peer_remedy.get(REMEDY_UNPROVEN)} — первые "
            f"две формы агент НЕ чинит; равенство числа не есть тождество "
            f"смысла, и сверка ошибается в сторону «спросить»")
        out.append(
            f"[ИМЯ] приватных {priv if priv is not None else 'НЕ ИЗМЕРЕНО'} из "
            f"{two} — на этой оси приватное имя из населения НЕ выбрасывается: "
            f"прочитать чужое `_X` нельзя, и копия от этого не мнимая, а "
            f"неизбежная; меняется лишь форма починки")
        peer_rows = [r for r in (doc.get("peer_rows") or [])
                     if r.get("verdict") == CLASS_PEER_TWO_COPIES]
        for row in peer_rows[:max_rows]:
            out.append(
                f"[ПАРА] {row['name']} = {row['value']} — {row['left']} × "
                f"{row['right']} · {row.get('remedy')}")
        if len(peer_rows) > max_rows:
            out.append(f"[…] показаны {max_rows} пар(ы) из {len(peer_rows)}; "
                       f"полный перечень — в артефакте")
        out.append(
            "[ПОЧЕМУ ОСЬ ЕСТЬ] молчание первой оси об этой паре было НЕ "
            "свидетельством: в сцене с ВОССТАНОВЛЕННОЙ второй копией её вердикт "
            "оставался побуквенно тем же (ADR-430). Ось не влияет на `status` — "
            "она мерит поверхность числом, а не выносит приговор каждой паре")
    shift = observed(doc, "constitution_shift", kind=dict)
    if shift is None:
        out.append("[ВТОРАЯ ПОВЕРХНОСТЬ] НЕ ИЗМЕРЕНА — перепись собрана без вопроса G54 п. 1")
    else:
        for key, label in (("first_axis", "сторож × исполнитель"),
                           ("peer_axis", "исполнитель × исполнитель")):
            ax = shift.get(key) or {}
            out.append(
                f"[ВТОРАЯ ПОВЕРХНОСТЬ · {label}] {ax.get('verdict')} · "
                f"сменили форму починки {ax.get('moved')} из "
                f"{ax.get('comparable')} сравнимых "
                f"(население {ax.get('population')} = порог RiskPolicy "
                f"{ax.get('owner_by_threshold')} + сравнимых "
                f"{ax.get('comparable')} + витрина молчит по построению "
                f"{ax.get('silent_by_construction')}); {ax.get('reason')}")
            for move, n in sorted((ax.get("transitions") or {}).items()):
                out.append(f"[СДВИГ] {move}: {n}")
            names = ax.get("moved_names") or []
            if names:
                out.append(f"[СДВИГ · имена] {', '.join(names[:max_rows])}"
                           + (f" … ещё {len(names) - max_rows}"
                              if len(names) > max_rows else ""))
    inter = observed(doc, "axes_intersection", kind=dict)
    if inter is None:
        out.append("[ПЕРЕСЕЧЕНИЕ ОСЕЙ] НЕ ИЗМЕРЕНО — перепись собрана без вопроса G53 п. 1")
    else:
        hist = inter.get("executors_per_name") or {}
        out.append(
            f"[ПЕРЕСЕЧЕНИЕ ОСЕЙ] имён, о которых говорят ОБЕ оси: "
            f"{inter.get('count')} — {inter.get('verdict')}; "
            f"{inter.get('reason')}")
        out.append(
            f"[ОСНОВАНИЕ] исполнителей у имён первой оси {hist.get('axis_one')} · "
            f"у имён второй {hist.get('axis_two')} — ноль читается по этим "
            f"числам, а не по слову «нет»")
    triple = observed(doc, "triple_counts", kind=dict)
    if triple is None:
        out.append("[ТРИ КОПИИ] НЕ ИЗМЕРЕНЫ — перепись собрана без третьей оси")
    else:
        names = observed(doc, "triple_names", kind=int)
        remedy3 = observed(doc, "triple_remedy_counts", kind=dict) or {}
        out.append(
            f"[ТРИ КОПИИ] сторож × два исполнителя {triple.get(CLASS_TRIPLE)} "
            f"пар(ы) на {names if names is not None else 'НЕ ИЗМЕРЕНО'} имён(и) · "
            f"дверь к одному {triple.get(CLASS_TRIPLE_DOOR_ONE)} · дверь к обоим "
            f"{triple.get(CLASS_TRIPLE_DOOR_BOTH)} · значения разные "
            f"{triple.get(CLASS_TRIPLE_VALUE_DIFFERS)} · сравнить нечем "
            f"{triple.get(CLASS_TRIPLE_NOT_CONSTANT)} · дверь НЕ ИЗМЕРЕНА "
            f"{triple.get(CLASS_TRIPLE_UNMEASURED)}")
        unread = doc.get("constitution_unread")
        out.append(
            f"[ПРАВО ЧИНИТЬ · 2 ПОВЕРХНОСТИ] предмет RiskPolicy "
            f"{remedy3.get(REMEDY_OWNER)} · предмет витрины порогов "
            f"{remedy3.get(REMEDY_CONSTITUTION)} · право НЕ ИЗМЕРЕНО "
            f"{remedy3.get(REMEDY_RIGHT_UNMEASURED)} · предмет не доказан "
            f"{remedy3.get(REMEDY_UNPROVEN)}"
            + (f" — {unread}" if unread else ""))
        triple_rows = [r for r in (doc.get("triple_rows") or [])
                       if r.get("verdict") == CLASS_TRIPLE]
        for row in triple_rows[:max_rows]:
            out.append(
                f"[ТРОЙКА] {row['name']} = {row['value']} — сторож "
                f"{row['guard']} против {row['left']} × {row['right']} · "
                f"{row.get('remedy')}: {row.get('remedy_evidence', 'основание не записано')}")
        if len(triple_rows) > max_rows:
            # Умолчание об укорочении и есть способ соврать усечением.
            out.append(f"[…] показаны {max_rows} тройки из {len(triple_rows)}; "
                       f"полный перечень — в артефакте")
        unmeasured = [r for r in (doc.get("triple_rows") or [])
                      if r.get("verdict") == CLASS_TRIPLE_UNMEASURED]
        for row in unmeasured[:max_rows]:
            out.append(f"[НЕ ИЗМЕРЕНО] {row['name']} — сторож {row['guard']}: "
                       f"{row.get('reason', 'причина не записана')}")
        out.append(
            "[ПОЧЕМУ ОСЬ ЕСТЬ] пересечение двух прежних осей пусто ПО "
            "ПОСТРОЕНИЮ и о трёх копиях не говорит ничего; храповика у этого "
            "числа сегодня НЕТ, рост виден только в этой строке (остаток G52 п. 2)")
    surfaces = observed(doc, "decision_surfaces", kind=dict)
    if surfaces is None:
        out.append("[ПОВЕРХНОСТИ РЕШЕНИЯ] НЕ ИЗМЕРЕНЫ — перепись собрана без "
                   "координаты населения (заказ G55 п. 1)")
    else:
        out.append(
            f"[ПОВЕРХНОСТИ РЕШЕНИЯ] {surfaces.get('verdict')} · объявлено "
            f"правилами {surfaces.get('candidates')} · из них шкафов чисел "
            f"{surfaces.get('shelves')} · сменили бы форму "
            f"{surfaces.get('would_move_total')} пар(ы); {surfaces.get('reason')}")
        for row in (surfaces.get("surfaces") or []):
            if row.get("kind") != SURFACE_SHELF:
                continue
            where = (row.get("declared_by") or [{}])[0]
            out.append(
                f"[ШКАФ] {row['path']} — чисел {row.get('numbers')} · называет "
                f"находок {row.get('matches')} · сменили бы форму "
                f"{row.get('would_move')} · спрашивается сегодня: "
                f"{'да' if row.get('asked_today') else 'НЕТ'} · объявлен "
                f"{where.get('text')}:{where.get('line')}")
            if row.get("would_move_names"):
                out.append(f"[ШКАФ · имена] {', '.join(row['would_move_names'][:8])}")
        for row in (surfaces.get("surfaces") or []):
            if row.get("kind") == SURFACE_SHELF:
                continue
            out.append(f"[НЕ ШКАФ] {row['path']} — {row.get('kind')}: "
                       f"{row.get('reason', 'причина не записана')}")
        for row in (surfaces.get("asked") or []):
            if row.get("declared_by_rules"):
                where = (row.get("evidence") or [{}])[0]
                out.append(f"[СПРАШИВАЕТСЯ] {row['path']} — объявлен правилом "
                           f"{where.get('text')}:{where.get('line')}")
            else:
                out.append(
                    f"[СПРАШИВАЕТСЯ, НО НЕ ОБЪЯВЛЕН ПУТЁМ] {row['path']} — "
                    f"правила не называют этого ПУТИ ни разу (упоминаний "
                    f"{row.get('mentions_in_rules')}). Про объявление ИМЕНЕМ "
                    f"эта строка не говорит ничего — его мерит координата "
                    f"`name_channel` ниже, и на 20.09 оно там НАШЛОСЬ "
                    f"(заказ G56 п. 2, ADR-434)")
        adr = surfaces.get("adr_channel") or {}
        out.append(
            f"[КАНАЛ ADR ОТВЕРГНУТ] в {adr.get('files')} ADR абзацы с языком "
            f"права изменения называют {adr.get('named_paths')} путь(ей), из них "
            f"артефактов data/ {adr.get('artifact_paths')}; реестр "
            f"{adr.get('registry')} исключён по замеру: "
            f"{adr.get('registry_long_lines')} из {adr.get('registry_lines')} "
            f"строк длиннее {MAX_DECLARING_LINE} символов — построчная мера там "
            f"совпадает со всем подряд")
        for blind in (surfaces.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    names = observed(doc, "name_channel", kind=dict)
    if names is None:
        out.append("[КАНАЛ ИМЕНИ] НЕ ИЗМЕРЕН — перепись собрана без координаты "
                   "объявления именем (заказ G56 п. 2)")
    elif names.get("verdict") == NAME_CHANNEL_UNMEASURED:
        out.append(f"[КАНАЛ ИМЕНИ] {NAME_CHANNEL_UNMEASURED}: {names.get('reason')}")
    else:
        out.append(
            f"[КАНАЛ ИМЕНИ] {names.get('verdict')} · абзацев с языком права "
            f"изменения {names.get('paragraphs_authority')} · из них БЕЗ ПУТИ "
            f"{names.get('paragraphs_without_path')} · зазор к населению пути "
            f"{names.get('gap')} поверхност(ь/ей) · сменили бы форму "
            f"{names.get('would_move_total')} пар(ы); {names.get('reason')}")
        outcomes = names.get("by_outcome") or {}
        out.append(
            f"[ИМЕНА] разрешено единственным файлом {outcomes.get(NAME_RESOLVED)} · "
            f"имя у многих {outcomes.get(NAME_AMBIGUOUS)} · имени в дереве нет "
            f"{outcomes.get(NAME_ABSENT)}; разобрано файлов дерева "
            f"{names.get('files_read')}, нечитаемых "
            f"{len(names.get('files_unreadable') or [])}")
        out.append(
            f"[ШИРОКИЕ АБЗАЦЫ] мера пути отбросила как широкие "
            f"{names.get('paragraphs_wide_with_authority')} из "
            f"{names.get('paragraphs_authority')} абзац(ев) с языком права "
            f"изменения — это и есть вторая половина зазора: не «имя вместо "
            f"пути», а абзац, до содержимого которого мера пути не доходит")
        ctl_p = names.get("control_paragraphs") or 0
        ctl_r = names.get("control_resolved_single") or 0
        auth_p = names.get("paragraphs_authority") or 0
        auth_r = outcomes.get(NAME_RESOLVED) or 0
        if ctl_p and auth_p:
            out.append(
                f"[ЧАСТОТА ОШИБКИ] контроль на абзацах БЕЗ языка права "
                f"изменения: {ctl_r} разрешённых имён на {ctl_p} абзац(ев) = "
                f"{ctl_r / ctl_p:.3f}/абзац против {auth_r / auth_p:.3f}/абзац "
                f"у отобранных — отбор обогащает в "
                f"{(auth_r / auth_p) / (ctl_r / ctl_p):.1f} раз(а), и пять "
                f"находок не есть базовая частота обратных кавычек")
        else:
            out.append(
                "[ЧАСТОТА ОШИБКИ] НЕ ИЗМЕРЕНА: контрольных абзацев нет, и "
                "обогащение отбора подтвердить нечем")
        for row in (names.get("surfaces") or []):
            where = (row.get("declared_by") or [{}])[0]
            if row.get("kind") != SURFACE_SHELF:
                out.append(f"[ИМЕНЕМ · НЕ ШКАФ] {row['path']} — {row.get('kind')}: "
                           f"{row.get('reason', 'причина не записана')}")
                continue
            out.append(
                f"[ИМЕНЕМ · ШКАФ] {row['path']} — объявлен как "
                f"`{where.get('named_as')}` в {where.get('text')}:"
                f"{where.get('line')} · чисел {row.get('numbers')} · называет "
                f"находок {row.get('matches')} · сменили бы форму "
                f"{row.get('would_move')} · спрашивается сегодня: "
                f"{'да' if row.get('asked_today') else 'НЕТ'}")
            if row.get("would_move_names"):
                out.append(f"[ИМЕНЕМ · имена] "
                           f"{', '.join(row['would_move_names'][:8])}")
        if names.get("already_declared_by_path"):
            out.append(f"[ИМЕНЕМ, УЖЕ ИЗВЕСТНО ПО ПУТИ] "
                       f"{', '.join(names['already_declared_by_path'][:6])} — "
                       f"к зазору не относятся")
        for blind in (names.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    wide = observed(doc, "wide_paragraph_channel", kind=dict)
    if wide is None:
        out.append("[ШИРОКИЙ АБЗАЦ] НЕ ИЗМЕРЕН — перепись собрана без "
                   "координаты потолка зазора (заказ G57 п. 1)")
    elif wide.get("verdict") == WIDE_CHANNEL_UNMEASURED:
        out.append(f"[ШИРОКИЙ АБЗАЦ] {WIDE_CHANNEL_UNMEASURED}: "
                   f"{wide.get('reason')}")
    else:
        out.append(
            f"[ШИРОКИЙ АБЗАЦ] {wide.get('verdict')} · абзацев "
            f"{wide.get('wide_authority_paragraphs')} · упоминаний пути "
            f"{wide.get('mentions')} · различных путей "
            f"{wide.get('distinct_paths')} (разрешилось "
            f"{wide.get('resolved_paths')}) · НОВЫХ к обоим прежним каналам "
            f"{wide.get('gap')} (шкафов {wide.get('shelves')}, сторожей "
            f"{wide.get('guards')}) · сменили бы форму "
            f"{wide.get('would_move_total')} пар(ы); {wide.get('reason')}")
        reasons = wide.get("wide_by_reason") or {}
        out.append(
            f"[ШИРОКИЙ ПОЧЕМУ] абзац длиннее предела "
            f"{reasons.get(WIDE_BY_LINES)} · строка длиннее предела "
            f"{reasons.get(WIDE_BY_LINE_LENGTH)} · оба "
            f"{reasons.get(WIDE_BY_BOTH)} — предел строки и предел абзаца "
            f"защищают от РАЗНОГО, и одно число о сумме ответило бы не на тот "
            f"вопрос")
        by_reason_move = wide.get("would_move_by_wide_reason") or {}
        by_reason_surf = wide.get("surfaces_by_wide_reason") or {}
        out.append(
            f"[КАКОЙ ПРЕДЕЛ ДЕРЖИТ ЦЕНУ] сменили бы форму: предел АБЗАЦА "
            f"{by_reason_move.get(WIDE_BY_LINES)} пар(ы) при "
            f"{by_reason_surf.get(WIDE_BY_LINES)} поверхност(и/ях) · предел "
            f"СТРОКИ {by_reason_move.get(WIDE_BY_LINE_LENGTH)} при "
            f"{by_reason_surf.get(WIDE_BY_LINE_LENGTH)} · оба "
            f"{by_reason_move.get(WIDE_BY_BOTH)} при "
            f"{by_reason_surf.get(WIDE_BY_BOTH)}. Заказ назвал "
            f"MAX_DECLARING_PARAGRAPH — посылка проверена, а не повторена")
        ratio = wide.get("enrichment_wide")
        narrow = wide.get("enrichment_narrow")
        if ratio is None:
            out.append(f"[ЧАСТОТА ОШИБКИ · ШИРОКИЙ] НЕ ИЗМЕРЕНА: "
                       f"{wide.get('enrichment_wide_reason')}")
        else:
            out.append(
                f"[ЧАСТОТА ОШИБКИ · ШИРОКИЙ] отбор «язык права изменения» "
                f"сгущает упоминания пути в {ratio:.1f} раз(а): "
                f"{wide.get('wide_authority_mentions')} на "
                f"{wide.get('wide_authority_paragraphs')} абзац(ев) против "
                f"{wide.get('wide_control_mentions')} на "
                f"{wide.get('wide_control_paragraphs')} контрольных")
        if narrow is None:
            out.append(f"[ЧАСТОТА ОШИБКИ · УЗКИЙ] НЕ ИЗМЕРЕНА: "
                       f"{wide.get('enrichment_narrow_reason')}")
        else:
            out.append(
                f"[ЧАСТОТА ОШИБКИ · УЗКИЙ] тот же отбор на абзацах, которые "
                f"мера пути ЧИТАЕТ, сгущает в {narrow:.1f} раз(а): "
                f"{wide.get('narrow_authority_mentions')} на "
                f"{wide.get('narrow_authority_paragraphs')} против "
                f"{wide.get('narrow_control_mentions')} на "
                f"{wide.get('narrow_control_paragraphs')} контрольных")
        out.append(
            f"[ЧАСТОТА ОШИБКИ · ПОСЛЕДСТВИЕ] контроль на ТОЙ ЖЕ ширине без "
            f"языка права изменения: шкафов {wide.get('control_shelves')} · "
            f"называют находок {wide.get('control_matches')} · сменили бы "
            f"форму {wide.get('control_would_move')} пар(ы) — против "
            f"{wide.get('would_move_total')} у отобранных")
        if ratio is not None:
            out.append(
                f"[ДВЕ ОСИ ОБОГАЩЕНИЯ, И ОНИ СПОРЯТ] по УПОМИНАНИЯМ отбор "
                f"сгущает в {ratio:.1f} раз(а) — сигнала почти нет; по "
                f"ПОСЛЕДСТВИЮ — {wide.get('would_move_total')} против "
                f"{wide.get('control_would_move')}. Вопрос заказа о "
                f"ПОСЛЕДСТВИИ, и ответ на него нельзя брать с первой оси: "
                f"широкий абзац называет пути и так, но шкафы, которые кусают, "
                f"стоят именно у языка права изменения")
        if ratio is not None and narrow is not None:
            out.append(
                f"[ПРЕДЕЛ НЕ ОСЛАБЛЕН] MAX_DECLARING_PARAGRAPH остаётся "
                f"{MAX_DECLARING_PARAGRAPH}: по упоминаниям широкий абзац "
                f"обогащается в {ratio:.1f} раз(а) против {narrow:.1f} у "
                f"узкого, то есть «путь рядом с фразой» там и правда не улика. "
                f"Эта координата не доливает найденное в население "
                f"объявленных поверхностей — она называет ПОТОЛОК зазора и "
                f"его цену в парах")
        for row in (wide.get("surfaces") or []):
            where = (row.get("declared_by") or [{}])[0]
            if row.get("kind") != SURFACE_SHELF:
                out.append(f"[ШИРОКИЙ · НЕ ШКАФ] {row['path']} — "
                           f"{row.get('kind')}: "
                           f"{row.get('reason', 'причина не записана')}")
                continue
            out.append(
                f"[ШИРОКИЙ · ШКАФ] {row['path']} — назван в "
                f"{where.get('text')}:{where.get('line')} (абзац "
                f"{where.get('paragraph_lines')} строк) · чисел "
                f"{row.get('numbers')} · называет находок "
                f"{row.get('matches')} · сменили бы форму "
                f"{row.get('would_move')}")
        for row in (wide.get("already_known") or []):
            out.append(
                f"[ШИРОКИЙ, УЖЕ ИЗВЕСТЕН] {row['path']} — знает канал "
                f"{row['known_by']}; называет находок {row.get('matches')} — "
                f"к зазору не относится, но укус мерит")
        for blind in (wide.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    form = observed(doc, "table_form_census", kind=dict)
    if form is None:
        out.append("[ФОРМА ТАБЛИЦЫ] НЕ ИЗМЕРЕНА — перепись собрана без "
                   "координаты формы (заказ G58 п. 1)")
    elif form.get("verdict") == TABLE_FORM_UNMEASURED:
        out.append(f"[ФОРМА ТАБЛИЦЫ] {TABLE_FORM_UNMEASURED}: "
                   f"{form.get('reason')}")
    else:
        out.append(
            f"[ФОРМА ТАБЛИЦЫ] {form.get('verdict')} · в объявленном канале "
            f"{form.get('sample_form_long_line')} · в контроле "
            f"{form.get('control_form_long_line')}; {form.get('reason')}")
        # `or {}` здесь был бы ровно тем, что запрещает инв. #17: отсутствие
        # ключа стало бы пустой долей, цикл не напечатал бы ни строки, и
        # «не измерено» сделалось бы неотличимо от «нечего показать».
        shares = observed(form, "table_share_of_wide_authority", kind=dict)
        if shares is None:
            out.append("[ФОРМА · ДОЛЯ] НЕ ИЗМЕРЕНА — координата собрана без "
                       "долей по каналам")
            shares = {}
        for name in _TABLE_CHANNELS:
            cell = observed(shares, name, kind=dict)
            if cell is None:
                out.append(f"[ФОРМА · ДОЛЯ] {name}: НЕ ИЗМЕРЕНА — канал в "
                           f"координате не назван")
                continue
            share = cell.get("share")
            printed = ("НЕ ИЗМЕРЕНА" if share is None
                       else f"{share * 100:.1f} %")
            out.append(
                f"[ФОРМА · ДОЛЯ] {name}: таблиц среди широких абзацев с "
                f"языком права изменения {cell.get('form_any_reason')} из "
                f"{cell.get('wide_authority_paragraphs')} = {printed}"
                + ("" if share is not None
                   else f" ({cell.get('share_reason')})"))
        channels = observed(form, "channels", kind=dict)
        if channels is None:
            out.append("[ФОРМА · ГДЕ] НЕ ИЗМЕРЕНО — координата собрана без "
                       "разбивки по каналам")
            channels = {}
        for name in _TABLE_CHANNELS:
            channel = observed(channels, name, kind=dict)
            if channel is None:
                continue
            for hit in (channel.get("long_line_hits") or [])[:6]:
                out.append(
                    f"[ФОРМА · ГДЕ] {name}: {hit.get('text')}:"
                    f"{hit.get('line')} — строк {hit.get('lines')}, "
                    f"длиннейшая {hit.get('longest_line')}")
            if channel.get("registry_hits"):
                out.append(
                    f"[ФОРМА · РЕЕСТР] {name}: {channel['registry_hits']} "
                    f"попадан(ие/ий) в объявленный реестр — считается "
                    f"отдельно и в утверждение о репозитории не входит")
        for blind in (form.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    # Секция вынесена ЗА блок формы намеренно: вложенная внутрь `else`, она
    # молчала бы у любого дерева, где координата формы не измерена, — ровно
    # та ошибка размещения, которую соседний сторож поймал у #655.
    channel = observed(doc, "out_of_channel_numbers", kind=dict)
    if channel is None:
        out.append("[ЧИСЛА ВНЕ КАНАЛА] НЕ ИЗМЕРЕНЫ — перепись собрана без "
                   "координаты (заказ G59 п. 2)")
    elif channel.get("verdict") == OUT_CHANNEL_UNMEASURED:
        out.append(f"[ЧИСЛА ВНЕ КАНАЛА] {OUT_CHANNEL_UNMEASURED}: "
                   f"{channel.get('reason')}")
    else:
        total = observed(channel, "numbers_total", kind=int)
        out.append(
            f"[ЧИСЛА ВНЕ КАНАЛА] {channel.get('verdict')} · таблиц "
            f"{channel.get('tables_read')} из {channel.get('tables')} · чисел "
            + ("НЕ ИЗМЕРЕНО" if total is None else str(total))
            + f" · совпало по величине {channel.get('matched_value')} · "
            f"НАЗВАНО порогом {channel.get('named')}; {channel.get('reason')}")
        evidence = observed(channel, "by_evidence", kind=dict)
        if evidence is None:
            out.append("[ЧИСЛА · СВИДЕТЕЛЬСТВО] НЕ ИЗМЕРЕНО — координата "
                       "собрана без разбивки по каналам")
        else:
            for name in _EV_ALL:
                cell = observed(evidence, name, kind=int)
                out.append(
                    f"[ЧИСЛА · СВИДЕТЕЛЬСТВО] {name}: "
                    + ("НЕ ИЗМЕРЕНО — канал в координате не назван"
                       if cell is None else str(cell)))
        reading = observed(channel, "by_reading", kind=dict)
        if reading is None:
            out.append("[ЧИСЛА · ПРОЧТЕНИЕ] НЕ ИЗМЕРЕНО — координата собрана "
                       "без прочтений")
        else:
            fraction = observed(reading, READ_AS_FRACTION, kind=int)
            out.append(
                f"[ЧИСЛА · ПРОЧТЕНИЕ] как написано "
                f"{observed(reading, READ_AS_WRITTEN, kind=int)} · как доля "
                + ("НЕ ИЗМЕРЕНО" if fraction is None else str(fraction))
                + " — второе прочтение существует потому, что один порог "
                "живёт у двух поверхностей в РАЗНЫХ единицах")
        rate = observed(channel, "enrichment", kind=float)
        out.append(
            "[ЧИСЛА · ЧАСТОТА ОШИБКИ] обогащение имени над голой величиной: "
            + (f"x{rate:.2f}" if rate is not None
               else f"НЕ ИЗМЕРЕНО — {channel.get('enrichment_reason')}"))
        for pair in (channel.get("pairs") or []):
            if pair.get("evidence") not in _EV_NAMED:
                continue
            out.append(
                f"[ЧИСЛА · НАЗВАНО] {pair.get('text')}:{pair.get('line')} "
                f"[{pair.get('number')}] -> {pair.get('threshold')} "
                f"({pair.get('evidence')}, {pair.get('reading')}) — "
                f"{pair.get('quote')}")
        for row in (channel.get("unreadable") or []):
            out.append(f"[ЧИСЛА · НЕ ПРОЧИТАНО] {row.get('text')}: "
                       f"{row.get('reason')}")
        for blind in (channel.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    # Секция вынесена ЗА блок чисел вне канала намеренно и закреплена тестом:
    # вложенная внутрь его `else`, она молчала бы у каждого дерева, где та
    # координата не измерена, — ошибка размещения, найденная у #655.
    reach = observed(doc, "bilingual_reach", kind=dict)
    if reach is None:
        out.append("[ДВУЯЗЫЧИЕ] НЕ ИЗМЕРЕНО — перепись собрана без координаты "
                   "(заказ G60 пп. 1–2)")
    elif reach.get("verdict") in (BILINGUAL_UNMEASURED, BILINGUAL_NOTHING_TO_ASK):
        out.append(f"[ДВУЯЗЫЧИЕ] {reach.get('verdict')}: {reach.get('reason')}")
    else:
        out.append(f"[ДВУЯЗЫЧИЕ] {reach.get('verdict')} · {reach.get('reason')}")
        witnesses = observed(reach, "witnesses", kind=dict) or {}
        subject = observed(witnesses, WITNESS_SUBJECT, kind=dict)
        if subject is None:
            out.append("[ДВУЯЗЫЧИЕ · ПРЕДМЕТ] НЕ ИЗМЕРЕНО — свидетель в "
                       "координате не назван")
        else:
            out.append(
                f"[ДВУЯЗЫЧИЕ · ПРЕДМЕТ] пар прочитано {subject.get('pairs_read')} "
                f"· сменили вердикт {subject.get('changed')} · карта применима к "
                f"{subject.get('askable')} из {subject.get('modules')} модулей "
                f"(задета у {subject.get('token_overlap')}) · по-русски написаны "
                f"{subject.get('cyrillic_sides')} — ноль без этих знаменателей "
                f"был бы утверждением о приборе")
            for row in (subject.get("changed_rows") or [])[:max_rows]:
                out.append(f"[ДВУЯЗЫЧИЕ · ПРЕДМЕТ · СДВИГ] {row.get('name')} = "
                           f"{row.get('value')} — {'; '.join(row.get('witness') or [])}")
        channel = observed(witnesses, WITNESS_NAME_CHANNEL, kind=dict)
        if channel is None:
            out.append("[ДВУЯЗЫЧИЕ · ИМЯ] НЕ ИЗМЕРЕНО — канал в координате не назван")
        else:
            rate = observed(channel, "enrichment", kind=float)
            out.append(
                f"[ДВУЯЗЫЧИЕ · ИМЯ] разрешимых имён {channel.get('candidates')} · "
                f"названо токенами {channel.get('authority_raw')} на "
                f"{channel.get('authority_paragraphs')} объявлениях · величиной "
                f"подтверждено {channel.get('authority_corroborated')}; контроль "
                f"{channel.get('control_raw')} на {channel.get('control_paragraphs')} "
                f"абзацах (подтверждено {channel.get('control_corroborated')}) · "
                f"обогащение "
                + (f"x{rate:.2f}" if rate is not None
                   else f"НЕ ИЗМЕРЕНО — {channel.get('enrichment_reason')}"))
            for pair in (channel.get("pairs") or []):
                out.append(
                    f"[ДВУЯЗЫЧИЕ · ИМЯ · НАЗВАНО] {pair.get('text')}:"
                    f"{pair.get('line')} -> {pair.get('resolved')} "
                    f"`{pair.get('named_as')}` = {pair.get('value')} — "
                    f"{pair.get('quote')}")
        coverage = observed(reach, "map_coverage", kind=dict)
        if coverage is None or coverage.get("status") != "MEASURED":
            out.append("[ДВУЯЗЫЧИЕ · КАРТА] НЕ ИЗМЕРЕНА — "
                       + str((coverage or {}).get("reason")
                             or "полнота карты в координате не названа"))
        else:
            out.append(
                f"[ДВУЯЗЫЧИЕ · КАРТА] порогов переписи {coverage.get('thresholds')} "
                f"· закрыты целиком {coverage.get('fully_covered')} · частично "
                f"{coverage.get('partly_covered')} · не закрыты вовсе "
                f"{coverage.get('not_covered')}; различающих токенов без русского "
                f"соответствия {coverage.get('tokens_without_russian')} из "
                f"{coverage.get('tokens')}: "
                + ", ".join((coverage.get("missing_tokens") or [])[:12]))
        for blind in (reach.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    # Секция стои́т ЗА блоком двуязычия на уровне тела функции, а не внутри
    # его `else`: вложенная туда, она молчала бы у каждого дерева, где карта
    # синонимов пуста, — то есть ровно там, где о точности спрашивать важнее
    # всего. Ошибка размещения найдена у #655 и закреплена тестом.
    precision = observed(doc, "bilingual_name_precision", kind=dict)
    if precision is None:
        out.append("[ТОЧНОСТЬ ИМЕНИ] НЕ ИЗМЕРЕНА — перепись собрана без "
                   "координаты (заказ G61 п. 1)")
    elif precision.get("status") != "MEASURED":
        out.append(f"[ТОЧНОСТЬ ИМЕНИ] НЕ ИЗМЕРЕНА: {precision.get('reason')}")
    else:
        out.append(f"[ТОЧНОСТЬ ИМЕНИ · ПРАВИЛО] {precision.get('rule')}")
        sides = observed(precision, "sides", kind=dict) or {}
        for side in ("authority", "control"):
            tally = observed(sides, side, kind=dict)
            if tally is None:
                out.append(f"[ТОЧНОСТЬ ИМЕНИ · {side}] НЕ ИЗМЕРЕНО — "
                           f"срабатываний этой стороны в населении нет")
                continue
            share = observed(tally, "false_share", kind=float)
            out.append(
                f"[ТОЧНОСТЬ ИМЕНИ · {side}] размечено {tally.get('labelled')} · "
                f"настоящих {tally.get(LABEL_GENUINE)} · ложных "
                f"{tally.get(LABEL_ARTEFACT)} · не решено "
                f"{tally.get(LABEL_UNDECIDED)} · доля ложных "
                + ("НЕ ИЗМЕРЕНА" if share is None else f"{share:.0%}")
                + f"; цена области (пункт против строки) {tally.get('wrap_cost')}")
            sizes = observed(tally, "by_token_count", kind=dict) or {}
            out.append(
                f"[ТОЧНОСТЬ ИМЕНИ · {side} · ТОКЕНОВ В ИМЕНИ] "
                + " · ".join(
                    f"{size}: настоящих {cell.get(LABEL_GENUINE)}, ложных "
                    f"{cell.get(LABEL_ARTEFACT)}, не решено {cell.get(LABEL_UNDECIDED)}"
                    for size, cell in sorted(sizes.items())))
        interval = observed(precision, "truth_interval", kind=dict)
        if interval is None:
            out.append("[ТОЧНОСТЬ ИМЕНИ · ИНТЕРВАЛ] НЕ ИЗМЕРЕН — размеченного "
                       "населения стороны объявления нет")
        else:
            out.append(
                f"[ТОЧНОСТЬ ИМЕНИ · ИНТЕРВАЛ] точность канала лежит в "
                f"[{interval['lower']:.1%}, {interval['upper']:.1%}] при "
                f"знаменателе {interval['denominator']} — ширину держит "
                f"`UNDECIDED`, и это ОТВЕТ заказа, а не его отсутствие: "
                f"независимого свидетеля хватило не на всех")
        enrich = observed(precision, "enrichment", kind=dict) or {}
        for key, what in (("per_paragraph", "на абзац объявления"),
                          ("per_hit", "на срабатывание канала")):
            rate = observed(enrich, key, kind=float)
            out.append(
                f"[ТОЧНОСТЬ ИМЕНИ · ОБОГАЩЕНИЕ {what}] "
                + (f"x{rate:.2f}" if rate is not None
                   else f"НЕ ИЗМЕРЕНО — {enrich.get(key + '_reason')}"))
        for row in (precision.get("rows") or []):
            if row.get("side") != "authority" or row.get("label") != LABEL_GENUINE:
                continue
            out.append(
                f"[ТОЧНОСТЬ ИМЕНИ · НАСТОЯЩАЯ] {row.get('text')}:"
                f"{row.get('w1_colocated_item_line')} -> {row.get('resolved')} "
                f"`{row.get('named_as')}` = {row.get('value')} "
                f"(модуль назван: {row.get('w2_subject_named')}, величина: "
                f"{row.get('w3_value_named')})")
        for row in (precision.get("unresolved") or []):
            out.append(f"[ТОЧНОСТЬ ИМЕНИ · НЕ РАЗМЕЧЕНО] {row.get('text')} "
                       f"`{row.get('named_as')}`: {row.get('reason')}")
        for blind in (precision.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    # Секция стои́т на уровне тела функции, а не внутри `else` соседней
    # координаты: вложенная туда, она молчала бы у каждого дерева, где
    # разметка не измерена, — то есть там, где цена сужения и так неизвестна,
    # но сказать об этом надо громко. Та же ошибка размещения найдена у #655.
    depth = observed(doc, "token_depth_price", kind=dict)
    if depth is None:
        out.append("[ЦЕНА ДВУХ ТОКЕНОВ] НЕ ИЗМЕРЕНА — перепись собрана без "
                   "координаты (заказ G62 п. 1)")
    elif depth.get("status") != "MEASURED":
        out.append(f"[ЦЕНА ДВУХ ТОКЕНОВ] НЕ ИЗМЕРЕНА: {depth.get('reason')}")
    else:
        out.append(
            f"[ЦЕНА ДВУХ ТОКЕНОВ · ПРАВИЛО] глубина {depth.get('depth')} · "
            f"порог введён: {'да' if depth.get('applied') else 'НЕТ'} · "
            f"{depth.get('rule')}")
        depth_sides = observed(depth, "sides", kind=dict) or {}
        for side in ("authority", "control"):
            tally = observed(depth_sides, side, kind=dict)
            if tally is None:
                out.append(f"[ЦЕНА ДВУХ ТОКЕНОВ · {side}] НЕ ИЗМЕРЕНО — "
                           f"срабатываний этой стороны в разметке нет")
                continue
            was = observed(tally, "before", kind=dict) or {}
            flt = observed(tally, "as_filter", kind=dict) or {}
            survive = observed(flt, "survive", kind=dict) or {}
            lost = observed(flt, "lost", kind=dict) or {}
            lost_total = sum(lost.get(key, 0) for key in
                             (LABEL_GENUINE, LABEL_ARTEFACT, LABEL_UNDECIDED))
            out.append(
                f"[ЦЕНА ДВУХ ТОКЕНОВ · {side} · СУЖЕНИЕ] было "
                f"{was.get('labelled')} срабатываний, исчезает {lost_total}, "
                f"остаётся {survive.get('labelled')}; ПОТЕРЯНО настоящих "
                f"{lost.get(LABEL_GENUINE)} из {was.get(LABEL_GENUINE)} · "
                f"ложных снято {lost.get(LABEL_ARTEFACT)} из "
                f"{was.get(LABEL_ARTEFACT)} · не решённых удалено "
                f"{lost.get(LABEL_UNDECIDED)}, РЕШЕНО "
                f"{flt.get('resolved_undecided')}")
            for key, what in (("before", "до"), ("as_filter", "после сужения")):
                cell = (survive if key == "as_filter"
                        else observed(tally, key, kind=dict) or {})
                share = observed(cell, "false_share", kind=float)
                span = observed(cell, "interval", kind=dict)
                out.append(
                    f"[ЦЕНА ДВУХ ТОКЕНОВ · {side} · {what}] доля ложных "
                    + ("НЕ ИЗМЕРЕНА" if share is None else f"{share:.0%}")
                    + " · интервал "
                    + ("НЕ ИЗМЕРЕН" if span is None
                       else f"[{span['lower']:.1%}, {span['upper']:.1%}] при "
                            f"знаменателе {span['denominator']}"))
            wit = observed(tally, "as_witness", kind=dict) or {}
            out.append(
                f"[ЦЕНА ДВУХ ТОКЕНОВ · {side} · КАК СВИДЕТЕЛЬ] решено "
                f"`UNDECIDED` {wit.get('resolved_undecided')} из "
                f"{was.get(LABEL_UNDECIDED)}; настоящих стало "
                f"{wit.get(LABEL_GENUINE)}, население не убывает")
        price = observed(depth, "price_in_pairs", kind=dict)
        if price is None or price.get("status") != "MEASURED":
            out.append("[ЦЕНА ДВУХ ТОКЕНОВ · В ПАРАХ] НЕ ИЗМЕРЕНА: "
                       + str((price or {}).get("reason")))
        else:
            lost_pairs = price.get("lost") or []
            out.append(
                f"[ЦЕНА ДВУХ ТОКЕНОВ · В ПАРАХ] подтверждённых величиной "
                f"{price.get('corroborated')} · ТЕРЯЕТСЯ {len(lost_pairs)} · "
                f"остаётся {len(price.get('kept') or [])} · вердикт неоднозначен "
                f"у {len(price.get('unmatched') or [])}")
            for pair in lost_pairs:
                out.append(
                    f"[ЦЕНА ДВУХ ТОКЕНОВ · ПОТЕРЯННАЯ ПАРА] {pair.get('text')} "
                    f"-> {pair.get('resolved')} `{pair.get('named_as')}` = "
                    f"{pair.get('value')} (различающих токенов "
                    f"{pair.get('token_count')})")
            for pair in (price.get("unmatched") or []):
                out.append(
                    f"[ЦЕНА ДВУХ ТОКЕНОВ · ПАРА НЕ РАЗОБРАНА] "
                    f"{pair.get('text')} `{pair.get('named_as')}`: "
                    f"{pair.get('reason')}")
        ind = observed(depth, "independence", kind=dict) or {}
        out.append(
            f"[ЦЕНА ДВУХ ТОКЕНОВ · ТРЕТИЙ СВИДЕТЕЛЬ] {ind.get('verdict')} — "
            f"{ind.get('reason')}"
            + (f"; имён в двух и более абзацах "
               f"{ind.get('names_in_two_paragraphs')}, из них вердикт меняется "
               f"у {ind.get('names_whose_verdict_varies')}"
               if ind.get("verdict") != DEPTH_INDEPENDENCE_UNMEASURED else ""))
        for row in (depth.get("unreadable") or []):
            out.append(f"[ЦЕНА ДВУХ ТОКЕНОВ · НЕ РАЗОБРАНО] {row.get('text')} "
                       f"`{row.get('named_as')}`: {row.get('reason')}")
        for blind in (depth.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    # Секция — на уровне тела функции, а не внутри `else` соседней координаты:
    # вложенная туда, она молчала бы у каждого дерева, где разметка не
    # измерена, то есть ровно там, где о кандидатах и надо сказать громко.
    wit = observed(doc, "paragraph_witness_price", kind=dict)
    if wit is None:
        out.append("[СВИДЕТЕЛИ АБЗАЦА] НЕ ИЗМЕРЕНЫ — перепись собрана без "
                   "координаты (заказ G63 п. 1)")
    elif wit.get("status") != "MEASURED":
        out.append(f"[СВИДЕТЕЛИ АБЗАЦА] НЕ ИЗМЕРЕНЫ: {wit.get('reason')}")
    else:
        out.append(
            f"[СВИДЕТЕЛИ АБЗАЦА · ПРАВИЛО] кандидатов "
            f"{len(wit.get('declared') or [])} · порог на частоту ошибки "
            f"введён: {'да' if wit.get('applied') else 'НЕТ'} · "
            f"{wit.get('rule')}")
        out.append(
            f"[СВИДЕТЕЛИ АБЗАЦА · НАСЕЛЕНИЕ] неразрешённых у стороны "
            f"объявлений {wit.get('undecided_population')} в "
            f"{wit.get('undecided_paragraphs')} разных абзац(ах) · "
            f"контрольных срабатываний с W1 {wit.get('control_population')} в "
            f"{wit.get('control_paragraphs')} абзац(ах) · `ARTEFACT` "
            f"не спрашивается: "
            + str(observed(wit, "artefact_skipped", kind=dict) or {}))
        cands = observed(wit, "candidates", kind=dict) or {}
        for key, cand in cands.items():
            got = observed(cand, "resolves_undecided", kind=dict) or {}
            err = observed(cand, "error_rate_on_control", kind=dict) or {}
            share = observed(got, "share", kind=float)
            rate = observed(err, "share", kind=float)
            out.append(
                f"[СВИДЕТЕЛЬ · {key}] "
                + ("ДЕЙСТВУЮЩИЙ" if cand.get("incumbent") else "кандидат")
                + f" · читает: {cand.get('reads')} · решает `UNDECIDED` "
                + ("НЕ ИЗМЕРЕНО" if share is None
                   else f"{got.get('fired')} из {got.get('askable')} "
                        f"({share:.0%}) в {got.get('paragraphs')} абзац(ах)")
                + " · частота ошибки на контроле "
                + ("НЕ ИЗМЕРЕНА" if rate is None
                   else f"{err.get('fired')} из {err.get('askable')} "
                        f"({rate:.0%}) в {err.get('paragraphs')} абзац(ах)")
                + " · в правило допустим: "
                + ("да" if cand.get("admissible_to_rule") else "НЕТ"))
            if got.get("unaskable") or err.get("unaskable"):
                out.append(
                    f"[СВИДЕТЕЛЬ · {key} · НЕ СПРОШЕН] неразрешённых "
                    f"{got.get('unaskable')}, контрольных "
                    f"{err.get('unaskable')} — причины: "
                    + "; ".join(f"{why} ×{n}" for why, n in
                                (cand.get("unaskable_reasons") or {}).items()))
            if cand.get("structural_zero"):
                out.append(f"[СВИДЕТЕЛЬ · {key} · НОЛЬ ПО ПОСТРОЕНИЮ] "
                           f"{cand.get('structural_zero')}")
            for row in (cand.get("contradictions") or []):
                out.append(
                    f"[СВИДЕТЕЛЬ · {key} · ПРОТИВОРЕЧИЕ] действующий свидетель "
                    f"сработал на `UNDECIDED` {row.get('text')} "
                    f"`{row.get('named_as')}` — разметка и эта мера спорят, и "
                    f"спор обязан быть разобран, а не усреднён")
            ind = observed(cand, "independence", kind=dict) or {}
            out.append(
                f"[СВИДЕТЕЛЬ · {key} · ЧИТАЕТ ЛИ АБЗАЦ] {ind.get('verdict')} — "
                f"{cand.get('independence_reading')}; охват "
                + str(cand.get("reach") or {}))
            for row in (cand.get("examples") or []):
                out.append(
                    f"[СВИДЕТЕЛЬ · {key} · РЕШЁННОЕ] {row.get('text')}:"
                    f"{row.get('block_start')} -> {row.get('resolved')} "
                    f"`{row.get('named_as')}` = {row.get('value')}")
        for row in (wit.get("unreadable") or []):
            out.append(f"[СВИДЕТЕЛИ АБЗАЦА · НЕ РАЗОБРАНО] {row.get('text')} "
                       f"`{row.get('named_as')}`: {row.get('reason')}")
        for row in (wit.get("unresolved") or []):
            out.append(f"[СВИДЕТЕЛИ АБЗАЦА · АБЗАЦ НЕ РАЗРЕШЁН] "
                       f"{row.get('text')} `{row.get('named_as')}`: "
                       f"{row.get('reason')}")
        for blind in (wit.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    # Секция — на уровне тела функции по той же причине, что и соседняя:
    # вложенная в `else` чужой координаты, она молчала бы ровно там, где о
    # цене и надо сказать громко.
    adm = observed(doc, "witness_admission_price", kind=dict)
    if adm is None:
        out.append("[ЦЕНА ДОПУСКА] НЕ ИЗМЕРЕНА — перепись собрана без "
                   "координаты (заказ G64 п. 1)")
    elif adm.get("status") != "MEASURED":
        out.append(f"[ЦЕНА ДОПУСКА] НЕ ИЗМЕРЕНА: {adm.get('reason')}")
    else:
        out.append(
            f"[ЦЕНА ДОПУСКА · ПРАВИЛО] порог введён: "
            f"{'да' if adm.get('applied') else 'НЕТ'} · {adm.get('rule')}")
        today = observed(adm, "pairs_today", kind=dict) or {}
        if today.get("status") != "MEASURED":
            out.append(f"[ЦЕНА ДОПУСКА · КНИГИ СЕГОДНЯ] НЕ ИЗМЕРЕНО: "
                       f"{today.get('reason')}")
        else:
            out.append(
                f"[ЦЕНА ДОПУСКА · КНИГИ СЕГОДНЯ] пар {today.get('pairs')} из "
                f"{today.get('paragraphs')} абзац(ев) · с меткой `GENUINE` "
                f"совпадают {today.get('genuine_overlap')} — совпадение ЧИСЕЛ "
                f"тождеством множеств не является, поэтому меряется "
                f"пересечение"
                + (f" · пара без `GENUINE`: {len(today.get('pairs_not_genuine') or [])}"
                   f" · `GENUINE` без пары: {len(today.get('genuine_not_pairs') or [])}"))
        for key, cand in (observed(adm, "candidates", kind=dict) or {}).items():
            prov = observed(cand, "pair_provenance", kind=dict) or {}
            sides = observed(cand, "sides", kind=dict) or {}
            auth = observed(sides, "authority", kind=dict) or {}
            ctl = observed(sides, "control", kind=dict) or {}
            out.append(
                f"[ЦЕНА ДОПУСКА · {key}] "
                + ("ДЕЙСТВУЮЩИЙ" if cand.get("incumbent") else "кандидат")
                + f" · {cand.get('admitted_rule')} · пар прибывает "
                + ("НЕ ИЗМЕРЕНО" if prov.get("status") != "MEASURED"
                   else f"{prov.get('added')} "
                        f"из {prov.get('paragraphs_added')} абзац(ев); из "
                        f"абзацев, уже плативших книгам: "
                        f"{prov.get('from_paragraph_already_paying')}; "
                        f"молчавших до сих пор: "
                        f"{prov.get('from_paragraph_silent_until_now')} в "
                        f"{prov.get('paragraphs_new_to_books')} абзац(ах))")
                + f" · на КОНТРОЛЕ прибывает {ctl.get('added')} — ложных ПО "
                  f"ПОСТРОЕНИЮ")
            for side_name, side in (("объявления", auth), ("контроль", ctl)):
                before = observed(side, "interval_before", kind=dict)
                after = observed(side, "interval_after", kind=dict)
                if side.get("status") != "MEASURED":
                    out.append(
                        f"[ЦЕНА ДОПУСКА · {key} · ИНТЕРВАЛ {side_name}] НЕ "
                        f"ИЗМЕРЕН: {side.get('reason') or 'стороны нет в разметке'}")
                    continue
                if before is None or after is None:
                    out.append(
                        f"[ЦЕНА ДОПУСКА · {key} · ИНТЕРВАЛ {side_name}] НЕ "
                        f"ИЗМЕРЕН: размеченного населения этой стороны нет")
                    continue
                out.append(
                    f"[ЦЕНА ДОПУСКА · {key} · ИНТЕРВАЛ {side_name}] "
                    f"[{before['lower']:.1%}, {before['upper']:.1%}] -> "
                    f"[{after['lower']:.1%}, {after['upper']:.1%}] при "
                    f"знаменателе {before['denominator']} · нижняя тронулась: "
                    + ("да" if side.get("lower_bound_moved") else "НЕТ")
                    + " · верхняя тронулась: "
                    + ("ДА — ПРОТИВОРЕЧИЕ ОПРЕДЕЛЕНИЮ"
                       if side.get("upper_bound_moved") else "нет"))
            if cand.get("structural_zero"):
                out.append(f"[ЦЕНА ДОПУСКА · {key} · НОЛЬ ПО ПОСТРОЕНИЮ] "
                           f"{cand.get('structural_zero')}")
            for item in (cand.get("contradicts_marking") or []):
                out.append(
                    f"[ЦЕНА ДОПУСКА · {key} · ПРОТИВОРЕЧИЕ] ДЕЙСТВУЮЩИЙ "
                    f"свидетель сработал на `UNDECIDED` {item.get('text')}:"
                    f"{item.get('block_start')} `{item.get('named_as')}` — "
                    f"ноль по построению ОПРОВЕРГНУТ замером, и спор обязан "
                    f"быть разобран, а не усреднён")
            for item in (cand.get("already_a_pair") or []):
                out.append(
                    f"[ЦЕНА ДОПУСКА · {key} · ПРОТИВОРЕЧИЕ] прибывшая пара "
                    f"{item.get('text')}:{item.get('block_start')} "
                    f"`{item.get('named_as')}` УЖЕ стои́т в парах канала — "
                    f"`UNDECIDED` означает «без W3», и спор обязан быть "
                    f"разобран, а не усреднён")
            for item in (cand.get("examples") or []):
                out.append(
                    f"[ЦЕНА ДОПУСКА · {key} · ПРИБЫЛО] {item.get('text')}:"
                    f"{item.get('block_start')} -> {item.get('resolved')} "
                    f"`{item.get('named_as')}` = {item.get('value')}")
        for item in (adm.get("unreadable") or []):
            out.append(f"[ЦЕНА ДОПУСКА · НЕ РАЗОБРАНО] {item.get('text')} "
                       f"`{item.get('named_as')}`: {item.get('reason')}")
        for item in (adm.get("unresolved") or []):
            out.append(f"[ЦЕНА ДОПУСКА · АБЗАЦ НЕ РАЗРЕШЁН] {item.get('text')} "
                       f"`{item.get('named_as')}`: {item.get('reason')}")
        for blind in (adm.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    # --- БАЗА ЧИТАТЕЛЯ (заказ G65 п. 1) ---------------------------------
    naming = observed(doc, "consumer_base_naming", kind=dict)
    if naming is None:
        out.append("[БАЗА ЧИТАТЕЛЯ] НЕ ИЗМЕРЕНА — перепись собрана без "
                   "разбора читателей")
    elif naming.get("status") != "MEASURED":
        out.append(f"[БАЗА ЧИТАТЕЛЯ] НЕ ИЗМЕРЕНА: {naming.get('reason')}")
    else:
        tally = naming.get("naming") or {}
        out.append(
            f"[БАЗА ЧИТАТЕЛЯ] читателей {len(naming.get('consumers') or [])} · "
            f"названо верно {tally.get(NAMING_SINGLE)} · "
            f"именем ДРУГОЙ базы {tally.get(NAMING_CROSS)} · "
            f"МНОГОЗНАЧНЫМ именем {tally.get(NAMING_AMBIGUOUS)} · "
            f"без имени {tally.get(NAMING_UNNAMED)}")
        for consumer in (naming.get("consumers") or []):
            if consumer.get("status") == CONSUMER_UNMEASURED:
                out.append(f"[БАЗА ЧИТАТЕЛЯ · {consumer.get('key')}] НЕ "
                           f"ИЗМЕРЕНО: {consumer.get('reason')}")
                continue
            if consumer.get("status") == CONSUMER_DELEGATES:
                out.append(
                    f"[БАЗА ЧИТАТЕЛЯ · {consumer.get('key')}] ДЕЛЕГИРУЕТ "
                    f"отрисовку производителю "
                    f"({', '.join(consumer.get('delegates_via') or [])}) — "
                    f"своей базы НЕТ, и это не ноль: он доносит до глаз чужую")
                continue
            if consumer.get("status") == CONSUMER_NO_READ:
                out.append(
                    f"[БАЗА ЧИТАТЕЛЯ · {consumer.get('key')}] НИ ОДНОЙ "
                    f"объявленной базы не читает и отрисовщик производителя не "
                    f"зовёт — объявлен читателем, а читает своё третье")
                continue
            out.append(
                f"[БАЗА ЧИТАТЕЛЯ · {consumer.get('key')}] базы "
                f"{', '.join(consumer.get('bases_read') or []) or '—'} · "
                f"чисел {len(consumer.get('numbers') or [])} · вне f-строки "
                f"{consumer.get('reads_outside_fstring')} (не разбирается)")
        for token, bases in sorted((naming.get("token_adjacency") or {}).items()):
            if len(bases) > 1:
                out.append(
                    f"[БАЗА ЧИТАТЕЛЯ · МНОГОЗНАЧНО] токен `{token}` стои́т "
                    f"рядом с {len(bases)} РАЗНЫМИ базами ({', '.join(bases)}) "
                    f"— читателю они этим словом не различаются ничем")
        for item in (naming.get("findings") or []):
            out.append(
                f"[БАЗА ЧИТАТЕЛЯ · {item.get('verdict')}] "
                f"{item.get('consumer')}:{item.get('line')} база "
                f"`{item.get('base')}` (координата `{item.get('coordinate')}`) "
                f"названа {item.get('tokens')}")
        carriers = naming.get("carries_ambiguity_by_delegation") or []
        if carriers:
            out.append(
                f"[БАЗА ЧИТАТЕЛЯ · ДОНОСИТ] {', '.join(carriers)} — своей базы "
                f"не имеет и потому несёт ЧУЖОЕ многозначное имя дальше: до "
                f"оркестратора доезжает именно эта строка")
        for blind in (naming.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    # --- РЕЕСТР ЧИТАТЕЛЕЙ (заказ G66 п. 1) ------------------------------
    completeness = observed(doc, "consumer_registry_completeness", kind=dict)
    if completeness is None:
        out.append("[РЕЕСТР ЧИТАТЕЛЕЙ] НЕ ИЗМЕРЕН — перепись собрана без "
                   "сведения двух населений")
    elif completeness.get("status") != "MEASURED":
        out.append(f"[РЕЕСТР ЧИТАТЕЛЕЙ] НЕ ИЗМЕРЕН: {completeness.get('reason')}")
    elif observed(completeness, "counts", kind=dict) is None:
        # Отсутствие счётчиков — ОТДЕЛЬНОЕ значение, а не пустой словарь
        # (инв. #17). Прежняя редакция писала `completeness.get("counts") or
        # {}`, и тогда «ключа нет» печаталось теми же `None`, что и «счётчик
        # равен None»: документ, объявивший себя измеренным без счётчиков,
        # выглядел бы измеренным с пустыми. Храповик
        # `test_absent_observation_ratchet` назвал эту строку новым членом
        # класса на предписанном прогоне — верно назвал.
        out.append("[РЕЕСТР ЧИТАТЕЛЕЙ] НЕ ИЗМЕРЕН: документ объявлен "
                   "MEASURED, но счётчиков в нём нет — это НЕ нулевые "
                   "счётчики и не пустое сведение")
    else:
        cnt = observed(completeness, "counts", kind=dict)
        out.append(
            f"[РЕЕСТР ЧИТАТЕЛЕЙ] объявлено {cnt.get('declared')} · мест "
            f"измерено {cnt.get('sites')} · названо {cnt.get('named')} · НЕ "
            f"названо {cnt.get('unnamed')} (кода {cnt.get('unnamed_code')}, "
            f"тестов {cnt.get('unnamed_test')}) · из них ПЕЧАТАЕТ числа "
            f"{cnt.get('unnamed_reading')}")
        out.append(
            f"[РЕЕСТР ЧИТАТЕЛЕЙ · СЛЕПОТА СОСЕДА] зовов, не разрешимых "
            f"статикой, у соседа {cnt.get('neighbour_dynamic_unresolved')}; "
            f"файлов ввоза не прочитано {cnt.get('import_files_unreadable')} "
            f"— это ЧИСЛА, а не ноль зовущих")
        for item in (completeness.get("declared_unseen") or []):
            out.append(
                f"[РЕЕСТР ЧИТАТЕЛЕЙ · СОСЕД НЕ ВИДИТ] `{item.get('key')}` "
                f"({item.get('path')}): {item.get('reason')} · поверхностью "
                f"ввоза виден: {item.get('seen_by_import_surface')}")
        for item in (completeness.get("findings") or [])[:max_rows]:
            out.append(
                f"[РЕЕСТР ЧИТАТЕЛЕЙ · НАХОДКА {item.get('kind')}] "
                f"{item.get('file')}:{item.get('line')} "
                f"(область {item.get('scope')}, канал {item.get('channel')}, "
                f"чисел {item.get('numbers')}) — {item.get('why')}")
        for item in (completeness.get("unreadable") or [])[:max_rows]:
            out.append(f"[РЕЕСТР ЧИТАТЕЛЕЙ · НЕ ПРОЧИТАНО] {item.get('file')}: "
                       f"{item.get('unreadable')}")
        for blind in (completeness.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    surface = doc.get("renamed_copy_surface") or []
    out.append(
        f"[ГРАНИЦА ПРАВИЛА ИМЕНИ] сторожей, читающих состояние репозитория и не "
        f"упоминающих дерево-предмет ни разу: {len(surface)} — у них копия своя "
        f"ПО ПОСТРОЕНИЮ; это доказанный МИНИМУМ переименованных копий, не потолок"
        + (f"; напр. {', '.join(surface[:3])}" if surface else ""))
    out.append("НЕ ДОКЛАДЫВАЕТ: вредит ли найденная копия сегодня; общее ли "
               "происхождение у совпавшего значения; является ли "
               "`subject_unproven` совпадением — свидетель односторонний")
    return out


def format_report(doc: dict, *, max_rows: int = 5) -> List[str]:
    """Отрисовка для шага 0-офис. Второй копии правила отрисовки здесь НЕТ:
    ветка офиса делегирует сюда, а эта функция — в ``report``."""
    lines = report(doc, max_rows=max_rows)
    if str(doc.get("status")) == "FINDING":
        lines[0] = f"⚠️ {lines[0]}"
    return lines


def run(root: str | Path = _ROOT, *, dest: Optional[Path] = None,
        data_dir: Optional[Path] = None, write: bool = True,
        now: Optional[dt.datetime] = None) -> dict:
    """Один прогон переписи для ступени моста.

    **Гейта такта здесь нет, и это замер, а не поблажка.** Зов есть разбор AST
    в одном процессе; цена названа в ADR-417. Недельный такт не купил бы
    ничего, а завёл бы ровно ту вторую копию правила о сроке, которую сосед
    (`tact_gate_census`) и ищет.
    """
    root = Path(root)
    target = (Path(dest) if dest is not None
              else (Path(data_dir) if data_dir is not None else root / "data") / ARTIFACT)
    try:
        # Журнал зонда лежит В ДЕРЕВЕ (рядом с кодом), а не в `data/`: он
        # есть замер исходников, и `data_dir` его не касается.
        doc = measure(root, now=now, probe_ledger=root / PROBE_LEDGER)
    except NotMeasured as exc:
        doc = {
            "generated_at": (now or _utcnow()).isoformat(),
            "generated_by": PRODUCER,
            "invoked_by": call_provenance(tree_root=root),
            "status": "UNMEASURED",
            "reason": str(exc),
        }
    if write:
        atomic_save(doc, str(target))
    return {"measured": doc.get("status") != "UNMEASURED", "doc": doc,
            "artifact": str(target)}


def main(argv: Optional[List[str]] = None) -> int:
    ap = argparse.ArgumentParser(
        description="перепись «одно правило — две копии»: исполнитель против сторожа (G41 п. 1)")
    ap.add_argument("--root", default=str(_ROOT))
    ap.add_argument("--out", default=None)
    ap.add_argument("--no-write", action="store_true")
    args = ap.parse_args(argv)

    outcome = run(Path(args.root),
                  dest=Path(args.out) if args.out else None,
                  write=not args.no_write)
    doc = outcome["doc"]
    for line in report(doc):
        print(line)
    return {"UNMEASURED": 2, "FINDING": 1}.get(str(doc.get("status")), 0)


if __name__ == "__main__":
    raise SystemExit(main())
